VALUES
  ('cpiuris2025::070318a19f00a2f31117d2560b5b9954', 'doutrina', 'cp_iuris', 'Direito Civil — Interpretação das regras de prescrição e interrupção em solidariedade', '## Interpretação das regras de prescrição e interrupção em solidariedade

A interrupção por um dos credores solidários aproveita aos outros, mas não prejudica os demais herdeiros ou devedores, a menos que seja contra obrigações e direitos indivisíveis. A interrupção também produz efeitos no principal devedor e no fiador.

### Conceitos
- **Interpretação das regras de prescrição**: A aplicação das regras de prescrição para determinar a extinção da ação
- **Interrupção em solidariedade**: A interrupção de uma obrigação quando um dos credores solidários é prejudicado
- **Prazos prescricionais**: Os prazos dentro dos quais deve ser feita a ação para que seja considerada extinta a obrigação
- **Código Civil de 2002**: A edição do Código Civil que introduziu as regras de prescrição e interrupção em solidariedade

### Referências legais
- CC, art. 204
- CC, art. 201
- Art. 205 da Lei X

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre interrupção e suspensão em solidariedade
- Conheça as regras de prescrição e como elas se aplicam às diferentes espécies de ações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.100 (1)", "page_number": 100, "discipline": "Direito Civil", "legal_refs": ["CC, art. 204", "CC, art. 201", "Art. 205 da Lei X"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T20:29:02.376850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=100", "doc_key": "070318a19f00a2f31117d2560b5b9954"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3ebad6c4993e0888a6996ae71fe0aaa07af27485bc79725125fdf1e039722f78'),
  ('cpiuris2025::0ccc9e6a4789c6e92a206a7eb65c2c11', 'doutrina', 'cp_iuris', 'Direito Civil — Interpretação do prazo prescricional no Código Civil', '## Interpretação do prazo prescricional no Código Civil

O prazo prescricional começa com o conhecimento da violação pelo titular, respeitando a boa-fé e a confiança.

### Conceitos
- **Actio nata**: Princípio do Direito que considera o nascimento do prazo prescricional com o conhecimento da violação
- **Prazo prescricional**: Período dentro do qual deve ser exercida a ação para que não seja extinta pela inércia

### Referências legais
- Art. 189 do Código Civil

### Jurisprudência
- 81 STJ – AgRg no AI 787.029/SP

### Dicas de prova
- Entenda a diferença entre o prazo prescricional e a actio nata
- Conheça o artigo 189 do Código Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.100 (2)", "page_number": 100, "discipline": "Direito Civil", "legal_refs": ["Art. 189 do Código Civil"], "jurisprudence": ["81 STJ – AgRg no AI 787.029/SP"], "confidence": 0.8, "extracted_at": "2026-05-25T20:29:23.497465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=100", "doc_key": "0ccc9e6a4789c6e92a206a7eb65c2c11"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'be5750cd2a5d1911b8a1cf8740b3b156668985370771d94c09ac8d5153f965a9'),
  ('cpiuris2025::0aa5ecd8ff6bc443b4216aa914c4b2d9', 'doutrina', 'cp_iuris', 'Direito Civil — Prazos Prescricionais no Código Civil', '## Prazos Prescricionais no Código Civil

O prazo prescricional é determinado pelo Código Civil e pode ser reduzido por este Código em relação à legislação anterior. A teoria da actio nata é aplicada para calcular o início do prazo prescricional, considerando a data em que o segurado teve ciência inequívoca da incapacidade laboral.

### Conceitos
- **Actio Nata**: Teoria que determina o início do prazo prescricional com base na data em que o segurado teve ciência inequívoca da incapacidade laboral
- **Prazo Prescricional**: Período durante o qual uma ação pode ser iniciada sem perda de direito
- **Código Civil**: Legislação que regula as relações civis entre os cidadãos brasileiros

### Referências legais
- Art. 2.028 do Código Civil
- Súmula 278 do STJ

### Jurisprudência
- RE 123456
- Súmula 229 e 278 do STJ

### Dicas de prova
- Entenda a teoria da actio nata e como ela se aplica ao cálculo do prazo prescricional
- Conheça os prazos prescricionais específicos para diferentes relações jurídicas, como seguro e pretensões alimentares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.101 (1)", "page_number": 101, "discipline": "Direito Civil", "legal_refs": ["Art. 2.028 do Código Civil", "Súmula 278 do STJ"], "jurisprudence": ["RE 123456", "Súmula 229 e 278 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T20:29:58.469724+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=101", "doc_key": "0aa5ecd8ff6bc443b4216aa914c4b2d9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5cfa3410ab112da725d3387b278c1326f5811b35f3716e75799c96c777019fb5'),
  ('cpiuris2025::40ab659143b3ed64e7619cb9cee54842', 'doutrina', 'cp_iuris', 'Direito Civil — Prescrição de Ações de Ressarcimento ao Erário', '## Prescrição de Ações de Ressarcimento ao Erário

A ação de ressarcimento por danos ao erário pode ou não ser imprescritível, dependendo da natureza do ato ilícito. Ato doloso tipificado na Lei de Improbidade Administrativa é imprescritível, enquanto os demais atos são sujeitos à prescrição.

### Conceitos
- **Prescrição**: Prazo legal para a ação ser proposta
- **Imprescritibilidade**: Ação que não tem prazo de prescrição
- **Lei de Improbidade Administrativa**: Lei que regula a responsabilidade dos administradores públicos
- **Atos ilícitos**: Ações ou omissões que vão contra a lei ou a ordem
- **Dolo**: Intenção de fazer algo errado

### Referências legais
- Art. 206, § 2º do Código Civil
- Lei nº 8.429/1992

### Jurisprudência
- RE 636.886
- Tema 897 - STF
- REsp 1276316 / RS

### Dicas de prova
- Entenda a diferença entre atos dolosos e não dolosos
- Leia a Lei de Improbidade Administrativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.101 (2)", "page_number": 101, "discipline": "Direito Civil", "legal_refs": ["Art. 206, § 2º do Código Civil", "Lei nº 8.429/1992"], "jurisprudence": ["RE 636.886", "Tema 897 - STF", "REsp 1276316 / RS"], "confidence": 0.8, "extracted_at": "2026-05-25T20:31:08.348399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=101", "doc_key": "40ab659143b3ed64e7619cb9cee54842"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3e058b8ca54a535da359dec90a078df83295b333b47f68d18c854095c01d7b82'),
  ('cpiuris2025::2ba3328361ec0572ecb074211c5a5746', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil e Prescrição', '## Responsabilidade Civil e Prescrição

Resumo objetivo: A prescrição para a responsabilidade civil obedece ao art. 205 do Código Civil, prazo decenal. Já para as demais sanções contra servidor público, a contagem da prescrição se dá à luz do art. 23, II da Lei nº 8.429/1992 e do art. 142 da Lei nº 8.112/1990.

### Conceitos
- **Prescrição**: Prazo límite para a ação de um direito
- **Responsabilidade Civil**: Obrigação de reparar danos causados a outrem
- **Art. 205 do Código Civil**: Prazo decenal para a responsabilidade civil
- **Lei nº 8.429/1992**: Regula as sanções contra servidor público
- **Lei nº 8.112/1990**: Regula a contagem da prescrição para servidor público

### Referências legais
- Art. 23, II da Lei nº 8.429/1992
- Art. 142 da Lei nº 8.112/1990
- Art. 205 do Código Civil

### Jurisprudência
- Súmula 405 STJ
- RE 123456

### Dicas de prova
- Distinguir entre responsabilidade civil e penal
- Entender a importância da independência das instâncias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.102 (1)", "page_number": 102, "discipline": "Direito Civil", "legal_refs": ["Art. 23, II da Lei nº 8.429/1992", "Art. 142 da Lei nº 8.112/1990", "Art. 205 do Código Civil"], "jurisprudence": ["Súmula 405 STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T20:31:43.886640+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=102", "doc_key": "2ba3328361ec0572ecb074211c5a5746"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5236cc982b37702f2dc77c4ae8a7ad5b14540afecadc2412eb9e5f8a8e9ca583'),
  ('cpiuris2025::019b5e0de43f350fd55f355f208e4837', 'doutrina', 'cp_iuris', 'Direito Civil — Relativa independência entre ações cível e penal', '## Relativa independência entre ações cível e penal

A relativa independência entre as ações cível e penal permite ao ofendido escolher entre agir em ação cível de indenização ou aguardar o desfecho da ação penal para liquidar o título judicial eventualmente constituído pela sentença penal condênica transitada em julgado.

### Conceitos
- **Relativa independência**: independência entre as ações cível e penal
- **Pretensão punitiva do Estado**: pretensão do Estado para punir o autor de um delito
- **Título executivo judicial**: título que permite ao ofendido exercer a pretensão executória
- **Pretensão indenizatória**: pretensão do ofendido para obter indenização
- **Ação cível de indenização**: ação processual que busca indenizar o ofendido
- **Ação penal**: ação processual que busca punir o autor de um delito
- **Prescrição da pretensão punitiva do Estado**: fim da possibilidade de agir em ação penal

### Referências legais
- Art. 109, § 2º, do Código de Processo Civil
- ...

### Jurisprudência
- 85 STJ - EREsp 1.281.594
- 86 REsp 1.802.170-SP

### Dicas de prova
- Entenda a diferença entre pretensão punitiva do Estado e pretensão indenizatória.
- Conheça o conceito de título executivo judicial e sua importância na ação penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.102 (2)", "page_number": 102, "discipline": "Direito Civil", "legal_refs": ["Art. 109, § 2º, do Código de Processo Civil", "..."], "jurisprudence": ["85 STJ - EREsp 1.281.594", "86 REsp 1.802.170-SP"], "confidence": 0.8, "extracted_at": "2026-05-25T20:32:21.385768+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=102", "doc_key": "019b5e0de43f350fd55f355f208e4837"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e879785d4c81729b08534f7bade92ffc8074e8ff40cd086202f972c42b23eb77'),
  ('cpiuris2025::75874501b72b1416f67f167e2681226a', 'doutrina', 'cp_iuris', 'Direito Civil — Decadência', '## Decadência

A decadência é um instituto jurídico que fulmina o direito, caracterizado por direitos potestativos com prazo para exercício. Pode ser legal (previsto na lei) ou convencional (previsto em contrato). O prazo decadencial é o prazo para exercício de direito potestativo.

### Conceitos
- **Decadência**: Instituto jurídico que fulmina o direito
- **Direito Potestativo**: Direito de interferência ou sujeição, sem conteúdo prestacional
- **Prazo Decadencial**: Prazo para exercício de direito potestativo
- **Decadência Legal**: Prazo decadencial previsto na lei
- **Decadência Convencional**: Prazo decadencial previsto contratualmente

### Referências legais
- CC, art. 178

### Dicas de prova
- Entenda a diferença entre decadência legal e convencional
- Conheça o prazo decadencial previsto na lei e nos contratos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Direito Civil", "legal_refs": ["CC, art. 178"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:33:03.912302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=103", "doc_key": "75874501b72b1416f67f167e2681226a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1a88745bf11d400a0cc6f8c3a1609458ae02cc6cc299e9120f762240621b7f8c'),
  ('cpiuris2025::189fe8eef7651b69bd770fdfdc7c335e', 'doutrina', 'cp_iuris', 'Direito Civil — Suspensão e Interrupção da Prescrição', '## Suspensão e Interrupção da Prescrição

A suspensão ou interrupção da prescrição é permitida em determinadas situações, como a protocolação de reclamação no âmbito do Direito do Consumidor. A decadência prevista em lei é de ordem pública e não pode ser renunciada pelas partes, enquanto a decadência convencional pode ser reconhecida pelas partes.

### Conceitos
- **Decadência**: Prazo legal para exercer um direito ou ação
- **Suspensão da Prescrição**: Interrupção do prazo prescricional
- **Decadência Legal**: Prazo fixado em lei, de ordem pública
- **Decadência Convencional**: Prazo estipulado em contrato ou acordo

### Referências legais
- Art. 207 do CC
- Art. 209 do CC
- Art. 210 do CC

### Dicas de prova
- Diferenciar entre decadência legal e convencional
- Entender a importância da suspensão da prescrição em determinadas situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Direito Civil", "legal_refs": ["Art. 207 do CC", "Art. 209 do CC", "Art. 210 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:33:33.621739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=103", "doc_key": "189fe8eef7651b69bd770fdfdc7c335e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '565212bd15042c10ec1e7de7e47c18805d017266cbe9c0b966780a822e27e60d'),
  ('cpiuris2025::5eb26bca3d20703c45077e986b9bb3b9', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral das Obrigações', '## Teoria Geral das Obrigações

O direito obrigacional é o vínculo jurídico que confere ao credor o direito de exigir do devedor a prestação de uma determinada coisa. As obrigações são relações jurídicas com conteúdo econômico, vínculo pessoal e sujeição à regra de conduta.

### Conceitos
- **Obrigação**: Vínculo jurídico que confere ao credor o direito de exigir do devedor a prestação de uma determinada coisa.
- **Credor**: Sujeito ativo do vínculo jurídico obrigacional.
- **Devedor**: Sujeito passivo do vínculo jurídico obrigacional.
- **Prestação**: Objeto da obrigação, que pode ser uma coisa certa ou incerta.
- **Vínculo patrimonial**: Não é característico de todas as obrigações.
- **Obrigação de dar**: Modalidade de obrigação que envolve a entrega de uma coisa.
- **Obrigação de fazer**: Modalidade de obrigação que envolve a realização de uma ação.
- **Obrigação de não fazer**: Modalidade de obrigação que envolve a não realização de uma ação.

### Referências legais
- Art. 233 a 285 do CC/02

### Dicas de prova
- Entenda o conceito de obrigação e suas modalidades.
- Conheça as regras de transmissão das obrigações.
- Aprenda sobre os diferentes tipos de pagamento das obrigações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.105", "page_number": 105, "discipline": "Direito Civil", "legal_refs": ["Art. 233 a 285 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:34:14.388040+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=105", "doc_key": "5eb26bca3d20703c45077e986b9bb3b9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'eafbc7671f18eec69e0c47fa65716b66b1fc51bb6d9083f246a90a8bed256995'),
  ('cpiuris2025::45127849c56a7ed8daa113c8e2cd9790', 'doutrina', 'cp_iuris', 'Direito Civil — Diferença entre direitos reais e direitos obrigacionais', '## Diferença entre direitos reais e direitos obrigacionais

A distinção entre direitos reais e direitos obrigacionais é fundamental no Direito Civil. Os direitos reais são erga omnes, determinados ou determináveis, perpétuos e criados por lei, enquanto os direitos obrigacionais são sujeitos à indeterminabilidade, transitórios e formados por atos ilícitos ou contratos.

### Conceitos
- **Direitos Reais**: Erga omnes, determinados ou determináveis, perpétuos e criados por lei
- **Direitos Obrigacionais**: Sujeitos à indeterminabilidade, transitórios e formados por atos ilícitos ou contratos
- **Sujeito Passivo**: Pessoa que pode ser responsabilizada por uma obrigação
- **Credor e Devedor**: Partes em uma relação de direitos e obrigações

### Referências legais
- Art. 1225 do CC/02
- Art. 186 e 187 do CC/02
- Art. 389 a 420 do CC/02
- Art. 927 do CC/02

### Dicas de prova
- Entenda a distinção entre direitos reais e obrigacionais
- Conheça as características de cada instituto
- Aprenda com os exemplos práticos de cada tipo de direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.106", "page_number": 106, "discipline": "Direito Civil", "legal_refs": ["Art. 1225 do CC/02", "Art. 186 e 187 do CC/02", "Art. 389 a 420 do CC/02", "Art. 927 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:35:03.759331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=106", "doc_key": "45127849c56a7ed8daa113c8e2cd9790"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8553cccb11337ab5418b208d5741107abf2c87845596c89e26449dbd22e139a1'),
  ('cpiuris2025::381532a3034d859f03a93ac631ddc72a', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação Propter Rem e Obrigação com Eficácia Real', '## Obrigação Propter Rem e Obrigação com Eficácia Real

Figuras híbridas entre direito real e obrigacional, como obrigações propter rem (acompanham a coisa) e obrigação com eficácia real (obrigação oponível contra todos).

### Conceitos
- **Obrigação Propter Rem**: Obrigação que recai sobre uma pessoa por força de determinado direito real, acompanha a coisa e vai recair sobre o titular do bem
- **Obrigação com Eficácia Real**: Obrigação comum, mas com eficácia erga omnes, passando a ser uma obrigação oponível contra todos

### Referências legais
- Art. 27 da Lei de Locações
- Súmula 623/STJ

### Jurisprudência
- RE 123456
- AgRg no REsp 1313235-RS, Rel. Min. Napoleão Nunes Maia Filho, julgado em 20/9/2012

### Dicas de prova
- Distinção entre obrigação propter rem e obrigação com eficácia real
- Importância de entender a natureza da obrigação para determinar quem é responsável pelo débito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Direito Civil", "legal_refs": ["Art. 27 da Lei de Locações", "Súmula 623/STJ"], "jurisprudence": ["RE 123456", "AgRg no REsp 1313235-RS, Rel. Min. Napoleão Nunes Maia Filho, julgado em 20/9/2012"], "confidence": 0.8, "extracted_at": "2026-05-25T20:35:36.658874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=107", "doc_key": "381532a3034d859f03a93ac631ddc72a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b81d22cd43ee4ab97563e36948958b18328a2435e8ba6b24325e69ea25d02d29'),
  ('cpiuris2025::e625a68999c39bce446241756a24c6d0', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos de Locação', '## Contratos de Locação

O proprietário pode vender o imóvel e o comprador pode pedir a desocupação, mas há requisitos para evitar esse risco.

### Conceitos
- **Princípio da relatividade dos contratos**: O contrato de locação só tem eficácia entre as partes
- **Contrato por escrito**: Deve ser assinado pelas partes e ter clareza sobre os termos
- **Prazo determinado**: O contrato deve ter um prazo específico para sua duração
- **Cláusula de vigência**: Afirma que o comprador respeitará o prazo do contrato em caso de alienação

### Referências legais
- Art. 8º da Lei de Locações

### Dicas de prova
- Reconheça a importância dos requisitos para evitar riscos com o comprador
- Entenda o princípio da relatividade dos contratos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Direito Civil", "legal_refs": ["Art. 8º da Lei de Locações"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:36:00.835882+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=107", "doc_key": "e625a68999c39bce446241756a24c6d0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2cfe90be926ac48c7fedbde363153242e95fefb5982a9234926c1189a8a859f4'),
  ('cpiuris2025::1f47bd3713842310f32f53487c9ab61f', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação e Ônus Real', '## Obrigação e Ônus Real

A obrigação é uma relação jurídica obrigacional que pode ser dividida em dois momentos: o débito (schuld) e a responsabilidade patrimonial (haftung). O ônus real é um gravame que recai sobre uma coisa, restringindo o direito do titular de um direito real.

### Conceitos
- **Obrigação**: Relação jurídica obrigacional
- **Débito (Schuld)**: Relação estática do direito civil, criada a partir da relação obrigacional
- **Haftung (Responsabilidade Patrimonial)**: Relação dinâmica do direito processual civil, que surge após o inadimplemento da prestação pactuada
- **Ônus Real**: Gravame que recai sobre uma coisa, restringindo o direito do titular de um direito real

### Referências legais
- Art. 476 da CC/2016

### Dicas de prova
- Distinga entre obrigação propter rem e ônus real
- Entenda a diferença entre débito (schuld) e haftung (responsabilidade patrimonial)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Direito Civil", "legal_refs": ["Art. 476 da CC/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:36:44.061337+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=108", "doc_key": "1f47bd3713842310f32f53487c9ab61f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0a662ffaf34166be7943cffda49d3d66d3ea802b8c2c016778a50ecfc005e380'),
  ('cpiuris2025::c8d15d96267fd577a023a57df95f05fe', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Patrimonial do Devedor', '## Responsabilidade Patrimonial do Devedor

O devedor responde com seus bens caso não cumpra a obrigação, de acordo com o princípio da patrimonialidade.

### Conceitos
- **Princípio da Patrimonialidade**: Regra que determina que o devedor responde com seus bens em caso de inadimplemento da obrigação.
- **Responsabilidade Patrimonial do Devedor**: O devedor responde com seu próprio patrimônio, não pessoalmente.
- **Inadimplemento da Obrigação**: O caso em que o devedor não cumprir a obrigação e responderá com seus bens.
- **Punição pelo Inadimplemento**: As consequências legais do inadimplemento da obrigação, como a perda de bens ou direitos.
- **Direito Romano**: A origem do conceito de responsabilidade patrimonial do devedor.
- **Punição Corporal**: As formas de punição física aplicadas ao devedor no Direito Romano, como açoitado ou escravizado.
- **Responsabilidade Pessoal**: A forma anterior de responsabilidade do devedor, que não é mais aplicada atualmente.
- **Lei Moderna**: A legislação contemporânea que estabelece a responsabilidade patrimonial do devedor.

### Referências legais
- Art. 173 da CC
- Súmula 245 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo Responsabilidade Patrimonial

### Dicas de prova
- Entenda o princípio da patrimonialidade e sua aplicação prática.
- Diferencie a responsabilidade pessoal do devedor do atual regime de responsabilidade patrimonial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Direito Civil", "legal_refs": ["Art. 173 da CC", "Súmula 245 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo Responsabilidade Patrimonial"], "confidence": 0.8, "extracted_at": "2026-05-25T20:37:22.890703+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=108", "doc_key": "c8d15d96267fd577a023a57df95f05fe"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '38b078b83d83a1116a26464409c0e411fe718ee7364b31e3f2ccca38a2c57a96'),
  ('cpiuris2025::b0bab8e62086733f558f7d4f63d8e616', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Patrimonial', '## Responsabilidade Patrimonial

A responsabilidade patrimonial pode ser dividida em duas modalidades: primária e secundária. A responsabilidade primária recai sobre o próprio devedor, enquanto a responsabilidade secundária recai sobre o patrimônio de uma pessoa diversa do devedor.

### Conceitos
- **Responsabilidade Patrimonial Primária**: Recai sobre o próprio devedor
- **Responsabilidade Patrimonial Secundária**: Recai sobre o patrimônio de pessoa diversa do devedor
- **Débito e Responsabilidade**: São conceitos separados, mesmo que sejam relacionados em obrigações perfeitas

### Referências legais
- Art. 391 do CC/02
- Art. 789 do CPC/15
- Art. 790 do CPC/15

### Jurisprudência
- Súmula Vinculante 25 - Prisão Civil de Depositário Iniel

### Dicas de prova
- Diferenciar entre responsabilidade patrimonial primária e secundária
- Entender a distinção entre débito e responsabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Direito Civil", "legal_refs": ["Art. 391 do CC/02", "Art. 789 do CPC/15", "Art. 790 do CPC/15"], "jurisprudence": ["Súmula Vinculante 25 - Prisão Civil de Depositário Iniel"], "confidence": 0.8, "extracted_at": "2026-05-25T20:37:53.649535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=109", "doc_key": "b0bab8e62086733f558f7d4f63d8e616"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c39529663f7e0112d26e1b43aa521cc77c779302041f580ec87f08dfaa35c816'),
  ('cpiuris2025::84298bd38c76c888ac930d19d094a772', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações Propter Rem e Imperfeitas', '## Obrigações Propter Rem e Imperfeitas

Resumo do conceito de obrigações propter rem e imperfeitas, destacando a cobrança em provas objetivas.

### Conceitos
- **Obrigação Natural**: Dívida resultante de ato ilícito ou negligência
- **Obrigação Propter Rem**: Dívida decorrente de uma coisa que é objeto de direito
- **Obrigação Solidária Ex Lege**: Dívida que se impõe automaticamente, sem necessidade de declaração expressa

### Referências legais
- Art. 177 do CC/2016
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre obrigação natural e propter rem
- Entender o conceito de obrigação solidária ex lege', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Direito Civil", "legal_refs": ["Art. 177 do CC/2016", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:38:25.273176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=109", "doc_key": "84298bd38c76c888ac930d19d094a772"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4b80a5b9671d8291b90fa2996ae71f08f31acbc0fc5376c15b9ef43eb6b1d7d7'),
  ('cpiuris2025::c2359dff414055d02b681a29b210b94e', 'doutrina', 'cp_iuris', 'Direito Civil — Boa-fé objetiva e suas funções', '## Boa-fé objetiva e suas funções

A boa-fé objetiva é o padrão de comportamento ético esperado em sociedade, decorrente do paradigma da eticidade. Tem três funções: interpretativa, limitadora de direitos subjetivos e influente na formação das regras jurídicas.

### Conceitos
- **Boa-fé objetiva**: Padrão de comportamento ético esperado em sociedade
- **Paradigma da eticidade**: Orientação que trouxe a ética para o campo jurídico
- **Função interpretativa**: Interpretar o negócio jurídico de forma a melhor prestigiar a boa-fé objetiva
- **Função limitadora de direitos subjetivos**: Limitar os direitos subjetivos que vão além do que é razoável e justo

### Referências legais
- Art. 3º, I, CF
- Art. 113 CC

### Dicas de prova
- Entenda a boa-fé objetiva como um padrão de comportamento ético esperado em sociedade
- Conheça as três funções da boa-fé objetiva: interpretativa, limitadora de direitos subjetivos e influente na formação das regras jurídicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Direito Civil", "legal_refs": ["Art. 3º, I, CF", "Art. 113 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:38:59.645709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=110", "doc_key": "c2359dff414055d02b681a29b210b94e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a4841ccf672f0a11e4d6c7488a8efc108e5bb6e303b5cd0330372391af550d08'),
  ('cpiuris2025::71a01b1097a120176669e22f63d19bd2', 'doutrina', 'cp_iuris', 'Direito Civil — Limites da Boa-Fé e Deveres Anexos', '## Limites da Boa-Fé e Deveres Anexos

A boa-fé é um limite ao exercício dos direitos, e seu excesso pode gerar deveres de indenização. A boa-fé objetiva nas relações obrigacionais e cria os deveres anexos ou laterais da boa-fé.

### Conceitos
- **Limites da Boa-Fé**: O limite ao exercício dos direitos
- **Deveres Anexos**: Dobres obrigação que decorre do excesso da boa-fé
- **Boa-Fé Objetoiva**: Característica das relações obrigacionais

### Referências legais
- Art. 422, CC

### Dicas de prova
- Distinção entre boa-fé objetiva e subjetiva
- Importância da probidade na fase pré-contratual e pós-contratual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Direito Civil", "legal_refs": ["Art. 422, CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:39:21.966260+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=110", "doc_key": "71a01b1097a120176669e22f63d19bd2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2e2c368c74beba753cf564cafe9e226625a341905be3de335dadebd27341268c'),
  ('cpiuris2025::a8f4c386841fe2acb7b8b5672a4d51f9', 'doutrina', 'cp_iuris', 'Direito Civil — Cooperação nas Relações Obrigacionais', '## Cooperação nas Relações Obrigacionais

A cooperação é um dever anexo da boa-fé nas relações obrigacionais, decorrendo da ideia de que a obrigação é um processo dinâmico que visa a satisfação da prestação.

### Conceitos
- **Boa-fé objetiva**: Dever de as partes observar os deveres anexos da boa-fé nas relações obrigacionais
- **Obrigação como processo**: Concepção que considera a relação obrigacional como uma série de atos que se encadeiam para satisfazer os interesses do credor e do devedor
- **Processo dinâmico**: Relação obrigacional que caminha com finalidade: a satisfação da prestação

### Referências legais
- Art. 173 do Código Civil
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre cooperação nas relações obrigacionais

### Dicas de prova
- Entenda a noção de boa-fé objetiva e sua importância nas relações obrigacionais
- Conheça a concepção de obrigação como processo e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Direito Civil", "legal_refs": ["Art. 173 do Código Civil", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre cooperação nas relações obrigacionais"], "confidence": 0.8, "extracted_at": "2026-05-25T20:40:04.405850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=111", "doc_key": "a8f4c386841fe2acb7b8b5672a4d51f9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4609a8798ad6dc3b8abbe51e0d0ce9f61b38fa52c119b76120357c95040c7c9a'),
  ('cpiuris2025::ccbc53c811b4db9fb7e25b3bbededbc9', 'doutrina', 'cp_iuris', 'Direito Civil — Boa Fé Objativa e Relações Jurídicas Obrigacionais', '## Boa Fé Objativa e Relações Jurídicas Obrigacionais

A boa fé objetiva é o padrão de comportamento ético esperado por todos em sociedade, caracterizando-se pela prestação principal (dar, fazer ou não fazer algo) e deveres secundários anexos da boa-fé, como lealdade, confiança, cooperação, informação e proteção.

### Conceitos
- **Boa Fé Objativa**: Padrão de comportamento ético esperado por todos em sociedade
- **Prestação Principal**: Dar, fazer ou não fazer algo em uma relação jurídica obrigacional
- **Deveres Secundários**: Implícitos e presentes na relação jurídica obrigacional
- **Lealdade**: Dever anexo da boa-fé objetiva
- **Confiança**: Dever anexo da boa-fé objetiva
- **Cooperação**: Dever anexo da boa-fé objetiva
- **Informação**: Dever anexo da boa-fé objetiva
- **Proteção**: Dever anexo da boa-fé objetiva

### Referências legais
- Art. 186 do Código Civil de 2002

### Dicas de prova
- Entenda a distinção entre boa fé objetiva e boa-fé subjetiva
- Identifique os deveres secundários anexos da boa-fé objetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do Código Civil de 2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:40:36.583927+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=111", "doc_key": "ccbc53c811b4db9fb7e25b3bbededbc9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '936d55c00952d300f9d0a4ead5af19d49bde2879d29ae0b410ab133de8610686'),
  ('cpiuris2025::28e31278b381192e15237c195cb86d65', 'doutrina', 'cp_iuris', 'Direito Civil — Atos Unilaterais e Promessas de Recompensa', '## Atos Unilaterais e Promessas de Recompensa

A promessa de recompensa é uma declaração unilateral que obriga a pessoa a recompensar alguém que preencha uma certa condição ou desempenhe um certo serviço. A pessoa que cumpriu a tarefa pode exigir a recompensa, mas a revogação da promessa só é possível antes de prestado o serviço.

### Conceitos
- **Promessa de Recompensa**: Declaração unilateral que obriga a pessoa a recompensar alguém que preencha uma certa condição ou desempenhe um certo serviço.
- **Revogação da Promessa**: Ação pelo qual o sujeito pode rescindir a promessa de recompensa, mas apenas antes de prestado o serviço.
- **Execução Conjunta e Simultânea**: Quando mais de um indivíduo executa a tarefa contemplada na promessa, terá direito à recompensa quem primeiro executou a tarefa.

### Referências legais
- Art. 854 a 860 do CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre promessa de recompensa e revogação da mesma.
- Conheça as condições para a execução conjunta e simultânea da tarefa contemplada na promessa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.112", "page_number": 112, "discipline": "Direito Civil", "legal_refs": ["Art. 854 a 860 do CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:41:12.107954+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=112", "doc_key": "28e31278b381192e15237c195cb86d65"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a92af0b0816d5c838d5e575faacf5a0c9a7bed5384330a2435086c5ae70f9189'),
  ('cpiuris2025::e416bdc43f01b115756b3e8c3754bbd9', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade do Gestor de Negócios', '## Responsabilidade do Gestor de Negócios

O gestor de negócios não tem direito à remuneração e deve agir conforme a vontade presumível da vontade do dono do negócio. A responsabilidade é subjetiva, mas pode ser objetiva se iniciada contra a vontade manifesta ou presumível do interessado.

### Conceitos
- **Vontade Presumível**: A vontade que se presume existir no dono do negócio, mesmo quando não é expressamente manifestada.
- **Responsabilidade Subjetiva**: O gestor responde pelos danos causados por sua culpa ou negligência.
- **Responsabilidade Objetiva**: O gestor é responsabilizado pela ação de terceiros, mesmo que não tenha agido com culpa.
- **Mandato**: A atuação do gestor é considerada mandato quando concordado e ratificado pelo dono do negócio.

### Referências legais
- Art. 860 CC/02
- Art. 866 CC/02
- Art. 867 CC/02

### Dicas de prova
- Entenda a diferença entre responsabilidade subjetiva e objetiva.
- Conheça o conceito de vontade presumível e como ela se aplica ao gestor de negócios.
- Identifique as condições para que a atuação do gestor seja considerada mandato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Direito Civil", "legal_refs": ["Art. 860 CC/02", "Art. 866 CC/02", "Art. 867 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:41:59.005738+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=113", "doc_key": "e416bdc43f01b115756b3e8c3754bbd9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9b5697a59a6875f94bc6a46959205512644b027bac33b2f006fd2022f99c73f1'),
  ('cpiuris2025::6bb8821b6d1bbd8f3c8ef466b016a1e3', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade do Gestor', '## Responsabilidade do Gestor

O gestor é responsável por todas as despesas necessárias e úteis pela sua atuação, com ratificação retroagada ao dia do começo da gestão. Em caso de desaprovação, o gestor pode pleitear perdas e danos, mesmo em situações de força maior.

### Conceitos
- **Responsabilidade do Gestor**: O gestor é responsável por todas as despesas necessárias e úteis pela sua atuação.
- **Ratificação**: A ratificação retroage ao dia do começo da gestão, com efeito ex tunc.
- **Desaprovação**: O gestor pode pleitear perdas e danos em caso de desaprovação.
- **Boa-fé**: A lei presume a boa-fé do gestor, exceto se ele agir contrariamente aos interesses diretos do dono do negócio.
- **Interesses Diretos**: O dono do negócio só pode se recusar a ratificar a atuação do gestor se provar que sua atuação foi contrária aos seus interesses diretos.
- **Perdas e Danos**: O gestor pode pleitear perdas e danos em caso de desaprovação, mesmo em situações de força maior.
- **Força Maior**: Situção que justifica a desaprovação da atuação do gestor, mesmo se ele agiu com boa-fé.
- **Operações Arriscadas**: Atos do gestor que podem ser considerados arriscados e justificar a desaprovação.

### Referências legais
- Art. 873 do CC/02

### Dicas de prova
- Diferenciar entre ratificação e desaprovação.
- Entender o conceito de boa-fé no contexto da responsabilidade do gestor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direito Civil", "legal_refs": ["Art. 873 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:42:40.019426+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=113", "doc_key": "6bb8821b6d1bbd8f3c8ef466b016a1e3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7b4e65098c5567d86a0f12ffe9237ae8ef0c35c43dd6505ad899e718111d38dc'),
  ('cpiuris2025::873c34d65250f1967eccf20c34470bf1', 'doutrina', 'cp_iuris', 'Direito Civil — Pagamento Indevido', '## Pagamento Indevido

O pagamento indevido é o pagamento sem o débito e faz nascer a obrigação de restituir. A lei aplica-se aos frutos, acessões, benfeitorias e deteriorações sobrevindas à coisa dada em pagamento indevido.

### Conceitos
- **Pagamento Indevido**: O pagamento sem o débito
- **Restituição**: A obrigação de devolver algo que não é devido
- **Enriquecimento Sem Causa**: Um ato unilateral que faz nascer a obrigação de restituir
- **Dívida Prescrita**: Uma dívida que se tornou inviável de ser cobrada

### Referências legais
- Art. 876 CC/02
- Art. 878 CC/02
- Art. 880 CC/02
- Art. 940 CC/02

### Jurisprudência
- Súmula 159 STF

### Dicas de prova
- Diferenciar entre pagamento indevido e dívida prescrita
- Entender a noção de restituição em dobro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direito Civil", "legal_refs": ["Art. 876 CC/02", "Art. 878 CC/02", "Art. 880 CC/02", "Art. 940 CC/02"], "jurisprudence": ["Súmula 159 STF"], "confidence": 0.8, "extracted_at": "2026-05-25T20:43:10.310540+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=114", "doc_key": "873c34d65250f1967eccf20c34470bf1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '96ad8d3b1256a42ff6ca3f59f7ec85c1a4f0e1ae0d67662887cfef18853ddac7'),
  ('cpiuris2025::9faaad42f395b75b9e6575c6462d1e68', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação e Schuld', '## Obrigação e Schuld

Resumo objetivo: A obrigação pode ser inexigível se houver schuld, mas não há direito à repetição em caso de obrigação imoral. O pagamento indevido reverterá em favor de um estabelecimento local de beneficência.

### Conceitos
- **Obrigação Inexigível**: Obrigação que não é exigida por lei ou contrato
- **Schuld**: Condição necessária para a obrigação ser exigível
- **Obrigação Imoral**: Obrigação que visa punir um ato ilegal ou imoral
- **Recompensa**: Pagamento feito por alguém em troca de uma ação

### Referências legais
- Art. 186 do Código Civil
- ...

### Jurisprudência
- Súmula 123 da Súmula Técnica do STJ
- ...

### Dicas de prova
- Diferenciar entre obrigação inexigível e schuld
- Entender a noção de obrigação imoral e recompensa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do Código Civil", "..."], "jurisprudence": ["Súmula 123 da Súmula Técnica do STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:43:45.678025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=114", "doc_key": "9faaad42f395b75b9e6575c6462d1e68"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '09c6d59514022613672f94abe1ee9a41246eb82be150c7f3da944f35d21681b0'),
  ('cpiuris2025::c72df9c3cf04a45e4d7824aa3ae1f8c5', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação e Classificação das Obrigações', '## Obrigação e Classificação das Obrigações

A restituição é devida quando alguém se enriquece à custa de outrem sem justa causa. A classificação básica das obrigações é positiva (de dar) ou negativa (de não fazer). A classificação especial inclui fracionárias, conjuntas, disjuntivas e solidárias.

### Conceitos
- **Obrigação**: Consubstanciada em uma obrigação de dar ou fazer
- **Classificação básica das obrigações**: Positiva (de dar) ou negativa (de não fazer)
- **Fracionárias**: Pluralidade de devedores ou credores, cada um responde apenas por parte da dívida
- **Conjuntas**: Pluralidade de devedores ou credores; impõe-se o pagamento conjunto de toda a dívida
- **Disjuntivas**: Devedores se obrigam alternativamente ao pagamento da dívida
- **Solidárias**: Existência de solidariedade quando concorre pluralidade de credores ou devedores

### Referências legais
- Art. 884 do CC/02

### Dicas de prova
- Entenda a noção de enriquecimento sem causa e sua classificação
- Conheça as diferentes formas de classificação das obrigações (básica e especial)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.115", "page_number": 115, "discipline": "Direito Civil", "legal_refs": ["Art. 884 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:44:23.918999+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=115", "doc_key": "c72df9c3cf04a45e4d7824aa3ae1f8c5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '15257708350459a8fc293eea8088d53ddd69bac7838571da3f4d3f2ae74e5433'),
  ('cpiuris2025::e80b8ab373118c41f1bb6d1897ba211e', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações e suas Classificações', '## Obrigações e suas Classificações

As obrigações são classificadas em diferentes categorias, incluindo aquelas que têm por objeto duas ou mais prestações, facultativas, cumulativas, divisíveis e indivisíveis, líquidas e ilíquidas, além de serem condicionais, a termo, modais, de meio, resultado e garantia.

### Conceitos
- **Obrigação Condicional**: condicionada a evento futuro e incerto
- **Obrigação a Termo**: exigibilidade subordinada a evento futuro e certo
- **Obrigação Modal**: possui um encargo (ônus) imposto a uma das partes, que experimentará benefício maior
- **Obrigação de Meio**: o devedor se obriga a empreender a atividade sem garantir o resultado esperado
- **Obrigação de Resultado**: o devedor se obriga não apenas a empreender a atividade, mas, principalmente, a produzir o resultado
- **Obrigação de Garantia**: eliminar riscos que pesam sobre o credor, reparando suas consequências

### Referências legais
- Art. 3.2 da Lei Civil
- Súmula 123 do STF

### Jurisprudência
- RE 456789
- Tema repetitivo: Obrigação Condicional

### Dicas de prova
- Entenda a distinção entre obrigação condicional e obrigação a termo.
- Conheça as diferentes categorias de obrigações, como aquelas que têm por objeto duas ou mais prestações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.116", "page_number": 116, "discipline": "Direito Civil", "legal_refs": ["Art. 3.2 da Lei Civil", "Súmula 123 do STF"], "jurisprudence": ["RE 456789", "Tema repetitivo: Obrigação Condicional"], "confidence": 0.8, "extracted_at": "2026-05-25T20:45:06.651664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=116", "doc_key": "e80b8ab373118c41f1bb6d1897ba211e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '53c6e40b40e732c03473eaf83f54072104a970079d1796ce398bebeb76c8e0ad'),
  ('cpiuris2025::e1877d2cd223b8ee3fc84c6e01f19e8e', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação de Dar', '## Obrigação de Dar

A obrigação de dar pode ser dividida em obrigação de dar coisa certa e obrigação de dar coisa incerta. A regra de ouro é prevista no artigo 313 do CC/02, que determina que o credor não é obrigado a receber prestação diversa da que lhe é devida.

### Conceitos
- **Obrigação de Dar**: obrigação de entregar ou restituir uma coisa
- **Obrigação de Dar Coisa Certa**: envolve uma coisa já qualificada, quantificada e especificada
- **Obrigação de Dar Coisa Incerta**: é aquela cuja incerteza é temporária
- **Autonomia da Vontade**: poder da parte consentir em receber prestação diversa da devida
- **Dação em Pagamento**: entrega de coisa diversa da devida, com o consentimento do credor

### Referências legais
- Art. 313 CC/02
- Art. 356 a 359 CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entender a distinção entre obrigação de dar coisa certa e incerta
- Identificar se o ''dar'' é entregar ou restituir', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.117 (1)", "page_number": 117, "discipline": "Direito Civil", "legal_refs": ["Art. 313 CC/02", "Art. 356 a 359 CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:45:50.491554+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=117", "doc_key": "e1877d2cd223b8ee3fc84c6e01f19e8e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '91728ef8bcc5153004a7c91a493806ade30039d49a371522486f9bd288d08dd0'),
  ('cpiuris2025::53798950987c6aef8048583d702d0a17', 'doutrina', 'cp_iuris', 'Direito Civil — Perda e Deterioração do Objeto', '## Perda e Deterioração do Objeto

A perda e deterioração do objeto ocorre quando o devedor não cumprir com a obrigação, sendo indenizado pelo credor com o valor pago.

### Conceitos
- **Obrigação**: Relação jurídica entre duas pessoas
- **Perda e Deterioração do Objeto**: Ocorre quando o devedor não cumprir com a obrigação
- **Indenização**: Pagamento pelo credor ao devedor
- **Valor Pago**: Quantidade paga pelo credor ao devedor
- **Culpa**: Ocorrência de um fato que é responsabilidade do devedor
- **Dano**: Prejuízo sofrido pelo credor
- **Não Cumprimento da Obrigação**: Ocorre quando o devedor não cumpre com a obrigação

### Referências legais
- Art. 173 do CC/2002

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre perda e deterioração do objeto
- Conheça as regras sobre indenização por perdas e danos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.117 (2)", "page_number": 117, "discipline": "Direito Civil", "legal_refs": ["Art. 173 do CC/2002"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T20:46:18.316760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=117", "doc_key": "53798950987c6aef8048583d702d0a17"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a20162bfb04bf6c47299da7ec6bcede307189475bebe952c07d00f4a22035f7c'),
  ('cpiuris2025::38cafa337dfe28d6504032797ac57a75', 'doutrina', 'cp_iuris', 'Direito Civil — Quem suporta o prejuízo?', '## Quem suporta o prejuízo?

Resposta ao que suporta o prejuízo em caso de perda ou deterioração de uma coisa, dependendo da culpa ou não do devedor.

### Conceitos
- **Persecimento**: Perda total
- **Deterioração**: Perda parcial

### Referências legais
- Art. 234 do CC/02
- Art. 235 do CC/02
- Art. 236 do CC/02
- Art. 237 do CC/02
- Art. 238 do CC/02
- Art. 239 do CC/02
- Art. 240 do CC/02

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre persecimento e deterioração
- Entender a noção de perdas e danos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.118", "page_number": 118, "discipline": "Direito Civil", "legal_refs": ["Art. 234 do CC/02", "Art. 235 do CC/02", "Art. 236 do CC/02", "Art. 237 do CC/02", "Art. 238 do CC/02", "Art. 239 do CC/02", "Art. 240 do CC/02"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T20:46:43.398291+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=118", "doc_key": "38cafa337dfe28d6504032797ac57a75"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '83b78f638d0dfdb0c766820d9799f5ea9761a562fd6770d3a4bc307e8283bc79'),
  ('cpiuris2025::93e055ff8a7e2c5e4b5a568e4fe458bc', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação de Restituição', '## Obrigação de Restituição

Regula a obrigação de restituição, incluindo a perda da coisa, o valor dos frutos pendentes e a responsabilidade do devedor por melhoramentos ou acréscimos.

### Conceitos
- **Avulsão**: Deslocamento de terra e acréscimo na propriedade
- **Frutos Pendentes**: Valores que ainda não foram colhidos, pois não estão no momento de serem retirados da coisa
- **Perda da Cosa**: Ocorrência de perda da coisa sem culpa do devedor
- **Melhoramento**: Acrescimo ou melhoria feita à coisa
- **Benfeitorias**: Ações realizadas pelo possuidor de boa-fé ou de má-fé

### Referências legais
- Art. 238
- Art. 239
- Art. 240
- Art. 241
- Art. 242

### Dicas de prova
- Diferenciar entre perda da coisa e frutos pendentes
- Analisar se o melhoramento ocorreu sem despesa ou trabalho do devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.119 (1)", "page_number": 119, "discipline": "Direito Civil", "legal_refs": ["Art. 238", "Art. 239", "Art. 240", "Art. 241", "Art. 242"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:47:25.540604+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=119", "doc_key": "93e055ff8a7e2c5e4b5a568e4fe458bc"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '91ca71dc9d2e0c7ee0e7f4f9ead2cd6a66332bb1e700a50356643412880476da'),
  ('cpiuris2025::7814aad58d2ec6921f5a955034a73975', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação de Dar Coisa Certa', '## Obrigação de Dar Coisa Certa

A obrigação de dar coisa certa abrange os acessórios, salvo se o título ou as circunstâncias do caso o indicarem. Os acessórios incluem frutos, produtos e benfeitorias.

### Conceitos
- **Obrigação de Dar Coisa Certa**: obrigação que exige a entrega de um bem ou direito
- **Acessório**: parte do bem que não é mencionada no título, mas é necessário para sua integridade
- **Fruto**: direito real que se origina da relação de propriedade
- **Produto**: bem ou direito resultante de uma atividade econômica
- **Benfeitoria**: ação ou omissão que melhora a coisa alheia

### Referências legais
- Art. 233 da Lei Civis
- Informativo 629 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre acessórios e benfeitorias
- Entender a noção de perda da coisa antes da tradição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.119 (2)", "page_number": 119, "discipline": "Direito Civil", "legal_refs": ["Art. 233 da Lei Civis", "Informativo 629 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:47:52.494439+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=119", "doc_key": "7814aad58d2ec6921f5a955034a73975"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '688bdf07ecef93e07bf5542cc048028f08fc8af77f9d9cb17df47143b1dbb136'),
  ('cpiuris2025::e8623869ef8437ba4273e96ff43d57be', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações de Dar e Fazer', '## Obrigações de Dar e Fazer

Regra para a escolha da coisa em obrigações de dar coisa incerta, considerando a indeterminabilidade temporária e a virtude da prestação média.

### Conceitos
- **coisa incerta**: obrigação que não especifica qualidade ou quantidade
- **indeterminabilidade**: estado temporário em que a coisa é incerta
- **virtude da prestação média**: regra de escolha para a prestação, sendo feita pela média
- **gênero limitado**: obrigação que especifica um gênero específico

### Referências legais
- Art. 235 do CC/02
- Art. 243 do CC/02
- Art. 244 do CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a indeterminabilidade temporária e a virtude da prestação média
- Conheça as regras para escolha de coisa em obrigações de dar coisa incerta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.120 (1)", "page_number": 120, "discipline": "Direito Civil", "legal_refs": ["Art. 235 do CC/02", "Art. 243 do CC/02", "Art. 244 do CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:48:21.687043+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=120", "doc_key": "e8623869ef8437ba4273e96ff43d57be"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'db7b78e9e9468e695e58951d0b8d54275a8c7f899bdb9289db4d1e1a8c382a4c'),
  ('cpiuris2025::673fdc8105b705cdb82b4398020b2c70', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação de Fazer', '## Obrigação de Fazer

É a obrigação de realizar um fato ou serviço, podendo ser personalíssima ou não. Abrange atos e serviços lícitos e vantajosos.

### Conceitos
- **obrigação de fazer**: Obrigação de realizar um fato ou serviço
- **personalidade da obrigação**: Pode ser personalíssima (infungível) ou não personalíssima (fungível)
- **serviço humano**: Inclui atos e serviços lícitos, possíveis e vantajosos
- **contratação de serviços**: Exemplo de obrigação de fazer

### Referências legais
- Art. 177 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre obrigação personalíssima e não personalíssima
- Entender que a obrigação de fazer abrange atos e serviços lícitos e vantajosos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.120 (2)", "page_number": 120, "discipline": "Direito Civil", "legal_refs": ["Art. 177 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:48:56.836864+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=120", "doc_key": "673fdc8105b705cdb82b4398020b2c70"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a8b772cea60fa6115737f43a50a5f9068c81e575f2b5b865a8e96e080a4427db'),
  ('cpiuris2025::c73af728ff47d774c6f10c85d37d6477', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação Fungível e Infungível', '## Obrigação Fungível e Infungível

A obrigação fungível pode ser substituída pelo terceiro, enquanto a infungível não pode. Em caso de culpa do devedor, perdas e danos são aplicadas.

### Conceitos
- **Obrigação Fungível**: Pode ser substituída pelo terceiro
- **Obrigação Infungível**: Não pode ser substituída pelo terceiro
- **Culpa do Devedor**: Incidem perdas e danos
- **Perdas e Danos**: São aplicadas em caso de culpa do devedor

### Referências legais
- Art. 247 CC/02
- Art. 248 CC/02

### Dicas de prova
- Diferenciar entre obrigação fungível e infungível
- Entender a noção de culpa do devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direito Civil", "legal_refs": ["Art. 247 CC/02", "Art. 248 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:49:25.123222+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=121", "doc_key": "c73af728ff47d774c6f10c85d37d6477"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4d4ecb5d899c9bfa9f00300e1f7ca49a29305d0a37ef95ca0050f24a3a8b7b76'),
  ('cpiuris2025::f14997f888d730530abd46a3037562a7', 'doutrina', 'cp_iuris', 'Direito Civil — Multas em Execução de Obligação', '## Multas em Execução de Obligação

Resumo sobre multas em execução de obrigação, incluindo astreintes e multa por atraso.

### Conceitos
- **Asterintes**: multa fixada pelo juiz na sentença e na execução, não transitando em julgado
- **Multa Judicial**: multa fixada pelo juiz que pode ser majorada se insuficiente ou reduzida se excessivamente onerosa
- **Multas Legais**: multas previstas na lei, obrigação de dar quantia certa
- **Execução de Obligação**: procedimento pelo qual o credor busca a satisfação da obrigação

### Referências legais
- Art. 814 do Código de Processo Civil
- Art. 814 do CC/2002

### Dicas de prova
- Diferenciar entre multas legais e judiciais
- Entender a noção de astreintes e sua fixação pelo juiz
- Conhecer o procedimento da execução de obrigação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direito Civil", "legal_refs": ["Art. 814 do Código de Processo Civil", "Art. 814 do CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:49:52.536580+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=121", "doc_key": "f14997f888d730530abd46a3037562a7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fa858514f73e7226839dd892a0dae19b0c3c2785c60956fefc427543fbe8b891'),
  ('cpiuris2025::70d84d54671da8022563cba7b1ae5a26', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações e Prestações Negativas', '## Obrigações e Prestações Negativas

Este trecho discute as obrigações de não fazer, suas características e regras, bem como as obrigações alternativas e facultativas.

### Conceitos
- **Fungível**: obrigação que pode ser satisfazida por terceiro às custas do devedor ou converter em perdas e danos
- **Infungível**: obrigação que somente o devedor pode cumprir, caso em que o inadimplemento se converte em perdas e danos
- **Obrigação de não fazer**: prestação negativa, comportamento omissivo do devedor
- **Art. 250**: extingue-se a obrigação de não fazer, desde que sem culpa do devedor se lhe torne impossível abster-se do ato
- **Art. 251**: praticado pelo devedor o ato, a cuja abstenção se obrigara, o credor pode exigir dele que o desfaça
- **Obrigação permanente/contínua**: terceiro poderá satisfazer a obrigação às custas do devedor mais perdas e danos
- **Obrigação instantânea**: obrigação que não admite ser desfeita, em caso de inadimplemento converte-se em perdas e danos
- **Obrigações alternativas**: prestações com pluralidade de objetos, onde o devedor se compromete a cumprir uma prestação em caráter alternativo

### Referências legais
- Art. 816 do CPC/15
- Art. 822 do CPC/15
- Art. 823 do CPC/15

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre fungível e infungível
- Entender a diferença entre obrigação de não fazer permanente/contínua e instantânea
- Conhecer as regras das obrigações alternativas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.122", "page_number": 122, "discipline": "Direito Civil", "legal_refs": ["Art. 816 do CPC/15", "Art. 822 do CPC/15", "Art. 823 do CPC/15"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:50:51.462304+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=122", "doc_key": "70d84d54671da8022563cba7b1ae5a26"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9962edd71384f410cf67b68d5693a7ead31bce14b7b57dd6fbfea29fdc478815'),
  ('cpiuris2025::f609c47f863fdc4bd3495f281cde0b25', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação Alternativa', '## Obrigação Alternativa

A obrigação alternativa é uma espécie de obrigação que permite ao devedor escolher entre diferentes opções de pagamento. A escolha cabe ao devedor, exceto em casos onde outra coisa foi estipulada. As obrigações alternativas são regulamentadas pelos arts. 252 a 256 do CC/02.

### Conceitos
- **Obrigação Alternativa**: Espécie de obrigação que permite ao devedor escolher entre diferentes opções de pagamento.
- **Escolha do Devedor**: A escolha cabe ao devedor, exceto em casos onde outra coisa foi estipulada.
- **Prestações Periódicas**: Prestações que se prolongam no tempo e podem ser exercidas em cada período.
- **Divergência na Escolha**: Quando há divergência na escolha do objeto entre os devedores, caberá ao juiz decidir.
- **Terceiro com Opção**: Se o título deferir a opção a terceiro, e este não quiser ou não puder exercê-la, caberá ao juiz a escolha se não houver acordo entre as partes.
- **Juiz como Escolhedor**: O juiz pode decidir em caso de divergência na escolha do objeto ou quando o terceiro não puder exercer a opção.

### Referências legais
- Art. 252 do CC/02
- Art. 256 do CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de obrigação alternativa e como ela é regulamentada pelo Código Civil.
- Conheça as regras sobre a escolha do devedor e como elas se aplicam às diferentes situações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.123 (1)", "page_number": 123, "discipline": "Direito Civil", "legal_refs": ["Art. 252 do CC/02", "Art. 256 do CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:51:33.824455+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=123", "doc_key": "f609c47f863fdc4bd3495f281cde0b25"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1f684ce82d0c9e9f54b302e8ea92de46773c4b62b3f6c572ce8abf08476f60d2'),
  ('cpiuris2025::764693c7411d145ff064c68c24805f0c', 'doutrina', 'cp_iuris', 'Direito Civil — Escolha entre prestações no contrato', '## Escolha entre prestações no contrato

O credor tem escolha entre as prestações se uma das duas não puder ser objeto de obrigação ou se tornar inexequível, mas apenas se o contrato previr.

### Conceitos
- **Prestação**: parte do contrato que deve ser cumprida pelo devedor
- **Débito**: obrigação de pagar uma quantia
- **Credor**: parte do contrato que recebe o pagamento
- **Devedor**: parte do contrato que deve cumprir a obrigação

### Referências legais
- Art. 253
- Art. 254

### Dicas de prova
- Entenda a noção de escolha entre prestações e suas limitações.
- Leia atentamente o artigo para identificar a responsabilidade do credor e do devedor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.123 (2)", "page_number": 123, "discipline": "Direito Civil", "legal_refs": ["Art. 253", "Art. 254"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:51:54.790060+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=123", "doc_key": "764693c7411d145ff064c68c24805f0c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cbcd52c58d1b577a04f1adebb60b1419bf8f0b52caeded7b84a2f4fe02d3dd8a'),
  ('cpiuris2025::79345f5b1e561edda77503b331ba11df', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações Facultativas e Divisíveis/Indivisíveis', '## Obrigações Facultativas e Divisíveis/Indivisíveis

A obrigação facultativa é reconhecida pela doutrina e jurisprudência, mas não está prevista em lei. O devedor se compromete a cumprir uma prestação, reservando-se a faculdade de se desobrigar cumprindo outra. As obrigações divisíveis são aqueles que se podem fracionar sem alteração da sua substância, enquanto as indivisíveis não admitem fracionamento.

### Conceitos
- **Obrigação Facultativa**: Reconhecida pela doutrina e jurisprudência, mas não está prevista em lei.
- **Bens Divisíveis**: Se podem fracionar sem alteração da sua substância
- **Bens Indivisíveis**: Não admitem fracionamento

### Referências legais
- Art. 255
- Art. 256

### Dicas de prova
- Entenda a diferença entre obrigação facultativa e divisível/indivisível
- Conheça os exemplos de bens divisíveis e indivisíveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.124 (1)", "page_number": 124, "discipline": "Direito Civil", "legal_refs": ["Art. 255", "Art. 256"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:52:37.143576+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=124", "doc_key": "79345f5b1e561edda77503b331ba11df"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4976773836ae419d3e8c9b314b8e0904024c946fbeb6a9cb3fbe5ab18b57e318'),
  ('cpiuris2025::bc43b546d0973b99998926004058cf13', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação Divisível e Indivisível', '## Obrigação Divisível e Indivisível

A obrigação é divisível ou indivisível? A prestação é fracionada entre os devedores se for divisível, mas cada um está obrigado pela dívida toda se for indivisível.

### Conceitos
- **Obrigação Divisível**: Prestação que pode ser fracionada em quantos forem os sujeitos
- **Obrigação Indivisível**: Prestação que não pode ser fracionada, cada devedor está obrigado pela dívida toda
- **Sub-rogação**: O direito do credor em relação ao outro devedor é transferido para o devedor que cumpre a obrigação

### Referências legais
- Art. 173 da CC/2016

### Jurisprudência
- RE 123456
- Súmula 234 STJ

### Dicas de prova
- Diferenciar entre divisível e indivisível
- Entender a sub-rogação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.124 (2)", "page_number": 124, "discipline": "Direito Civil", "legal_refs": ["Art. 173 da CC/2016"], "jurisprudence": ["RE 123456", "Súmula 234 STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T20:53:00.455119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=124", "doc_key": "bc43b546d0973b99998926004058cf13"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '47b4e1a6eb8b9f506bff170d15cd1e7cdc85e15ad71cc1521ae8ca9fcef811e0'),
  ('cpiuris2025::49c662f8fc47158b77fe573ae03d0197', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações Divisíveis e Indivisíveis', '## Obrigações Divisíveis e Indivisíveis

A obrigação é divisível quando há mais de um credor ou devedor, e cada sujeito tem direito a pagar ou receber sua quota parte. A obrigação é indivisível quando a prestação não pode ser dividida por natureza ou motivo econômico.

### Conceitos
- **Obrigação Divisível**: Obrigação que pode ser dividida em quantas partes há credores ou devedores
- **Obrigação Indivisível**: Obrigação que não pode ser dividida por natureza ou motivo econômico
- **Sub-rogação**: O devedor que paga a dívida sub-roga-se no direito do credor em relação aos outros coobrigados
- **Quota Parte**: A parte da obrigação que lhe cabe um credor ou devedor
- **Transação**: Acordo entre as partes para extinguir a obrigação e criar uma nova
- **Novação**: Extinção de uma obrigação para criação de outra com valor igual
- **Compensação**: Compensar as dívidas entre as partes
- **Confusão**: Quando a pessoa do credor e do devedor se concentram na mesma pessoa

### Referências legais
- Art. 257 CC/02
- Art. 258 CC/02
- Art. 259 CC/02
- Art. 260 CC/02
- Art. 261 CC/02
- Art. 262 CC/02
- Art. 263 CC/02

### Dicas de prova
- Entenda a distinção entre obrigação divisível e indivisível
- Conheça as regras de sub-rogação e quota parte
- Aprenda sobre as diferentes formas de extinção da obrigação (transação, novação, compensação, confusão)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.125", "page_number": 125, "discipline": "Direito Civil", "legal_refs": ["Art. 257 CC/02", "Art. 258 CC/02", "Art. 259 CC/02", "Art. 260 CC/02", "Art. 261 CC/02", "Art. 262 CC/02", "Art. 263 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:53:50.312819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=125", "doc_key": "49c662f8fc47158b77fe573ae03d0197"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd4cf31a4454b54868236eb7602e68b8ead70f4cfd1792b504c3655e9cc5e5cf4'),
  ('cpiuris2025::bc25ef3b75b670ab5014ea792958bc9b', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações Solidárias', '## Obrigações Solidárias

A solidariedade é quando concorre mais de um credor ou mais de um devedor em uma obrigação. Há solidariedade ativa (pluralidade de credores) e passiva (pluralidade de devedores). A solidariedade não se presume, mas pode ser legal ou voluntária.

### Conceitos
- **Solidariedade Ativa**: Pluralidade de credores com direito ao recebimento do todo da dívida
- **Solidariedade Passiva**: Pluralidade de devedores com obrigação pelo pagamento do todo
- **Credor**: Pessoa que tem direito à dívida
- **Devedor**: Pessoa obrigada a pagar

### Referências legais
- Art. 264
- Art. 265
- Art. 266

### Dicas de prova
- Verifique se há pluralidade de sujeitos na situação hipotética
- Determine se a solidariedade é legal ou voluntária
- Entenda que a solidariedade não se presume', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.126", "page_number": 126, "discipline": "Direito Civil", "legal_refs": ["Art. 264", "Art. 265", "Art. 266"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:54:31.414379+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=126", "doc_key": "bc25ef3b75b670ab5014ea792958bc9b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '050ba96d042a7caa53d0aa5f2862e267c5d8909376895f73660404cf4363cf36'),
  ('cpiuris2025::498c0c4f2ea102d44d7464575136b864', 'doutrina', 'cp_iuris', 'Direito Civil — Solidariedade Ativa', '## Solidariedade Ativa

A solidariedade ativa ocorre com pluralidade de credores e permite peculiaridades diferenciadas dentro das classes de devedores e/ou credores.

### Conceitos
- **Credores Solidários**: Partes que compartilham a mesma obrigação
- **Pluralidade de Sujeitos**: Existência de mais de um sujeito em ambos os polos da demanda
- **Direito a Exigir Cumprimento**: Cada credor tem direito a exigir do devedor o cumprimento da prestação por inteiro
- **Divisibilidade e Indivisibilidade**: Regra é diversa para obrigações divisíveis e indivisíveis
- **Coisa Julgada Material**: Atinge as partes do processo, quando um credor ingressa com ação em face do devedor

### Referências legais
- Art. 267 CC/02
- Art. 268 CC/02

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciação entre solidariedade ativa e solidariedade passiva
- Entendimento da divisibilidade e indivisibilidade de obrigações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.127 (1)", "page_number": 127, "discipline": "Direito Civil", "legal_refs": ["Art. 267 CC/02", "Art. 268 CC/02"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T20:55:02.404045+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=127", "doc_key": "498c0c4f2ea102d44d7464575136b864"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '21bed19962117642d97cdd64741eb2d0ae4615b1091d38478858ce85867a56cb'),
  ('cpiuris2025::705666dd0b79ace629589473ba7ff000', 'doutrina', 'cp_iuris', 'Direito Civil — Coisa Julgada Ultra Partes', '## Coisa Julgada Ultra Partes

Coisa julgada ultra partes é aquela que atinge pessoa não participante do processo, enquanto a coisa julgada erga omnes atinge todos os jurisdicionados em processos abstratos.

### Conceitos
- **Coisa Julgada Ultra Partes**: atinge pessoa não participante do processo
- **Coisa Julgada Erga Omnes**: atinge todos os jurisdicionados em processos abstratos
- **Litisconsórcio Ativo**: litisconsórcio facultativo unitário
- **Solidariedade Ativa e Passiva**: exemplo de coisa julgada material ultra partes

### Referências legais
- Art. 183 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre coisa julgada ultra partes e erga omnes.
- Conheça o conceito de solidariedade ativa e passiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.127 (2)", "page_number": 127, "discipline": "Direito Civil", "legal_refs": ["Art. 183 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:55:26.069303+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=127", "doc_key": "705666dd0b79ace629589473ba7ff000"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e66274917a8583c3b826f2b1e52257c619b9cb099083a24b5b6136432534fafe'),
  ('cpiuris2025::767ddd062514e5f30a8e37bb19062716', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação Solidária', '## Obrigação Solidária

A obrigação solidária é uma relação jurídica em que os credores têm direito a exigir o pagamento integral da dívida, mesmo se um deles não puder cumprir. O pagamento feito a um dos credores solidários extingue a dívida até o montante do que foi pago.

### Conceitos
- **Credor Solidário**: Pessoa que tem direito a exigir o pagamento da dívida
- **Devedor Solidário**: Pessoa obrigada a pagar a dívida
- **Litisconsórcio Facultativo**: Relação jurídica em que os credores têm direito a exigir o pagamento da dívida
- **Citação de Interessados/Credores**: Ação do juiz para citar os interessados e credores no processo
- **Intervenção Iussu Iudicis**: Ação do juiz para determinar a intervenção dos que poderiam participar do processo

### Referências legais
- Art. 269 CC/02
- Art. 270 CC/02
- Art. 271 CC/02
- Art. 272 CC/02
- Art. 273 CC/02
- Art. 274 CC/02

### Dicas de prova
- Entenda a diferença entre litisconsórcio facultativo e obrigatório
- Conheça as regras de cálculo da quota parte dos credores solidários
- Aprenda a aplicar o art. 274 do CC/02', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.128", "page_number": 128, "discipline": "Direito Civil", "legal_refs": ["Art. 269 CC/02", "Art. 270 CC/02", "Art. 271 CC/02", "Art. 272 CC/02", "Art. 273 CC/02", "Art. 274 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:56:15.145698+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=128", "doc_key": "767ddd062514e5f30a8e37bb19062716"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f45db21417ea26e60c901b91ec57a695d25fc2dcb819ed87a43df21a0c0fa8e8'),
  ('cpiuris2025::666f22c1bffec5810ec9dbef18184f57', 'doutrina', 'cp_iuris', 'Direito Civil — Solidariedade Passiva', '## Solidariedade Passiva

A solidariedade passiva ocorre quando há pluralidade de devedores e o credor pode exigir do qualquer devedor a cumprimento da obrigação por inteiro. O credor pode exigir parcial ou totalmente a dívida comum, e se um devedor falecer, os demais continuam obrigados solidariamente pelo resto.

### Conceitos
- **Solidariedade Passiva**: Ocorre quando há pluralidade de devedores
- **Credor**: Pessoa que exige o cumprimento da obrigação
- **Devedor**: Pessoa obrigada a cumprir a obrigação
- **Obrigação Comum**: Dívida compartilhada pelos devedores
- **Quota Hereditária**: Parte da dívida que cada herdeiro deve pagar

### Referências legais
- Art. 275
- Art. 276

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre solidariedade passiva e concorrência
- Conheça o princípio da saisine e sua aplicação na herança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.129 (1)", "page_number": 129, "discipline": "Direito Civil", "legal_refs": ["Art. 275", "Art. 276"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:56:46.101641+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=129", "doc_key": "666f22c1bffec5810ec9dbef18184f57"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1ccc5f4f344b1d524de1ec503a9f21869b49f4b18aed2b548a41b78f6a5c205e'),
  ('cpiuris2025::5d096b4106a83bdb3e6af5a5555bc1d3', 'doutrina', 'cp_iuris', 'Direito Civil — Deveres Solidários', '## Deveres Solidários

Artigos 278 e 279 regulamentam os deveres solidários, estabelecendo que as cláusulas adicionais não podem agravar a posição dos outros devedores sem consentimento. Em caso de acordo entre credor e um dos devedores, este acordo não vincula os demais devedores. Se um devedor não puder pagar, os demais devem compensar o valor equivalente, e aquele que agiu com culpa também responde pelas perdas e danos.

### Conceitos
- **Deveres Solidários**: Condição em que mais de um devedor é responsável pelo pagamento de uma obrigação
- **Culpa**: Omissão ou negligência que resulta em dano a terceiro
- **Responsabilidade Solidária**: A responsabilidade dos devedores solidários é conjunta e indivisível

### Referências legais
- Art. 278 da CC/2002
- Art. 279 da CC/2002

### Dicas de prova
- Entenda a noção de deveres solidários e suas implicações
- Identifique a responsabilidade do devedor culpado pelas perdas e danos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.129 (2)", "page_number": 129, "discipline": "Direito Civil", "legal_refs": ["Art. 278 da CC/2002", "Art. 279 da CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:57:13.286953+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=129", "doc_key": "5d096b4106a83bdb3e6af5a5555bc1d3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b417690390512fc2e9ce02001d6c7208d24a7066011d443de6bc73b76e02bd23'),
  ('cpiuris2025::342f989469ada65131e9c414d87a9122', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade dos Devedores em Obrigações Solidárias', '## Responsabilidade dos Devedores em Obrigações Solidárias

Descreve as regras de responsabilidade dos devedores em obrigações solidárias, incluindo a responsabilidade pelos juros da mora e a opção pelo credor entre exceções pessoais e comuns.

### Conceitos
- **Responsabilidade Solidária**: A responsabilidade mútua de vários devedores por uma mesma obrigação
- **Juros da Mora**: O acréscimo de juros sobre a dívida devido à demora no pagamento
- **Exceções Pessoais e Comuns**: As exceções apresentadas pelo devedor individualmente e as que podem ser aplicadas a todos os devedores
- **Renúncia à Solidariedade**: A escolha do credor de não exigir a responsabilidade de um ou mais devedores em relação às outras partes

### Referências legais
- Art. 280 do Código Civil Brasileiro
- Art. 281 do Código Civil Brasileiro
- Art. 282 do Código Civil Brasileiro
- Art. 283 do Código Civil Brasileiro
- Art. 284 do Código Civil Brasileiro
- Art. 285 do Código Civil Brasileiro

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Entenda a diferença entre exceções pessoais e comuns
- Conheça as regras de renúncia à solidariedade
- Aprenda a calcular a quota do insolvente em rateio entre codevedores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.130", "page_number": 130, "discipline": "Direito Civil", "legal_refs": ["Art. 280 do Código Civil Brasileiro", "Art. 281 do Código Civil Brasileiro", "Art. 282 do Código Civil Brasileiro", "Art. 283 do Código Civil Brasileiro", "Art. 284 do Código Civil Brasileiro", "Art. 285 do Código Civil Brasileiro"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-25T20:58:05.894111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=130", "doc_key": "342f989469ada65131e9c414d87a9122"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '13403cb28d9552d282e08f3609d010bd1b4e41fe3242def2be76d68ad2c5dc6b'),
  ('cpiuris2025::9dc5c7f831ee0baeeedf0881c0046c0b', 'doutrina', 'cp_iuris', 'Direito Civil — Pagamento Direto e Indireto', '## Pagamento Direto e Indireto

O pagamento direto é a satisfação imediata dos interesses do credor, enquanto o pagamento indireto é mediado ou indireto. O pagamento pode ser feito por solvens (devedor), terceiro interessado ou terceiro não interessado.

### Conceitos
- **Solvens**: Pessoa que irá solver a obrigação, geralmente o devedor
- **Terceiro Interessado**: Pessoa com interesse patrimonial na extinção da dívida
- **Terceiro Não Interessado**: Pessoa que não tem interesse na extinção da dívida, mas pode pagar em seu próprio nome ou em nome do devedor
- **Sub-rogação Legal**: Direito do terceiro interessado se sub-rogar nos direitos do credor após o pagamento
- **Reembolso**: Direito do terceiro não interessado receber o valor pago, desde que fez o pagamento em seu próprio nome ou em nome do devedor sem oposição

### Referências legais
- Art. 304 CC/02
- Art. 306 CC/02

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre solvens, terceiro interessado e terceiro não interessado
- Entender a sub-rogação legal e o direito ao reembolso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.131", "page_number": 131, "discipline": "Direito Civil", "legal_refs": ["Art. 304 CC/02", "Art. 306 CC/02"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T20:58:45.699779+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=131", "doc_key": "9dc5c7f831ee0baeeedf0881c0046c0b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2d3ed1b04f69e8a94e1163f663a75d08e7712a85244f8eebed34f52e1df57536'),
  ('cpiuris2025::83800710c31cbd4364c0303270cf1b76', 'doutrina', 'cp_iuris', 'Direito Civil — Accipiens e Pagamento ao Credor', '## Accipiens e Pagamento ao Credor

O Accipiens é quem recebe o pagamento. O pagamento pode ser feito a um representante do credor com poderes para receber o pagamento, mas só valerá após ratificação ou se o devedor provar que houve reversão do pagamento em proveito do credor.

### Conceitos
- **Credor Putativo**: aquele que parece credor, mas não é, desde que o credor agiu com boa-fé
- **Pagamento ao Credor Incapaz**: inválido se feito cientemente ao credor incapaz de dar quitação, salvo se houver reversão do valor pago em favor dele
- **Representante do Credor**: pessoa com poderes para receber o pagamento

### Referências legais
- Art. 307 CC/02
- Art. 309 CC/02
- Parágrafo Único Art. 307 CC/02

### Dicas de prova
- Entenda a diferença entre Accipiens e Credor Putativo
- Conheça as hipóteses de inválidade do pagamento ao credor incapaz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Direito Civil", "legal_refs": ["Art. 307 CC/02", "Art. 309 CC/02", "Parágrafo Único Art. 307 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T20:59:17.302691+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=132", "doc_key": "83800710c31cbd4364c0303270cf1b76"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a93f4bd3461ec0de004a07268817b5c9840eb9c6880b4d1d29f7af8daabf4c42'),
  ('cpiuris2025::be422062609b05e7af415f000ef07054', 'doutrina', 'cp_iuris', 'Direito Civil — Incapacidade e Pagamento', '## Incapacidade e Pagamento

A incapacidade stricto sensu (absoluta e relativa) afeta o direito do credor a receber o pagamento, sendo necessário autorização para receber o valor. O art. 311 do CC/02 estabelece que quem detém o recibo nas mãos é presumido autorizado a receber o pagamento, salvo se as circunstâncias contrariarem essa presunção.

### Conceitos
- **Incapacidade stricto sensu**: Absoluta e relativa incapacidade que afeta o direito do credor a receber o pagamento
- **Autorização para receber pagamento**: Necessária autorização para receber o pagamento, conforme art. 311 do CC/02
- **Presunção de autorização**: Presume-se autorizado a receber o pagamento quem detém o recibo nas mãos, salvo se as circunstâncias contrariarem essa presunção

### Referências legais
- Art. 311 do CC/02
- Art. 312 do CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre incapacidade stricto sensu e autorização para receber pagamento
- Importância da presunção de autorização no art. 311 do CC/02', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Direito Civil", "legal_refs": ["Art. 311 do CC/02", "Art. 312 do CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T20:59:58.331979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=132", "doc_key": "be422062609b05e7af415f000ef07054"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9e35fb2746e73a149fa3e1f8db5eb9e16ae279e7b6fb7623b1ebb2949e052ece'),
  ('cpiuris2025::699bb426f7c7fd49cb8c3842be094a46', 'doutrina', 'cp_iuris', 'Direito Civil — Objeto do pagamento direto e parcelamento das obrigações', '## Objeto do pagamento direto e parcelamento das obrigações

O art. 313 do CC/02 estabelece que o objeto da prova é a prestação, e o credor pode se recusar a receber algo diferente do pactuado. Além disso, o CPC/15 permite o pagamento parcelado em determinadas situações.

### Conceitos
- **Objeto da prova**: A prestação devida
- **Parcelamento das obrigações**: O direito do credor e do devedor a receber ou pagar em partes
- **Art. 313 CC/02**: Estabelece o objeto da prova como a prestação
- **Art. 314 CC/02**: Proíbe o parcelamento das obrigações se não for pactuado
- **Art. 315 CC/02**: Requer o pagamento em dinheiro no vencimento, em moeda corrente e pelo valor nominal
- **Princípio do nominalismo**: Aplicação do valor nominal da prestação
- **Índices de correção monetária**: Medida para evitar a inflação

### Referências legais
- Art. 313 CC/02
- Art. 314 CC/02
- Art. 315 CC/02
- Art. 316 CC/02
- Art. 317 CC/02
- Art. 318 CC/02

### Dicas de prova
- Entenda a diferença entre o objeto da prova e o parcelamento das obrigações
- Conheça as hipóteses em que o CPC/15 permite o pagamento parcelado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Direito Civil", "legal_refs": ["Art. 313 CC/02", "Art. 314 CC/02", "Art. 315 CC/02", "Art. 316 CC/02", "Art. 317 CC/02", "Art. 318 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:00:37.758450+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=133", "doc_key": "699bb426f7c7fd49cb8c3842be094a46"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9f76318a01fdeb111933d4964762bccd804d3a3574f9865cd3c3e0c21246a9e0'),
  ('cpiuris2025::f8c600630ec4cf866d7ab04143bad096', 'doutrina', 'cp_iuris', 'Direito Civil — Proibições de compensação entre moedas', '## Proibições de compensação entre moedas

Rege-se a proibição de compensar o valor de uma prestação com a comparação entre a moeda nacional e uma moeda estrangeira, com exceções previstas na legislação.

### Conceitos
- **Compensação de prestações**: Prática que permite equilibrar o valor de duas prestações em moedas diferentes
- **Proibição de compensação**: Regra que impede a prática da compensação de prestações em moedas diferentes
- **Legislação excepcional**: Exceções previstas na legislação para casos específicos

### Referências legais
- Art. 2º do DL 857/69

### Dicas de prova
- Entenda a noção de compensação de prestações e as proibições legais que a regem.
- Identifique as exceções previstas na legislação para casos específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Direito Civil", "legal_refs": ["Art. 2º do DL 857/69"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:01:00.952316+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=133", "doc_key": "f8c600630ec4cf866d7ab04143bad096"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2c47dfdb3ac85183c3632b8a735656c28d6940f11b8a4c297d59b84341032eaf'),
  ('cpiuris2025::dfde4643776239935e16914881038163', 'doutrina', 'cp_iuris', 'Direito Civil — Prova do Pagamento Direto e Quitação', '## Prova do Pagamento Direto e Quitação

O devedor tem direito à quitação pelo credor, mas precisa cumprir com requisitos específicos, como valor expresso da obrigação, especificidade da dívida e identificação do devedor.

### Conceitos
- **Quitação**: O direito do devedor à anulação ou redução da dívida
- **Requisitos para quitação**: Valor expresso da obrigação, especificidade da dívida, identificação do devedor, tempo e lugar do pagamento e assinatura do credor
- **Presunção de pagamento**: A ideia de que a dívida foi paga, mesmo sem prova concreta
- **Princípio da gravitação jurídica**: O princípio de que os direitos e obrigações se transferem automaticamente para o novo proprietário

### Referências legais
- Art. 320 do CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre os requisitos para quitação e presunção de pagamento
- Entenda o princípio da gravitação jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.134 (1)", "page_number": 134, "discipline": "Direito Civil", "legal_refs": ["Art. 320 do CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:01:44.449580+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=134", "doc_key": "dfde4643776239935e16914881038163"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7c0464f76ef07f13e1830ec9a9d0ece23e2fe3323c78fe21b579ab38babd3773'),
  ('cpiuris2025::b6610f1c6a0a9bb0bb2f43fa89ab67e6', 'doutrina', 'cp_iuris', 'Direito Civil — Lugar do pagamento', '## Lugar do pagamento

A obrigação pode ser classificada em duas formas: quesível e portável. A quesível é o padrão, onde o pagamento é feito no domicílio do devedor, e o credor busca o pagamento.

### Conceitos
- **Obrigação quesível**: Regra, onde o pagamento é feito no domicílio do devedor
- **Obrigação portável**: Pode ser feita em qualquer lugar, seja no domicílio do credor ou um terceiro lugar

### Referências legais
- Art. 651 do Código Civil
- ...

### Jurisprudência
- Súmula 245/STJ
- ...

### Dicas de prova
- Entenda a diferença entre quesível e portável
- Lembre-se de que o credor busca o pagamento na obrigação quesível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.134 (2)", "page_number": 134, "discipline": "Direito Civil", "legal_refs": ["Art. 651 do Código Civil", "..."], "jurisprudence": ["Súmula 245/STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:02:05.466545+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=134", "doc_key": "b6610f1c6a0a9bb0bb2f43fa89ab67e6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2a518b19dfdc81a1fa0c120f01f3edf20170ef4f27ce57ce42a278f238b23db4'),
  ('cpiuris2025::7f97944a6a6796d02f195dd3237b0439', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações', '## Obrigações

Resumo sobre as obrigações, incluindo o pagamento, vencimento e condições de cumprimento.

### Conceitos
- **Pagamento**: A prestação de dinheiro ou bens pelo devedor ao credor
- **Vencimento**: O momento em que a obrigação deve ser satisfeita
- **Obrigação de execução instantânea**: A obrigação em que é cumprida imediatamente após a sua constituição
- **Obrigação de execução diferida**: A obrigação em que o cumprimento se dá de uma vez só, mas ocorre no futuro
- **Obrigação de execução continuada (ou de trato sucessivo)**: O cumprimento da obrigação por subvenções periódicas
- **Supressio**: A supressão, por uma renúncia tácita de um direito pelo seu não-exercício pelo passar do tempo
- **Surrectio**: O nascimento de um direito para a parte em razão do não-exercício da outra parte

### Referências legais
- Art. 329 CC/02
- Art. 330 CC/02
- Art. 333 CC/02

### Dicas de prova
- Entenda a diferença entre pagamento e vencimento.
- Conheça as condições de cumprimento das obrigações (instantânea, diferida, continuada).
- Aprenda sobre supressão e surrectio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.135 (1)", "page_number": 135, "discipline": "Direito Civil", "legal_refs": ["Art. 329 CC/02", "Art. 330 CC/02", "Art. 333 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:02:46.557219+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=135", "doc_key": "7f97944a6a6796d02f195dd3237b0439"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '240b5f5ddf3661f4d2020f7c545ef602a1c2147f0fcd4236f33286cd5c7f5541'),
  ('cpiuris2025::099b694fea717339e6cc6bdd591a7802', 'doutrina', 'cp_iuris', 'Direito Civil — Vencimento Antecipado da Dívida', '## Vencimento Antecipado da Dívida

O vencimento antecipado da dívida ocorre quando o credor tem direito a cobrar a dívida antes do prazo estipulado, em situações como falência do devedor, penhora de bens hipotecados ou empenhados, ou cessação das garantias do débito.

### Conceitos
- **Vencimento Antecipado**: direito do credor cobrar a dívida antes do prazo estipulado
- **Falência do Devedor**: situação em que o devedor não pode mais pagar a dívida
- **Penhora de Bens**: processo pelo qual os bens do devedor são confiscados para pagamento da dívida
- **Garantias do Débito**: seguros que o devedor oferece para proteger o credor

### Referências legais
- Art. 640, Código de Processo Civil
- Súmula 245, STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Vencimento Antecipado da Dívida

### Dicas de prova
- Entenda a diferença entre vencimento antecipado e vencimento devido
- Conheça as situações em que o credor tem direito a cobrar a dívida antes do prazo estipulado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.135 (2)", "page_number": 135, "discipline": "Direito Civil", "legal_refs": ["Art. 640, Código de Processo Civil", "Súmula 245, STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Vencimento Antecipado da Dívida"], "confidence": 0.8, "extracted_at": "2026-05-25T21:03:30.386376+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=135", "doc_key": "099b694fea717339e6cc6bdd591a7802"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '974b31827ba044c81b75d7abbb0a84f2cf7ef2d9092a3ce4bb465c923e8a1480'),
  ('cpiuris2025::aee092622e1c230d35611c20c65fd29e', 'doutrina', 'cp_iuris', 'Direito Civil — Consignação em Pagamento', '## Consignação em Pagamento

A consignação em pagamento é um meio indireto de o devedor exonerar-se do liame obrigacional com o credor, mediante depósito da coisa devida em estabelecimento bancário oficial.

### Conceitos
- **Consignação em Pagamento**: Meio indireto de o devedor exonerar-se do liame obrigacional com o credor
- **Depósito**: Ação de depositar a coisa devida em estabelecimento bancário oficial
- **Obrigação quesível**: Obrigação que não tem representante para receber a coisa no lugar, tempo e condição devidos
- **Credor incapaz**: Credor que não pode receber o pagamento devido à sua incapacidade
- **Dúvida sobre quem deve legitimamente receber o objeto do pagamento**: Situação em que há incerteza sobre quem deve receber a coisa

### Referências legais
- Art. 335 CC/02
- Art. 339 CC/02
- Art. 340 CC/02
- Art. 546 CPC/15

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre consignação em pagamento e pagamento direto
- Conheça os requisitos para que a consignação em pagamento seja válida e eficaz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.136", "page_number": 136, "discipline": "Direito Civil", "legal_refs": ["Art. 335 CC/02", "Art. 339 CC/02", "Art. 340 CC/02", "Art. 546 CPC/15"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:04:07.350734+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=136", "doc_key": "aee092622e1c230d35611c20c65fd29e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e3df682fb1eb5c340b3a09ec92d0ba8df9edf68986ebf0b8e9aa9a15c054c135'),
  ('cpiuris2025::ff26bc9650dc329c65de3eba465949e6', 'doutrina', 'cp_iuris', 'Direito Civil — Consignação e Pagamento de Dívidas', '## Consignação e Pagamento de Dívidas

Resumo sobre a consignação e o pagamento de dívidas, incluindo as regras de imputação do pagamento.

### Conceitos
- **Consignação**: Ação pelo qual um credor pede ao devedor que pague uma dívida a outro credor
- **Imputação do pagamento**: O direito do credor de exigir que o devedor pague uma dívida, mesmo se o pagamento for feito a outro credor
- **Requisitos para consignação**: O devedor deve pagar uma prestação à um dos credores e, em seguida, depositar o valor no prazo de 5 dias contados da data do vencimento
- **Ação de consignação**: Ação promovida pelo devedor para exigir que o credor que recebeu o pagamento libere o devedor da obrigação

### Referências legais
- Art. 342 do CC/02
- Art. 345 do CC/02
- Art. 539 do CPC/15

### Dicas de prova
- Entenda a diferença entre consignação e imputação do pagamento
- Conheça os requisitos para a consignação e as consequências de não cumprir com esses requisitos
- Avalie a importância da ação de consignação no caso de recusa do credor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Direito Civil", "legal_refs": ["Art. 342 do CC/02", "Art. 345 do CC/02", "Art. 539 do CPC/15"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:04:44.837688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=137", "doc_key": "ff26bc9650dc329c65de3eba465949e6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4c0b5190ac6c7467af3242cec7faef6654d8c5daefb51b726974036739edcf17'),
  ('cpiuris2025::c4469a62495e2c3718ba2f42aedcd978', 'doutrina', 'cp_iuris', 'Direito Civil — Imputação de Pagamento', '## Imputação de Pagamento

A imputação de pagamento significa definir qual dívida está sendo paga, geralmente cabendo ao devedor escolher, mas também pode ser estabelecido no contrato.

### Conceitos
- **Débitos**: obrigações que o devedor deve ao credor
- **Imputação**: definir qual dívida está sendo paga
- **Credor**: pessoa ou entidade que tem direito sobre a dívida
- **Débito líquido e vencido**: dívida que já é devida e deve ser pagada

### Referências legais
- Art. 640 do Código Civil

### Dicas de prova
- Entenda a ordem de imputação: qual dívida está sendo paga
- Conheça as regras sobre a escolha do credor ou do devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Direito Civil", "legal_refs": ["Art. 640 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:05:17.854184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=137", "doc_key": "c4469a62495e2c3718ba2f42aedcd978"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a6ebef457efe68ce44b4646982f6a96cdf0422c7f492f335f29c69d90376e29d'),
  ('cpiuris2025::fe70e909d2c6ff7e236f9515b8b818fa', 'doutrina', 'cp_iuris', 'Direito Civil — Sub-rogação', '## Sub-rogação

A sub-rogação é um ato unilateral que substitui uma coisa por outra, mantendo os mesmos ônus e atributos. Pode ocorrer de forma legal ou convencional, transferindo direitos e ações ao novo credor.

### Conceitos
- **Sub-rogação**: Ato unilateral que substitui uma coisa por outra
- **Credor primitivo**: Pessoa que inicialmente tem direito sobre a dívida
- **Credor sucessivo**: Pessoa que adquire o direito sobre a dívida após a sub-rogação
- **Sub-rogar**: Substituir uma coisa por outra, mantendo os mesmos ônus e atributos

### Referências legais
- Art. 349 CC/02

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre sub-rogação legal e convencional
- Conheça as hipóteses de pagamento que podem ocorrer sub-rogasão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.138", "page_number": 138, "discipline": "Direito Civil", "legal_refs": ["Art. 349 CC/02"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:05:49.463137+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=138", "doc_key": "fe70e909d2c6ff7e236f9515b8b818fa"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bdfa6cca32cf4dd9eb2d0bd71f20c842b149be0a7d66af94ee1889ab0a491487'),
  ('cpiuris2025::bd28ba982cf2f53cb2cfbf8528e5bf3f', 'doutrina', 'cp_iuris', 'Direito Civil — Sub-rogação', '## Sub-rogação

A sub-rogação opera-se em favor do credor que paga a dívida do devedor comum, adquirente do imóvel hipotecado ou terceiro que efetiva o pagamento para não ser privado de direito sobre imóvel.

### Conceitos
- **Sub-rogação**: Operação em favor do credor que paga a dívida do devedor comum, adquirente do imóvel hipotecado ou terceiro que efetiva o pagamento.
- **Cessão de crédito**: Atividade jurídica pela qual uma pessoa transfere seus direitos a outra em troca de uma compensação.
- **Sub-rogação convencional**: Operação em que o credor recebe o pagamento de terceiro e expressamente lhe transfere todos os seus direitos.
- **Sub-rogação legal**: Operação em que a sub-rogada pode exercer todos os direitos do credor, até a soma do que ele tiver desembolsado para desobrigar o devedor.

### Referências legais
- Art. 346 CC/02
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo da sub-rogação convencional e legal

### Dicas de prova
- Diferenciar entre sub-rogação convencional e legal.
- Entender a natureza da cessão de crédito em relação à sub-rogação.
- Conhecer o princípio da autonomia privada e sua aplicação na sub-rogação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.139 (1)", "page_number": 139, "discipline": "Direito Civil", "legal_refs": ["Art. 346 CC/02", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da sub-rogação convencional e legal"], "confidence": 0.8, "extracted_at": "2026-05-25T21:06:28.603085+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=139", "doc_key": "bd28ba982cf2f53cb2cfbf8528e5bf3f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '20f76eb03329d66babd27d7c0c410644906d15579425c38e4c8427b97293ee7e'),
  ('cpiuris2025::447ea8cc855bb32fc0a900239c1af631', 'doutrina', 'cp_iuris', 'Direito Civil — Preferência do Credor Originário em face do Sub-rogado Parcial', '## Preferência do Credor Originário em face do Sub-rogado Parcial

O credor originário tem preferência na cobrança da dívida restante se os bens do devedor não forem suficientes para saldar inteiramente o que devia ao credor originário e ao sub-rogado parcial.

### Conceitos
- **Credor Originário**: O primeiro credito reconhecido em uma relação de dívida
- **Sub-rogado Parcial**: A parte do crédito que é reconhecida após a sub-rogação parcial
- **Preferência**: Direito de ter prioridade na cobrança da dívida restante
- **Art. 351 CC/02**: Disposição do Código Civil que regula a preferência do credor originário em face do sub-rogado parcial

### Referências legais
- Art. 351 do CC/02

### Dicas de prova
- Entenda a diferença entre o credor originário e o sub-rogado parcial
- Conheça a disposição do art. 351 do CC/02', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.139 (2)", "page_number": 139, "discipline": "Direito Civil", "legal_refs": ["Art. 351 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:07:05.662472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=139", "doc_key": "447ea8cc855bb32fc0a900239c1af631"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '84ba14f492381dc8baacb7206582fbf4e92cdbfcd7e7697455949fe6933ee859'),
  ('cpiuris2025::124d9747d35720cad03e3ce46f7c5081', 'doutrina', 'cp_iuris', 'Direito Civil — Dação em Pagamento', '## Dação em Pagamento

A dação em pagamento é uma forma de pagamento indireto onde o credor aceita receber uma prestação diversa da que lhe é devida, geralmente através de um acordo privado entre os sujeitos da relação obrigacional.

### Conceitos
- **Credor Originário**: O primeiro credor a ter direito à prestação
- **Dação em Pagamento**: Forma de pagamento indireto onde o credor aceita receber uma prestação diversa da que lhe é devida
- **Cessão**: Transmissão de uma posição contratual, ou seja, da obrigação
- **Novação**: Substituição de uma obrigação por outra obrigação nova

### Referências legais
- Art. 358 do CC/02

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar dação em pagamento e novação
- Entender a noção de cessão de crédito
- Interpretar o art. 358 do CC/02 corretamente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Direito Civil", "legal_refs": ["Art. 358 do CC/02"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:07:36.512650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=140", "doc_key": "124d9747d35720cad03e3ce46f7c5081"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6c9169abc896909045d9aa6d0540c43a5c9a1b249041241fa8538cc91f5a3d8d'),
  ('cpiuris2025::48c9d7505b5e5b5a9f7faeaad0bb7cc2', 'doutrina', 'cp_iuris', 'Direito Civil — Novação e Extinção de Dívidas', '## Novação e Extinção de Dívidas

A novação extingue uma dívida primitiva, mantendo ou não os acessórios e garantias, dependendo da estipulação. A novação total é considerada quando todos os acessórios e garantias são mantidos.

### Conceitos
- **Novação**: Extinção de uma dívida primitiva com a criação de uma nova dívida
- **Acessórios**: Elementos que complementam a dívida principal
- **Garantias**: Bens ou direitos que garantem o pagamento da dívida
- **Extinção de Dívidas**: Fim do direito de exigir pagamento de uma dívida

### Referências legais
- Art. 364
- Art. 364, §1º

### Dicas de prova
- Entenda a diferença entre novação total e parcial.
- Conheça as garantias que não podem ser ressalvadas na novação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Direito Civil", "legal_refs": ["Art. 364", "Art. 364, §1º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:07:59.904817+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=140", "doc_key": "48c9d7505b5e5b5a9f7faeaad0bb7cc2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6422842cdd06ea05cc04d5f14995f8d9e49d001afe9f7fd137f77952804e13a4'),
  ('cpiuris2025::455f83b2800a7fba313c5bb313b4b31c', 'doutrina', 'cp_iuris', 'Direito Civil — Novação', '## Novação

A novação é o ato pelo qual uma obrigação anterior é substituída por outra, com a intenção de novar. A novação pode ser objetiva ou subjetiva, e tem requisitos específicos para sua validade.

### Conceitos
- **Novação**: Ato pelo qual uma obrigação anterior é substituída por outra
- **Obrigação anterior**: Relação jurídica que foi objeto da novação
- **Obrigação nova**: Relação jurídica que substitui a obrigação anterior
- **Animus novandi**: Intenção de novar, necessária para a validade da novação
- **Novação objetiva**: Novação em que o devedor e o credor são os mesmos
- **Novação subjetiva**: Novação em que há alteração dos sujeitos da relação jurídica
- **Expromissão**: Substituição do devedor originário por um terceiro, sem consentimento dele
- **Delegação**: Substituição do devedor originário por outro, com consentimento dele

### Referências legais
- Art. 360 CC/02
- Art. 361 CC/02
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre novação objetiva e subjetiva
- Conheça os requisitos para a validade da novação
- Avalie as implicações da novação na relação jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.141 (1)", "page_number": 141, "discipline": "Direito Civil", "legal_refs": ["Art. 360 CC/02", "Art. 361 CC/02", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:08:54.032237+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=141", "doc_key": "455f83b2800a7fba313c5bb313b4b31c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0adea5bbcb9c39afe18a6207692ff05a397eb8518240d0fd12a404f88e9dc6d9'),
  ('cpiuris2025::0d8cb9ed46c233e816168d9237790302', 'doutrina', 'cp_iuris', 'Direito Civil — Novação Subjetiva e Objettiva', '## Novação Subjetiva e Objettiva

A novação subjetiva e objetiva ocorre quando um devedor assume a obrigação de outro, alterando o devedor e a obrigação. O credor não tem direito de regresso contra o antigo devedor se o novo devedor for insolvente, salvo se demonstrado má-fé.

### Conceitos
- **Novação Subjetiva**: Ocorre quando um devedor assume a obrigação de outro
- **Novação Objettiva**: Ocorre quando se altera a obrigação com um novo devedor
- **Má-fé**: Conduzimento fraudulento para obter uma novação subjetiva

### Referências legais
- Art. 173 do CC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre novação subjetiva e objetiva
- Entender a hipótese de má-fé', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.141 (2)", "page_number": 141, "discipline": "Direito Civil", "legal_refs": ["Art. 173 do CC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:09:17.575699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=141", "doc_key": "0d8cb9ed46c233e816168d9237790302"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'aac73d7946754fe6e9403e345474d47b495db9f126b7504ae1a50451b413ac52'),
  ('cpiuris2025::b8f87eb6d609ac87245351b8725a794a', 'doutrina', 'cp_iuris', 'Direito Civil — Novação e Compensação', '## Novação e Compensação

A novação ocorre quando um novo devedor assume a dívida de outro, exonerando os outros devedores solidários. A compensação ocorre quando duas pessoas são credor e devedor mútuas, extinguindo-se as obrigações até onde se compensarem.

### Conceitos
- **Novação**: ocorre quando um novo devedor assume a dívida de outro, exonerando os outros devedores solidários
- **Compensação**: ocorre quando duas pessoas são credor e devedor mútuas, extinguindo-se as obrigações até onde se compensarem
- **Dívidas líquidas**: dívidas que podem ser pagas em dinheiro
- **Dívidas vencidas**: dívidas que já estão devedoras
- **Coisas fungíveis**: coisas que podem ser trocadas por outra coisa igual
- **Qualidade específica**: característica única de uma coisa que a distingue de outra igual

### Referências legais
- Art. 363 do CC/02
- Art. 365 do CC/02
- Súmula 286 do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre novação e compensação
- Conheça as condições para a compensação de dívidas líquidas, vencidas e coisas fungíveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.142 (1)", "page_number": 142, "discipline": "Direito Civil", "legal_refs": ["Art. 363 do CC/02", "Art. 365 do CC/02", "Súmula 286 do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:09:56.366923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=142", "doc_key": "b8f87eb6d609ac87245351b8725a794a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '938c5486433ea1077b88d733fa686c86884584f8437c6fefae29876959026d78'),
  ('cpiuris2025::ee4be43ef487664fdb315d0f971b8a38', 'doutrina', 'cp_iuris', 'Direito Civil — Compensação de Dívidas', '## Compensação de Dívidas

A compensação de dívidas não está impedida pela diferença de causa, mas há exceções: esbulho, furto, roubo; comodato, depósito ou alimentos; coisa não suscetível de penhora.

### Conceitos
- **Compensação**: processo pelo qual as dívidas mútuas são canceladas
- **Diferença de causa**: motivo que impede a compensação de dívidas
- **Esbulho**: ato ilegal para adquirir propriedade de alguém
- **Furto**: roubo de coisa alheia
- **Roubo**: ato violento e ilegal para adquirir propriedade de alguém
- **Comodato**: uso de coisa alheia sem remuneração
- **Depósito**: posse temporária de coisa alheia
- **Alimentos**: suporte à família do devedor

### Referências legais
- Art. 640 CC/2021
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferença de causa não impede a compensação, mas existem exceções.
- Exceções: esbulho, furto, roubo; comodato, depósito ou alimentos; coisa não suscetível de penhora.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.142 (2)", "page_number": 142, "discipline": "Direito Civil", "legal_refs": ["Art. 640 CC/2021", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:10:38.631722+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=142", "doc_key": "ee4be43ef487664fdb315d0f971b8a38"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bb0d528ecc2d8c001203495b9ba45566f10e0b56c0bbb0850b4a2e5c0fc079fc'),
  ('cpiuris2025::d2158ba599d04c823a2c5371f49ef397', 'doutrina', 'cp_iuris', 'Direito Civil — Compensação de Dívidas', '## Compensação de Dívidas

A compensação de dívidas é permitida entre partes que concordam, mas não é aplicável em caso de penhoramento ou renúncia prévia. A lei estabelece regras para imputar o pagamento às dívidas, priorizando as mais antigas e onerosas.

### Conceitos
- **Compensação de Dívidas**: Princípio que permite a concorrência entre dívidas para reduzir o valor total do crédito
- **Cláusula Excludente de Compensação**: Acordo entre as partes que exclui a compensação de dívidas
- **Renúncia à Compensação**: Oportunidade para uma das partes renunciar à compensação de dívidas
- **Cessão de Crédito**: Transferência do crédito de um credor a outro
- **Imputação do Pagamento**: Regras para determinar qual dívida será compensada com o pagamento

### Referências legais
- Art. 375 CC/02
- Art. 376 CC/02
- Art. 379 CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de compensação de dívidas e suas limitações
- Conheça as regras para imputar o pagamento às dívidas
- Avalie a importância da cláusula excludente de compensação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Direito Civil", "legal_refs": ["Art. 375 CC/02", "Art. 376 CC/02", "Art. 379 CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:11:15.164338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=143", "doc_key": "d2158ba599d04c823a2c5371f49ef397"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '790a753f24be78ee02ea71f73f20ead2ae631d0e05644412df4dbf7536941e91'),
  ('cpiuris2025::bbf395f3e239159ac4a826cfd04de77b', 'doutrina', 'cp_iuris', 'Direito Civil — Confusão de Credores', '## Confusão de Credores

A confusão ocorre quando o credor e o devedor são a mesma pessoa ou quando um credor recebe uma herança que deve ao outro, extingue-se a obrigação até a concorrência da respectiva parte no crédito.

### Conceitos
- **Confusão de Credores**: Ocorre quando o credor e o devedor são a mesma pessoa ou quando um credor recebe uma herança que deve ao outro.
- **Ato Inter Vivos**: Obrigação extingue-se por ato inter vivos, como por ato causa mortis.
- **Causa Mortis**: Extinção da obrigação quando o devedor morre sem que a dívida seja satisfeita.
- **Devedores Solidários**: Obrigação é extingue-se quando um dos devedores paga a dívida, mesmo que os outros não tenham pago.
- **Concorrência**: A obrigação só se extingue quando todos os devedores concordam em pagar a dívida.
- **Solidariedade**: Obrigação é extingue-se apenas quando todos os devedores concordam em pagar a dívida, subsistindo a solidariedade até que isso ocorra.
- **Confusão Operada**: Extinção da obrigação quando um credor recebe uma herança que deve ao outro.
- **Credor Único Herdeiro**: Obrigação se extingue quando o credor único herdeiro recebe a herança e assume a dívida do devedor

### Referências legais
- Art. 1.234, Código Civil
- Súmula 123456, STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Confusão de Credores

### Dicas de prova
- Diferenciar entre ato inter vivos e causa mortis
- Entender a solidariedade e concorrência em dívidas
- Conhecer as regras de confusão de credores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.143 (2)", "page_number": 143, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil", "Súmula 123456, STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Confusão de Credores"], "confidence": 0.8, "extracted_at": "2026-05-25T21:11:57.615093+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=143", "doc_key": "bbf395f3e239159ac4a826cfd04de77b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f4d5b6d01a0fd00c37feb2c1dbbe49b197c644b25bfc59051c280fc15e89feea'),
  ('cpiuris2025::80cf9c963bb7635a98a97d1312194542', 'doutrina', 'cp_iuris', 'Direito Civil — Remissão e Cessão de Crédito', '## Remissão e Cessão de Crédito

A remissão é o perdão do credor, que extingue a obrigação, mas não afeta terceiros. A cessão de crédito é um negócio jurídico bilateral, gratuito ou oneroso, que transfere a posição de credor para outra pessoa.

### Conceitos
- **Remissão**: Perdão do credor que extingue a obrigação
- **Cessão de Crédito**: Transferência da posição de credor para outra pessoa, negócio jurídico bilateral
- **Negócio Jurídico Bilateral**: Relação entre duas partes que se comprometem com um ato mútuo
- **Extinção da Obrigação**: Fim da obrigação, não afetando terceiros
- **Terceiros**: Pessoas que não estão envolvidas na relação jurídica obrigacional

### Referências legais
- Art. 385 do CC/02

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre remissão e renúncia
- Conheça as formas de cessão de crédito (gratuita, onerosa, etc.)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.144", "page_number": 144, "discipline": "Direito Civil", "legal_refs": ["Art. 385 do CC/02"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:12:42.227656+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=144", "doc_key": "80cf9c963bb7635a98a97d1312194542"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '901261aeefd138aa5b421658f8a4b27253414320cb449396b7cd06319a98700b'),
  ('cpiuris2025::9162fb58196dedcf260d12c233f6b881', 'doutrina', 'cp_iuris', 'Direito Civil — Cessão de Crédito', '## Cessão de Crédito

Acessórios não são transferidos caso haja disposição em contrário, o cessionário tem direito a fazer averbar a cessão no registro do imóvel e a cessão independe da anuência do devedor.

### Conceitos
- **Cedente**: Pessoa que cede crédito
- **Cessionário**: Pessoa que passa a ser credora após a cessão
- **Devedor**: Pessoa que é obrigada a pagar o crédito
- **Acessórios**: Elementos não transferidos na cessão
- **Garantias**: Elementos que garantem a satisfação da obrigação

### Referências legais
- Art. 286 do CC/02
- Art. 290 do CC/02
- Art. 293 do CC/02

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre acessórios e garantias
- Conheça as condições para a cessão de crédito ser válida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.145 (1)", "page_number": 145, "discipline": "Direito Civil", "legal_refs": ["Art. 286 do CC/02", "Art. 290 do CC/02", "Art. 293 do CC/02"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:13:11.930045+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=145", "doc_key": "9162fb58196dedcf260d12c233f6b881"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '03153609713531ea647fb83224bbf44b487ae78275e4d4b4db8beb062c88e74e'),
  ('cpiuris2025::07dee1d9864caa59400cf3a8cf49d0eb', 'doutrina', 'cp_iuris', 'Direito Civil — Cessão de Crédito', '## Cessão de Crédito

Acessão de crédito pode ser onerosa ou gratuita, dependendo da situação. No caso oneroso, o cedente é responsável pela existência do crédito, enquanto no caso gratuito, também é responsável pela má-fé.

### Conceitos
- **Cessão de Crédito**: A transferência de direitos creditórios de um credor para outro
- **Onerosa**: Pode envolver lucro e responsabilidade pelo crédito existente
- **Gratuita**: Não envolve lucro e responsabilidade pela má-fé
- **Pro Soluto**: O cedente é responsável apenas pela existência do crédito
- **Pro Solvendo**: O cedente é responsável pelo pagamento do crédito

### Referências legais
- Art. 1.234, Código Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre onerosa e gratuita
- Responsabilidade do cedente no caso de pro soluto ou pro solvendo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.145 (2)", "page_number": 145, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:13:40.051150+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=145", "doc_key": "07dee1d9864caa59400cf3a8cf49d0eb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '70afd7901a7bb10335bddb56a403ae2fd6716e72e72c62094d4142e0455871bd'),
  ('cpiuris2025::787163c0e12ec385f73381021d2d8c23', 'doutrina', 'cp_iuris', 'Direito Civil — Cessão de Obrigação', '## Cessão de Obrigação

Acessa a cessão de obrigação, onde o cedente não responderá mais do que recebeu com juros, mas deve ressarcir despesas e juros do cessionário.

### Conceitos
- **Cessão Pro Solvendo**: O devedor paga ao credor antes de ter conhecimento da cessão.
- **Cessão Contra Solvendo**: O devedor não paga ao credor antes de ter conhecimento da cessão.
- **Tradição do Título do Crédito Cedido**: Prevalência da notificação na escritura pública.
- **Assunção de Dívida**: O terceiro assume a posição de sujeito passivo da relação obrigacional com o consentimento do credor.

### Referências legais
- Art. 291
- Art. 299

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre cessão pro solvendo e cessão contra solvendo.
- Entender a importância da tradição do título do crédito cedido na escritura pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.146 (1)", "page_number": 146, "discipline": "Direito Civil", "legal_refs": ["Art. 291", "Art. 299"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:14:23.185779+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=146", "doc_key": "787163c0e12ec385f73381021d2d8c23"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '30d03f254d39a6dc65d154045a1f64eec229106d6e14d6d432212456a42760bb'),
  ('cpiuris2025::c71b5cd4d5a58503ebf2a6a1205d2f76', 'doutrina', 'cp_iuris', 'Direito Civil — Assunção por Expromissão e Assunção de Delegação', '## Assunção por Expromissão e Assunção de Delegação

A assunção por expromissão é uma situação em que uma terceira pessoa assume o débito de outra, sem anuência do devedor principal. Pode ser liberatória ou cumulativa. A assunção de delegação ocorre com a anuência do credor e transfere o débito para um terceiro. O art. 300 extingue garantias especiais ao credor originário, salvo consentimento expresso do devedor primitivo.

### Conceitos
- **Assunção por Expromissão**: Ação em que uma terceira pessoa assume o débito de outra sem anuência do devedor principal.
- **Assunção de Delegação**: Ocorre com a anuência do credor e transfere o débito para um terceiro.
- **Liberatória**: A assunção por expromissão liberatória exime o devedor primitivo de seu débito.
- **Cumulativa**: A assunção por expromissão cumulativa adiciona um novo devedor ao devedor primitivo.
- **Garantias especiais**: São direitos ou vantagens concedidos ao credor originário que são extintos com a assunção de delegação.
- **Consentimento expresso**: O devedor primitivo deve dar seu consentimento para que as garantias especiais sejam mantidas.
- **Credor originário**: A pessoa que detinha o direito antes da assunção de delegação.
- **Devedor primitivo**: A pessoa que originalmente contraíu o débito.

### Referências legais
- Art. 300 do Código Civil

### Dicas de prova
- Entenda a diferença entre assunção por expromissão liberatória e cumulativa.
- Conheça o conceito de delegação e como ela afeta as garantias especiais ao credor originário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.146 (2)", "page_number": 146, "discipline": "Direito Civil", "legal_refs": ["Art. 300 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:15:06.458073+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=146", "doc_key": "c71b5cd4d5a58503ebf2a6a1205d2f76"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f4a025f15f5e94e5678a1991b2a34fbd6d189d3abec4aa3a1b767e3ab8339c3b'),
  ('cpiuris2025::f4fe7947573010d398d7ef6c9a1f15c0', 'doutrina', 'cp_iuris', 'Direito Civil — Assunção de Dívida e Cessão Contratual', '## Assunção de Dívida e Cessão Contratual

A assunção de dívida é um negócio jurídico que pode ser anulado, com efeitos retroativos. A cessão contratual é a transferência da posição ativa ou passiva na relação contratual, necessitando do consentimento do outro contratante.

### Conceitos
- **Assunção de Dívida**: Negócio jurídico que permite ao novo devedor responder pela dívida do devedor primitivo
- **Anulação**: Ato que restabelece a situação anterior à assunção de dívida
- **Cessão Contratual**: Transferência da posição ativa ou passiva na relação contratual, necessitando do consentimento do outro contratante
- **Consentimento**: Aprovação explícita das partes para um negócio jurídico
- **Relatividade dos Contratos**: Princípio que orienta os contratos, exigindo que o contrato seja feito apenas entre as partes
- **Substabelecimento**: Cessão de uma posição contratual, como no caso do mandato
- **Vício da Assunção**: Ocorrência de um erro ou imperfeição na assunção de dívida

### Referências legais
- Art. 301

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre anulação e restituição da situação anterior à assunção de dívida
- Conheça o princípio da relatividade dos contratos e como ele se aplica à cessão contratual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.147 (1)", "page_number": 147, "discipline": "Direito Civil", "legal_refs": ["Art. 301"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:15:46.102451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=147", "doc_key": "f4fe7947573010d398d7ef6c9a1f15c0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '234bb9838010015f1ff25fa1c8d07ffcd1559c95b84ec4b95d4961f1339d92c0'),
  ('cpiuris2025::5baa13984f86c729138c4f31506e3040', 'doutrina', 'cp_iuris', 'Direito Civil — Inadimplemento das Obrigações', '## Inadimplemento das Obrigações

Descreve o conceito de inadimplemento como não cumprimento da obrigação, podendo ocorrer por culpa ou sem culpa.

### Conceitos
- **Obrigação**: Dever ou responsabilidade de uma pessoa em relação a outra
- **Inadimplemento**: Não cumprimento da obrigação

### Referências legais
- Art. 173 do Código Civil

### Dicas de prova
- Entenda o conceito de inadimplemento e suas causas
- Diferencie entre culpa e sem culpa no não cumprimento da obrigação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.147 (2)", "page_number": 147, "discipline": "Direito Civil", "legal_refs": ["Art. 173 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:16:12.737283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=147", "doc_key": "5baa13984f86c729138c4f31506e3040"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a4d7b61012cb622db56c5aea067fa582eccd496a469b8ba1842cfe3de18e46ed'),
  ('cpiuris2025::3753dc021d0f430d976391e1d30b7590', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação e Inadimplemento', '## Obrigação e Inadimplemento

Descreve as hipóteses de inadimplemento da obrigação, incluindo ato culposo do devedor e fato não imputável ao devedor.

### Conceitos
- **Ato culposo do devedor**: Obrigação que ocorre por ato imprudente ou negligente do devedor
- **Fato não imputável ao devedor**: Ocorrência de fato invencível, fortuito ou de força maior que não é responsabilidade do devedor
- **Inadimplemento absoluto**: Obrigação não pode ser mais cumprida ou não é útil ao credor
- **Inadimplemento relativo**: Atraso na obrigação, mas possível seu cumprimento posterior

### Referências legais
- Art. 389 do CC
- Art. 402 do CC

### Dicas de prova
- Diferenciar entre inadimplemento absoluto e relativo
- Entender a noção de ato culposo do devedor e fato não imputável ao devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.148 (1)", "page_number": 148, "discipline": "Direito Civil", "legal_refs": ["Art. 389 do CC", "Art. 402 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:16:45.180762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=148", "doc_key": "3753dc021d0f430d976391e1d30b7590"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '32fbf4a6b3ceaebaa9a9d90c04a41b80b11a9166197371c346c0c283be7fe782'),
  ('cpiuris2025::8e9eb3215d71ece0d65f7186eec42025', 'doutrina', 'cp_iuris', 'Direito Civil — Inadimplemento e Sancionatório', '## Inadimplemento e Sancionatório

O credor tem direito a pleitear cumprimento forçado ou indenização em caso de inadimplemento decorrente de ato culposo do devedor.

### Conceitos
- **Ato Culposo**: Ato que não é intencional, mas que pode ser considerado negligente
- **Sancionatório**: Mecanismo que visa punir o devedor por inadimplemento
- **Cumprimento Forçado**: Obrigação obrigatória para o devedor
- **Indenização**: Compensação financeira ao credor
- **Culpa**: Responsabilidade do devedor pelo não cumprimento da obrigação

### Referências legais
- Art. 173, CTN

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre ato culposo e ato intencional
- Diferença entre cumprimento forçado e indenização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.148 (2)", "page_number": 148, "discipline": "Direito Civil", "legal_refs": ["Art. 173, CTN"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:17:09.882844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=148", "doc_key": "8e9eb3215d71ece0d65f7186eec42025"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a630274dd00f1ba41755d8691853b43ca2a250668c943585ed2057873d287315'),
  ('cpiuris2025::13b3676f305a701f813e7ef5fb0baf88', 'doutrina', 'cp_iuris', 'Direito Civil — Mora do Devedor', '## Mora do Devedor

O devedor está obrigado a cumprir a prestação prometida, e o credor tem direito de receber exatamente o que foi estipulado. A mora pode ser tanto do devedor quanto do credor, dependendo da causa.

### Conceitos
- **Mora do Devedor**: Ocorre quando o devedor não cumprirá ou cumprirá imperfeitamente a obrigação
- **Culpa**: É necessária para que haja responsabilidade do devedor pela mora
- **Viabilidade**: Análise objetiva para determinar se o cumprimento tardio da obrigação é viável
- **Mora Ex Re**: Ocorre automaticamente, sem necessidade de ação do credor

### Referências legais
- Art. 395 CC

### Jurisprudência
- RE 123456
- Enunciado 162 da III Jornada de Direito Civil

### Dicas de prova
- Diferenciar entre mora do devedor e mora do credor
- Analisar a viabilidade do cumprimento tardio da obrigação objetivamente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.149 (1)", "page_number": 149, "discipline": "Direito Civil", "legal_refs": ["Art. 395 CC"], "jurisprudence": ["RE 123456", "Enunciado 162 da III Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T21:17:51.380524+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=149", "doc_key": "13b3676f305a701f813e7ef5fb0baf88"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1f8052c54574c535c7d948253fbbaba0faad1f79a0df131b1febe995bbb09e89'),
  ('cpiuris2025::0cdf694d37280ef2756fc7e4f166c6d5', 'doutrina', 'cp_iuris', 'Direito Civil — Mora Ex Persona', '## Mora Ex Persona

A mora ex persona é necessária em todos os casos de mora, exigindo interpelação ou notificação por escrito para a constituição da mora. Gera responsabilidade civil pelo prejuízo causado ao credor.

### Conceitos
- **Mora Ex Persona**: necessária em todos os casos de mora
- **Interpelação**: notificação por escrito para a constituição da mora
- **Responsabilidade Civil**: prejuízos causados ao credor

### Referências legais
- Art. 395, do CC

### Dicas de prova
- Distinção entre mora ex persona e mora ex officio
- Importância da interpelação ou notificação por escrito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.149 (2)", "page_number": 149, "discipline": "Direito Civil", "legal_refs": ["Art. 395, do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:18:10.292245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=149", "doc_key": "0cdf694d37280ef2756fc7e4f166c6d5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '705c29f8a00ebeb4375897c5415e4148e3e0088c370f1c3ceb6bf2901585acfe'),
  ('cpiuris2025::2f572a713e28717c86a12de7f5abce4a', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil pela Integridade da Coisa', '## Responsabilidade Civil pela Integridade da Coisa

O devedor responde pelos prejuízos causados por sua mora, incluindo juros, atualização dos valores monetários e honorários de advogado. A responsabilidade do credor é determinada pela mora do credor, que ocorre quando ele se recusa a receber o pagamento no tempo e lugar indicados.

### Conceitos
- **Mora do Credor**: Ocorre quando o credor se recusa a receber o pagamento no tempo e lugar indicados.
- **Mora Subjetivamente Imputável**: Ocorre quando o devedor não cumpre a obrigação de forma voluntária, por culpa ou por dolo.
- **Mora Objetivamente Imputável**: Ocorre quando o devedor estava inadimplente perante o credor e o caso fortuito ou força maior ocorreu durante o atraso.

### Referências legais
- Art. 395, do CC
- Art. 399, do CC

### Dicas de prova
- Distinguir entre mora subjetivamente imputável e mora objetivamente imputável.
- Entender a noção de mora do credor e seus efeitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.150 (1)", "page_number": 150, "discipline": "Direito Civil", "legal_refs": ["Art. 395, do CC", "Art. 399, do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:18:42.959838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=150", "doc_key": "2f572a713e28717c86a12de7f5abce4a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '672ca20247c2c056ca09d05fc86094eaa28337dedbf0693558bf24a3ec53a743'),
  ('cpiuris2025::3f685dc82f42766b1159c1d3f5358218', 'doutrina', 'cp_iuris', 'Direito Civil — Mora do Credor e Responsabilidade pela Conservação da Coisa', '## Mora do Credor e Responsabilidade pela Conservação da Coisa

O credor não responde pela conservação da coisa se agir com dolo, mas deve ressarcir despesas de conservação. A mora do credor sujeita o devedor a receber a coisa pelo valor mais favorável ao devedor.

### Conceitos
- **Mora do Credor**: Ocorre quando o credor não recebe a coisa em tempo hábil
- **Responsabilidade pela Conservação da Coisa**: Obrigação do credor de ressarcir despesas de conservação e receber a coisa pelo valor mais favorável ao devedor
- **Dolo**: Ação com intenção de prejudicar o devedor

### Referências legais
- Art. 400 do Código Civil
- Art. 400 do CC

### Dicas de prova
- Distinção entre dolo e não-dolo
- Importância da estimação mais favorável ao devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.150 (2)", "page_number": 150, "discipline": "Direito Civil", "legal_refs": ["Art. 400 do Código Civil", "Art. 400 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:19:17.355651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=150", "doc_key": "3f685dc82f42766b1159c1d3f5358218"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a9918c9ec26f16b4b9b19742afe25b3b2e884610080a29bb5bf7813bb4853b4c'),
  ('cpiuris2025::ef1c96c4a5a25310e1badddc83b38b58', 'doutrina', 'cp_iuris', 'Direito Civil — Violação positiva do contrato', '## Violação positiva do contrato

A violação positiva do contrato ocorre quando o devedor não cumpre os deveres anexos da boa-fé objetiva, como confiança, cooperação e lealdade, mesmo que tenha cumprido a prestação em si. Isso pode ser considerado inadimplemento por si só.

### Conceitos
- **Boa-fé objetiva**: Padrão de comportamento ético esperado de todos em sociedade
- **Deveres anexos da boa-fé**: Confiança, cooperação, lealdade, informação e proteção

### Referências legais
- Art. 422 do CC
- Enunciado nº 24 do CJF

### Dicas de prova
- Entenda a boa-fé objetiva e seus deveres anexos
- Identifique quando a violação positiva do contrato pode ser considerada inadimplemento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.151 (1)", "page_number": 151, "discipline": "Direito Civil", "legal_refs": ["Art. 422 do CC", "Enunciado nº 24 do CJF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:19:44.690058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=151", "doc_key": "ef1c96c4a5a25310e1badddc83b38b58"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8707bb73989ebf7de890eb6c787febe5803873a47ebf8008fc6bb6974436d044'),
  ('cpiuris2025::b3c8f5ccc06443e00f6e6273e12d0b24', 'doutrina', 'cp_iuris', 'Direito Civil — Inadimplemento Fortuito', '## Inadimplemento Fortuito

O inadimplemento fortuito é a extinção da obrigação sem indenização, quando a obrigação é descumprida por fortuito ou força maior.

### Conceitos
- **Fortuito**: Ocorreza devido à sorte ou acaso
- **Força Maior**: Circunstância imprevisível que não pode ser evitada
- **Inadimplemento Fortuito**: Extinção da obrigação sem indenização, quando a obrigação é descumprida por fortuito ou força maior
- **Obrigação de Indenizar**: Obrigação de pagar danos causados ao credor
- **Imputabilidade**: A capacidade do devedor de se responsabilizar pelos danos causados

### Referências legais
- Art. 393, do CC

### Dicas de prova
- Diferenciar entre inadimplemento fortuito e obrigação de indenizar
- Entender a distinção entre imputável e inimputável em relação ao inadimplemento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.151 (2)", "page_number": 151, "discipline": "Direito Civil", "legal_refs": ["Art. 393, do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:20:10.259199+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=151", "doc_key": "b3c8f5ccc06443e00f6e6273e12d0b24"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c4aa3a3618314af5bdbb9422039b99cca9d4ec7bf0349c8d117440a5a46ac804'),
  ('cpiuris2025::ee5626dba6a4f65fb9b1d312b2480e05', 'doutrina', 'cp_iuris', 'Direito Civil — Inadimplemento das Obrigações', '## Inadimplemento das Obrigações

Descreve as formas de inadimplemento das obrigações, incluindo inadimplemento imputável e inimputável, bem como a teoria do adimplemento substancial.

### Conceitos
- **Inadimplemento imputável**: Ocorre quando as consequências são atribuídas ao devedor
- **Inadimplemento inimputável**: Ocorre quando as consequências não podem ser atribuídas ao devedor, por ausência de culpa
- **Teoria do adimplemento substancial**: A teoria que considera que a obrigação pode ser cumprida parcialmente, desde que a mora seja irrelevante

### Referências legais
- Art. 408 a 416 do CC

### Jurisprudência
- RECURSOS ESPECIAIS. DIREITO CIVIL. AÇÃO MONITÓRIA. NEGATIVA DE PRESTAÇÃO JURIDICIONAL. NÃO OCORRÊNCIA. CONTRATO DE PATROCÍNIO.
- INFORMATIVO N° 627 do STJ

### Dicas de prova
- Entenda a diferença entre inadimplemento imputável e inimputável
- Conheça a teoria do adimplemento substancial e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.152 (1)", "page_number": 152, "discipline": "Direito Civil", "legal_refs": ["Art. 408 a 416 do CC"], "jurisprudence": ["RECURSOS ESPECIAIS. DIREITO CIVIL. AÇÃO MONITÓRIA. NEGATIVA DE PRESTAÇÃO JURIDICIONAL. NÃO OCORRÊNCIA. CONTRATO DE PATROCÍNIO.", "INFORMATIVO N° 627 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T21:20:53.952156+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=152", "doc_key": "ee5626dba6a4f65fb9b1d312b2480e05"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '181c0ae38cac93208552883750fac0041d77b684e17d8bc5b929d5b123ae3795'),
  ('cpiuris2025::1a16d77134e96a1fac2a4e71cbe2a968', 'doutrina', 'cp_iuris', 'Direito Civil — Arras e Compensação', '## Arras e Compensação

As arras são uma forma de antecipação das perdas e danos, podendo ser confirmatórias ou penitenciais, com objetivo de reforçar a obrigatoriedade contratual ou viabilizar o arrependimento.

### Conceitos
- **Arras**: sinal ou coisa paga para demonstrar comprometimento em relação à obrigação principal
- **Compensatória**: forma de antecipação das perdas e danos, sem cumulação com indenização
- **Confirmatória**: modalidade de arras que reforça a obrigatoriedade contratual
- **Penitenciais**: modalidade de arras que viabiliza eventual arrependimento

### Referências legais
- Art. 417 a 420 do CC

### Dicas de prova
- Entenda a diferença entre confirmatória e penitenciais
- Conheça o conceito de arras como forma de antecipação das perdas e danos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.152 (2)", "page_number": 152, "discipline": "Direito Civil", "legal_refs": ["Art. 417 a 420 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:21:18.854272+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=152", "doc_key": "1a16d77134e96a1fac2a4e71cbe2a968"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3e13de2ad7974a91b0f732cce55f52be872449c2d1379054e35d060ba1437661'),
  ('cpiuris2025::4450cbbc1c64dbe72f6ad79e13cc2def', 'doutrina', 'cp_iuris', 'Direito Civil — Redução Equitativa e Readequação de Dívidas', '## Redução Equitativa e Readequação de Dívidas

Discute-se a redução equitativa e readequação de dívidas, incluindo conversão, cotação, data da contratação, verba honorária e proveito econômico, bem como o controle judicial do valor das multas compensatórias pactuadas.

### Conceitos
- **Redução Equitativa**: Método de redução da dívida que visa equilibrar as obrigações e os direitos dos contrapartes.
- **Readequação**: Ajuste das obrigações e dos direitos para refletir as mudanças nas condições econômicas ou sociais.
- **Conversão**: Mudança da natureza de uma obrigação, transformando-a em outra com características diferentes.
- **Cotação**: Determinação do valor de uma dívida para fins de redução equitativa ou readequação.
- **Data da Contratação**: Importância da data em que foi firmado o contrato, na determinação da redução equitativa e readequação das dívidas.
- **Verba Honorária**: Valor adicionado ao valor principal de uma obrigação para compensar os custos de negociação ou procedimento judicial.
- **Proveito Econômico**: Benefício econômico concedido a um dos contrapartes em decorrência de uma redução equitativa ou readequação das dívidas.

### Referências legais
- Art. 2.º, inciso IV, do Código de Processo Civil
- Súmula 346/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Redução Equitativa e Readequação de Dívidas

### Dicas de prova
- Entenda a distinção entre redução equitativa e readequação das dívidas.
- Conheça as regras para determinar a cotação e o proveito econômico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.153 (1)", "page_number": 153, "discipline": "Direito Civil", "legal_refs": ["Art. 2.º, inciso IV, do Código de Processo Civil", "Súmula 346/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Redução Equitativa e Readequação de Dívidas"], "confidence": 0.8, "extracted_at": "2026-05-25T21:22:08.659315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=153", "doc_key": "4450cbbc1c64dbe72f6ad79e13cc2def"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '67efec216aaba39588c866c9629f509f22728f5bed7b26d56fac96e533de3b30'),
  ('cpiuris2025::9c9f15c86714563424e4f4a5d1046a32', 'doutrina', 'cp_iuris', 'Direito Civil — Cláusulas Penais e Execução Fórmula', '## Cláusulas Penais e Execução Fórmula

A decisão agravada deve ser reconsiderada pois o recurso especial é tempestivo, comprovado a suspensão do prazo recursal. A jurisprudência da Corte permite reduzir o valor da cláusula penal caso evidenciado seu excesso.

### Conceitos
- **Cláusulas Penais**: cláusulas que imponham sanções ao devedor em caso de inadimplência
- **Execução Fórmula**: procedimento pelo qual o juiz executa a sentença, sem necessidade de recurso do devedor

### Referências legais
- Art. 273 do Código de Processo Civil

### Jurisprudência
- REsp 1803803/RJ
- Súmula 342/STJ

### Dicas de prova
- Distinção entre cláusulas penais e execução fórmula
- Evidência de excesso de cláusula penal
- Suspensão do prazo recursal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.153 (2)", "page_number": 153, "discipline": "Direito Civil", "legal_refs": ["Art. 273 do Código de Processo Civil"], "jurisprudence": ["REsp 1803803/RJ", "Súmula 342/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T21:22:47.640706+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=153", "doc_key": "9c9f15c86714563424e4f4a5d1046a32"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '10afc6afda69cadcbb1bb3efa5b64d3101834cc2b20f29ae3a81577212b4e99f'),
  ('cpiuris2025::1435228aef2958deb97c4090b9584fd9', 'doutrina', 'cp_iuris', 'Direito Civil — Cláusula Penal Compensatória em Contrato de Afretamento', '## Cláusula Penal Compensatória em Contrato de Afretamento

A cláusula penal compensatória é obrigação pecuniária que prefixa os prejuízos decorrentes do descumprimento do contrato. A sua existência depende da vontade das partes externada no contrato.

### Conceitos
- **Cláusula Penal Compensatória**: obrigação pecuniária que prefixa os prejuízos decorrentes do descumprimento do contrato
- **Solidariedade**: decorre da vontade das partes externada no contrato firmado
- **Autonomia da Vontade**: força obrigatória dos contratos

### Referências legais
- Art. 473 do Código de Processo Civil de 2015

### Jurisprudência
- Súmula nº 282/STF

### Dicas de prova
- Entenda a natureza da cláusula penal compensatória e sua relação com a solidariedade
- Conheça a regra da autonomia da vontade em contratos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.154 (1)", "page_number": 154, "discipline": "Direito Civil", "legal_refs": ["Art. 473 do Código de Processo Civil de 2015"], "jurisprudence": ["Súmula nº 282/STF"], "confidence": 0.8, "extracted_at": "2026-05-25T21:23:17.238176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=154", "doc_key": "1435228aef2958deb97c4090b9584fd9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '243f82c39ba9a1da5893bdc8674767459811c72ec341353bbd59e358e0fd0621'),
  ('cpiuris2025::ea193760a18cee3ec742e59699417fc7', 'doutrina', 'cp_iuris', 'Direito Civil — Cláusula Penal Compensatória e Arras', '## Cláusula Penal Compensatória e Arras

A cláusula penal compensatória é um pacto acessório de natureza pessoal que prevê a imposição de uma penalidade em caso de inexecução do contrato. As arras são quantias ou bens móveis entregues por um dos contratantes como garantia do negócio, com finalidades confirmatórias, pagamentos e indenização.

### Conceitos
- **Cláusula Penal Compensatória**: Pacto acessório de natureza pessoal que prevê a imposição de uma penalidade em caso de inexecução do contrato
- **Arras**: Quantias ou bens móveis entregues por um dos contratantes como garantia do negócio
- **Pacto Acessório**: Acordo adicional ao contrato principal, de natureza pessoal e não obrigatório
- **Natureza Pessoal**: Caracterização da cláusula penal compensatória como pacto acessório de natureza pessoal
- **Cláusula Indenizatória**: Cláusula que determina a indenização em caso de inexecução do contrato

### Referências legais
- Art. 1.022 do CPC/2015
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Cláusulas Penais e Arras

### Dicas de prova
- Distinção entre cláusula penal compensatória e indenizatória
- Entendimento da natureza pessoal das cláusulas penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.154 (2)", "page_number": 154, "discipline": "Direito Civil", "legal_refs": ["Art. 1.022 do CPC/2015", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Cláusulas Penais e Arras"], "confidence": 0.8, "extracted_at": "2026-05-25T21:23:56.481196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=154", "doc_key": "ea193760a18cee3ec742e59699417fc7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b494b10beb6892df91d947c97314fde9c5d3dd007e968dc9ecf21d07e137d422'),
  ('cpiuris2025::dd9aa144f568ea253143c14acbd8bfa8', 'doutrina', 'cp_iuris', 'Direito Civil — Regramento das arras e indenização por inexecução do contrato', '## Regramento das arras e indenização por inexecução do contrato

O regramento das arras se faz presente não apenas quando há lícito arrependimento, mas principalmente quando ocorre a inexecução do contrato. As arras atuarão como indenização prefixada em favor da parte inocente pelo inadimplemento.

### Conceitos
- **arras**: indenização prefixada em favor de uma das partes por inadimplemento do contrato
- **inexecução do contrato**: ocorrência que justifica a indenização pelas arras
- **princípio do non bis in idem**: proibição da dupla condenação a mesmo título
- **taxa mínima de indenização**: valor das arras previsto no art. 419 do CC

### Referências legais
- Art. 417 a 420 do CC/02

### Jurisprudência
- REsp 1617652/DF

### Dicas de prova
- Distinção entre lícito arrependimento e inexecução do contrato
- Prevalência da pena de perda das arras sobre a cláusula penal compensatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.155 (1)", "page_number": 155, "discipline": "Direito Civil", "legal_refs": ["Art. 417 a 420 do CC/02"], "jurisprudence": ["REsp 1617652/DF"], "confidence": 0.8, "extracted_at": "2026-05-25T21:24:38.171075+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=155", "doc_key": "dd9aa144f568ea253143c14acbd8bfa8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '42eb77c2f44182d7883bc2fd89c537a9e1c5ccca4614451eb1fb9571b7fdfbb3'),
