- **Mora**: Omissão ou atraso na prestação de uma obrigação
- **Perdas e danos**: Consequências da não cumprimento de uma obrigação, incluindo prejuízos e lucros cessantes

### Referências legais
- Art. 173 do CC
- Súmula 137 do STF

