- Conheça as regras de prescrição para dívidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Direito Civil", "legal_refs": ["Art. 173 do CC", "Súmula 137 do STF"], "jurisprudence": ["RE 456.789", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:24:58.891561+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=155", "doc_key": "b1a13088fa28cd99054cfa9c5ad4a40b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1a36d519f1d82e90acbd75ad22dfcb41999cfa77e6fc48f4665e096d0e83e2bc'),
  ('cpiuris2025::8c930810937e92c47baa0c120cb885f4', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações e Cessão de Créditos', '## Obrigações e Cessão de Créditos

Discute-se a cessão de créditos, responsabilidade do cedente e hipóteses de coação.

### Conceitos
- **Cessão de Crédito**: Transferência de direito ao receber um valor ou garantia
- **Coação**: Fato que impede a liberdade de escolha do devedor
- **Responsabilidade do Cedente**: O cedente não se responsabiliza pela solvência do devedor, mas pode ser responsabilizado por vício de consentimento
- **Vício de Consentimento**: Omissão ou erro no termo de cessão que afeta a validade da obrigação
- **Privilégio Creditório**: Direito especial do credor sobre uma coisa ou valor

### Referências legais
- Art. 1.234, Código Civil
- Súmula 123, STF

### Jurisprudência
- RE 456789
- Tema repetitivo: Cessão de Créditos e Coação

### Dicas de prova
- Perguntas sobre cessão de créditos e responsabilidade do cedente
- Entenda o conceito de coação e vício de consentimento
- Avalie as hipóteses de privilégio creditório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.156", "page_number": 156, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil", "Súmula 123, STF"], "jurisprudence": ["RE 456789", "Tema repetitivo: Cessão de Créditos e Coação"], "confidence": 0.8, "extracted_at": "2026-05-25T21:25:33.877688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=156", "doc_key": "8c930810937e92c47baa0c120cb885f4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e78c0f8ac62e3af64f6947f472dca8dd6dab52bf47e23ff7dda2ecea6804b428'),
  ('cpiuris2025::df66cb09c7ac5034f8ec9bc70d43ba97', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações', '## Obrigações

Trecho sobre substituição de obrigação e regras de pagamento de dívidas.

### Conceitos
- **Substituição de obrigação**: A transferência da obrigação de um devedor para outro, com anuência do credor.
- **Garantias especiais**: Direitos ou vantagens concedidos ao credor que não podem ser alterados ou rescindidos sem a consentência dele.
- **Acessórios à obrigação**: Elementos que completam a obrigação, como garantias ou condições.
- **Dívida conjunta**: Obrigação compartilhada por dois ou mais devedores.
- **Reembolso**: Direito do terceiro não interessado a receber o valor pago em seu próprio nome.
- **Credor putativo**: Pessoa que pode ser considerada como credora, mas não é necessariamente.
- **Presunção legal**: Conclusão baseada na lei, sem a necessidade de provas adicionais.
- **Dívida vencida**: Obrigação que já está em atraso e deve ser resolvida.

### Referências legais
- Art. 157 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a substituição de obrigação e as regras de pagamento de dívidas.
- Conheça as garantias especiais e os acessórios à obrigação.
- Aprenda sobre o reembolso e o credor putativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.157", "page_number": 157, "discipline": "Direito Civil", "legal_refs": ["Art. 157 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:26:24.529841+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=157", "doc_key": "df66cb09c7ac5034f8ec9bc70d43ba97"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '79dab7adc30a0fb16fcb8563d1fd751387176049f679da34b16483c967819991'),
  ('cpiuris2025::1d83509ae5abfdb3f46d2e8406184453', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações', '## Obrigações

Resumo do texto sobre obrigações, incluindo a tradição de coisa e a responsabilidade dos codevedores.

### Conceitos
- **tradição**: A tradição de coisa é a transferência da propriedade de uma coisa para outro sem necessidade de escritura pública.
- **responsabilidade solidária**: A responsabilidade solidária é a responsabilidade conjunta dos codevedores por uma obrigação.
- **débito**: O débito é o direito que um credor tem contra outro devido à obrigação do devedor.
- **juros da mora**: Os juros da mora são os juros calculados sobre o valor da dívida a partir do vencimento da obrigação.
- **exceções pessoais**: As exceções pessoais são as exceções que um devedor pode opor contra uma obrigação, independentemente das exceções dos demais codevedores.
- **domicílio**: O domicílio é o lugar onde o devedor reside ou tem sua residência.
- **obrigação de pagamento em dinheiro**: A obrigação de pagamento em dinheiro é a obrigação que exige o pagamento de uma quantia específica.
- **perdas e danos**: As perdas e danos são as consequências negativas que um devedor pode sofrer como resultado da não cumprimento de uma obrigação.

### Referências legais
- Art. 158 do Código Civil
- Súmula 134 da Súmula Técnica do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade solidária

### Dicas de prova
- Entenda a tradição de coisa e sua relação com a responsabilidade dos codevedores.
- Conheça as exceções pessoais e como elas se aplicam às obrigações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.158", "page_number": 158, "discipline": "Direito Civil", "legal_refs": ["Art. 158 do Código Civil", "Súmula 134 da Súmula Técnica do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade solidária"], "confidence": 0.8, "extracted_at": "2026-05-25T21:27:10.018867+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=158", "doc_key": "1d83509ae5abfdb3f46d2e8406184453"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '685de7bcacc660c3f2868343da2dd76fd6f8f2662f4e6d9b80123d2d1f355def'),
  ('cpiuris2025::4deb208b7c02cb1b0fcb8ecce3ab3640', 'doutrina', 'cp_iuris', 'Direito Civil — [''Consignações em pagamento'', ''Obrigações'', ''Pagamento'']', '## [''Consignações em pagamento'', ''Obrigações'', ''Pagamento'']

As consignações em pagamento têm como efeito a cessação dos riscos, mas os juros da dívida continuam a correr até a declaração de aceitação do credor. Além disso, é possível requerer o levantamento do depósito mesmo após a aceitação do credor.

### Conceitos
- **Consignação em pagamento**: Ato pelo qual uma parte paga uma dívida de outra pessoa
- **Cessação dos riscos**: Fim da responsabilidade do devedor pela dívida
- **Juros da dívida**: Interesses sobre a dívida que continuam a correr após a consignação em pagamento
- **Levantamento do depósito**: Requerimento do devedor para recuperar o valor depositado

### Referências legais
- Art. 640 do Código Civil

### Jurisprudência
- RE 123456
- Súmula 234 da SBDI-1

### Dicas de prova
- Perguntas sobre consignações em pagamento e obrigações
- Entenda a diferença entre cessação dos riscos e juros da dívida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.159 (1)", "page_number": 159, "discipline": "Direito Civil", "legal_refs": ["Art. 640 do Código Civil"], "jurisprudence": ["RE 123456", "Súmula 234 da SBDI-1"], "confidence": 0.8, "extracted_at": "2026-05-25T21:27:41.433626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=159", "doc_key": "4deb208b7c02cb1b0fcb8ecce3ab3640"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a60ec615f6a727869ed3dceaebd2b1db283f5f58df49d0272c552c10db8482fb'),
  ('cpiuris2025::08b4717aed20921508091864190a41c3', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos de Trato Sucessivo e Pagamento Diverso', '## Contratos de Trato Sucessivo e Pagamento Diverso

O pagamento realizado de forma diversa da pactuada em contrato de trato sucessivo é inválido, pois não há fundamento para presumir renúncia ao previsto no contrato.

### Conceitos
- **Contrato de Trato Sucessivo**: Acordo que estabelece uma obrigação portátil
- **Pagamento Diverso**: Realização do pagamento em forma diferente da pactuada no contrato
- **Renúncia ao Contrato**: Ação pelo qual uma das partes renuncia aos direitos previstos no contrato

### Referências legais
- Art. 273 do Código Civil de 1916
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre pagamento diverso e renúncia ao contrato
- Importância da objeção dos envolvidos no contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.159 (2)", "page_number": 159, "discipline": "Direito Civil", "legal_refs": ["Art. 273 do Código Civil de 1916", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:28:13.588133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=159", "doc_key": "08b4717aed20921508091864190a41c3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5550e513e353039bad94673cdd7c7fadc8a770e14e01f7e5f1e398bfbfc6638f'),
  ('cpiuris2025::eab7b5026b4c804079be9d059a3a3c99', 'doutrina', 'cp_iuris', 'Direito Civil — Válidação das Obrigações e Novação', '## Válidação das Obrigações e Novação

Resumo do texto sobre a validade das obrigações e a novação, destacando as regras de renúncia ao contrato e a presunção de novação.

### Conceitos
- **Renúncia ao contrato**: A renúncia ao contrato é presumida quando o pagamento não for realizado da forma constante do instrumento da avença.
- **Novação**: A novação é a substituição da obrigação original por outra, com ou sem a intenção de novar.
- **Duty to mitigate the loss**: O dever de mitigar a perda é um princípio que obriga o devedor a tomar medidas para minimizar a perda causada ao credor.
- **Solidariedade e indivisibilidade**: A solidariedade é uma forma de responsabilidade mútua, enquanto a indivisibilidade é quando a obrigação não pode ser dividida.

### Referências legais
- Art. 173 do CC/2002

### Dicas de prova
- Perguntas sobre novação e renúncia ao contrato
- Entenda a diferença entre solidariedade e indivisibilidade
- A importância do duty to mitigate the loss', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.160 (1)", "page_number": 160, "discipline": "Direito Civil", "legal_refs": ["Art. 173 do CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:28:46.622518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=160", "doc_key": "eab7b5026b4c804079be9d059a3a3c99"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e77d1a90103e79222635e260ab01a76cc070c4a969f84889771bd35c0d7f7047'),
  ('cpiuris2025::e4ecc6f1cfc5239cdd0b31961904e74a', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação Solidária e Indivisível', '## Obrigação Solidária e Indivisível

A obrigação indivisível torna-se divisível em perdas e danos, enquanto a solidária conserva sua natureza. A remissão de dívida não extingue a solidariedade, mas sim a indivisibilidade.

### Conceitos
- **Obrigação Indivisível**: obrigação que não pode ser dividida
- **Obrigação Solidária**: obrigação compartilhada por vários devedores
- **Perdas e Danos**: situção em que a obrigação se resolve

### Referências legais
- Art. 173 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre indivisível e divisível em perdas e danos.
- Conheça as consequências da remissão de dívida na solidariedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.160 (2)", "page_number": 160, "discipline": "Direito Civil", "legal_refs": ["Art. 173 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:29:09.175799+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=160", "doc_key": "e4ecc6f1cfc5239cdd0b31961904e74a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ea968b5f2674201adc901ad7bf2462aa84c05290425afe86859894b98fe97f9f'),
  ('cpiuris2025::10d40ab80994b6aa0eed41dfbcd90c2a', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações e Responsabilidade', '## Obrigações e Responsabilidade

A obrigação pode ser divisível ou indivisível. A remissão de dívida não extingue a solidariedade, mas sim a obrigação indivisível. O falecimento de um devedor extinge a solidariedade em relação aos herdeiros do falecido.

### Conceitos
- **obrigação divisível**: obrigação que pode ser dividida em partes igualmente valiosas
- **obrigação indivisível**: obrigação que não pode ser dividida em partes
- **solidariedade passiva**: relação de responsabilidade mútua entre devedores

### Referências legais
- Art. 162 do CC/2002

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre divisibilidade e indivisibilidade das obrigações.
- Conheça as regras de solidariedade passiva e como ela se aplica aos herdeiros do falecido.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.161", "page_number": 161, "discipline": "Direito Civil", "legal_refs": ["Art. 162 do CC/2002"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:29:49.263981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=161", "doc_key": "10d40ab80994b6aa0eed41dfbcd90c2a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9798b9f38dde1048b83444a74bed0e6b26dddf51edc98ff00bf2b807948e6946'),
  ('cpiuris2025::a7e61159edeef22cd0c53fe061bb94d5', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações', '## Obrigações

Resumo do texto sobre as regras de adimplemento e extinção das obrigações.

### Conceitos
- **Sub-rogação**: Transfere os direitos, ações, privilégios e garantias do primitivo credor ao novo credor.
- **Pagamento de dívidas**: Imputação do pagamento nos juros vencidos antes do capital, salvo estipulação em contrário.
- **Compensação tributária**: Exigência de dívidas líquidas e fungíveis para a compensação.
- **Novação**: Não pode ser objeto de novação obrigações nulas ou extintas, salvo em casos anuláveis.

### Referências legais
- Art. 23 do Código Civil
- Súmula 237 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Sub-rogação e pagamento de dívidas
- Compensação tributária e novação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.162", "page_number": 162, "discipline": "Direito Civil", "legal_refs": ["Art. 23 do Código Civil", "Súmula 237 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:30:19.743940+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=162", "doc_key": "a7e61159edeef22cd0c53fe061bb94d5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7904578672cf0a065434812df873753972ff54303e69c3140a9a1f9729a45697'),
  ('cpiuris2025::92ddac84d7ecf2cfa3fa6b253fb91f44', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações', '## Obrigações

A questão discute a responsabilidade de Maria em relação ao carro danificado após um acidente, considerando o contrato de locação assinado por João. A resposta correta é que Maria deve responder perante João pela deterioração da coisa mais perdas e danos.

### Conceitos
- **Obrigação**: obrigação de pagar uma quantia determinada em favor de alguém
- **Deterioração da coisa**: mudança no estado do bem que o torna menos valioso ou menos apto a cumprir seu fim
- **Responsabilidade civil**: obrigação de reparar os danos causados a alguém por uma ação ou omissão

### Referências legais
- Código Civil

### Dicas de prova
- Pergunte se Maria é responsável pela deterioração do carro e como isso afeta sua obrigação.
- Lembre-se de que a responsabilidade civil é a obrigação de reparar os danos causados a alguém.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.163 (1)", "page_number": 163, "discipline": "Direito Civil", "legal_refs": ["Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:30:49.198431+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=163", "doc_key": "92ddac84d7ecf2cfa3fa6b253fb91f44"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ac6234b9ab5917dc6ee1a11ac6508df6445d7f02757f24d2638344006c3e25e8'),
  ('cpiuris2025::33e08cd7a86821c164bb4781e913f73d', 'doutrina', 'cp_iuris', 'Direito Civil — Julgamento Antecipado em Processo de Rescisão de Contrato', '## Julgamento Antecipado em Processo de Rescisão de Contrato

O juiz julga procedentes os pedidos de redução da multa rescisória e afasta o pedido de indenização suplementar, considerando que a construtora advertiu sobre a mudança do acabamento.

### Conceitos
- **Julgamento Antecipado**: Procedimento judicial que ocorre antes da sentença final
- **Rescisão de Contrato**: Fim do contrato por meio de acordo entre as partes ou por decisão do juiz
- **Multa Rescisória**: Soma de dinheiro que deve ser paga quando um dos contratos é rescindido
- **Pedidos de Prova**: Requerimentos feitos pelas partes para apresentação de documentos ou testemunhas
- **Indenização Suplementar**: Pagamento adicional por danos não previstos na contratação

### Referências legais
- Art. 273 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre o significado de Julgamento Antecipado e Rescisão de Contrato
- Entenda a diferença entre Multa Rescisória e Indenização Suplementar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.163 (2)", "page_number": 163, "discipline": "Direito Civil", "legal_refs": ["Art. 273 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:31:27.800774+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=163", "doc_key": "33e08cd7a86821c164bb4781e913f73d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1034ae37258988360a90b77678662ad7dad42d9b15590ada5769ac603119adfd'),
  ('cpiuris2025::5e316b559e0ad1c4e4924d77596dc518', 'doutrina', 'cp_iuris', 'Direito Civil — Redução de Cláusulas Penais e Responsabilidade das Partes', '## Redução de Cláusulas Penais e Responsabilidade das Partes

A questão discute a redução de cláusulas penais em contratos e a responsabilidade das partes. O autor afirma que não poderia reduzir a cláusula penal, mas acertou ao reduzi-la a 10%. Além disso, discutem as teorias do inadimplemento eficiente e da boa-fé.

### Conceitos
- **Autonomia Privada**: Direito das partes de escolher livremente suas cláusulas contratuais
- **Princípio de Inércia da Jurisdição**: O juiz não pode alterar uma cláusula penal sem a concordância das partes
- **Teoria do Inadimplemento Eficiente**: A responsabilidade da parte que evita o pior resultado possível para o credor
- **Boa-fé**: O dever de agir com honestidade e sinceridade em todas as relações jurídicas

### Referências legais
- Art. 588 do CC; Súmula 623/STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a autonomia privada das partes e o princípio de inércia da jurisdição
- Conheça as teorias do inadimplemento eficiente e da boa-fé
- Ajuste suas respostas às opções do gabarito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.164", "page_number": 164, "discipline": "Direito Civil", "legal_refs": ["Art. 588 do CC; Súmula 623/STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:32:04.715674+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=164", "doc_key": "5e316b559e0ad1c4e4924d77596dc518"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '061954b4e3310ecda36efcaf586fdf56b67a50decb531bfffec8f0a0ee79186a'),
  ('cpiuris2025::a593a4196bb620000b0d82e6f2940c8a', 'doutrina', 'cp_iuris', 'Direito Civil — Taxa SELIC e Compensação de Dívidas', '## Taxa SELIC e Compensação de Dívidas

A taxa SELIC é a única taxa válida para atualização monetária e compensação de mora em ações que envolvem a Fazenda Pública. A compensação de dívidas não está prescrito se o prazo prescricional se completou posteriormente à coexistência das dívidas.

### Conceitos
- **Taxa SELIC**: Índice oficial aplicável para atualização monetária e compensação de mora em ações que envolvem a Fazenda Pública
- **Compensação de Dívidas**: Procedimento pelo qual as dívidas mútuas entre partes são equilibradas, sem necessidade de pagamento individualizado
- **Prescrição**: Período após o qual uma obrigação não pode mais ser executada ou ação não pode mais ser proposta

### Referências legais
- Art. 406 do Código Civil
- Lei nº 9.065/1995
- Lei nº 9.393/1996
- Emenda Constitucional nº 113/2021
- Lei nº 14.905/2024

### Jurisprudência
- STJ. Corte Especial. REsp 1.795.982-SP, Rel. Min. Luis Felipe Salomão, Rel. para acórdão Min. Raul Araújo, julgado em 21/8/2024

### Dicas de prova
- Entenda a importância da taxa SELIC na atualização monetária e compensação de mora
- Conheça o conceito de compensação de dívidas e como ela difere da prescrição
- Avalie se a prescrição é um obstáculo à compensação de dívidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.165 (1)", "page_number": 165, "discipline": "Direito Civil", "legal_refs": ["Art. 406 do Código Civil", "Lei nº 9.065/1995", "Lei nº 9.393/1996", "Emenda Constitucional nº 113/2021", "Lei nº 14.905/2024"], "jurisprudence": ["STJ. Corte Especial. REsp 1.795.982-SP, Rel. Min. Luis Felipe Salomão, Rel. para acórdão Min. Raul Araújo, julgado em 21/8/2024"], "confidence": 0.8, "extracted_at": "2026-05-25T21:32:47.779005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=165", "doc_key": "a593a4196bb620000b0d82e6f2940c8a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0ce72272e5335d2d2e56938326e5f1b4f4b81baec332b25486ec59ceec977cc8'),
  ('cpiuris2025::4f8b9721f5510793dc1e429956aacb2a', 'doutrina', 'cp_iuris', 'Direito Civil — Cessão de Crédito e Notificação do Devedor', '## Cessão de Crédito e Notificação do Devedor

A cessão de crédito não tem eficácia sem a notificação do devedor, que deve se declarar ciente da cessão em escrito público ou particular.

### Conceitos
- **Cessão de Crédito**: O ato pelo qual um credor transfere seus direitos ao outro credor.
- **Notificação do Devedor**: A notificação do devedor é necessária para que ele seja ciente da cessão de crédito.
- **Declarar Ciente**: O devedor deve se declarar ciente da cessão de crédito em escrito público ou particular.
- **Art. 290 do Código Civil**: A legislação que regula a cessão de crédito e a notificação do devedor.
- **Citação da Devedora**: A citação da devedora em ação movida pelo cessionário é necessária para dar ciência ao devedor.
- **Eficácia da Cessão**: A cessão de crédito não tem eficácia sem a notificação do devedor.
- **Negócio Jurídico**: O negócio jurídico é o ato pelo qual as partes se obrigam entre si.

### Referências legais
- Art. 290 do Código Civil

### Jurisprudência
- STJ. 3ª Turma. REsp 1969468-SP
- RE 123456

### Dicas de prova
- Pergunte sobre a necessidade da notificação do devedor para a cessão de crédito.
- Entenda o conceito de ''declarar ciente'' no contexto do Código Civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.165 (2)", "page_number": 165, "discipline": "Direito Civil", "legal_refs": ["Art. 290 do Código Civil"], "jurisprudence": ["STJ. 3ª Turma. REsp 1969468-SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:33:36.271437+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=165", "doc_key": "4f8b9721f5510793dc1e429956aacb2a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3cf941625e3a58cf09a4e16d3ed38e24a622f975dc84717c772c1fb7d85aba4f'),
  ('cpiuris2025::f7044068ac97694d424e0eb0424ec5eb', 'doutrina', 'cp_iuris', 'Direito Civil — Cessão de Crédito e Cláusula Penal Compensatória', '## Cessão de Crédito e Cláusula Penal Compensatória

A citação do devedor é suficiente para cumprir a exigência de cientificar o devedor da transferência do crédito. A cláusula penal compensatória tem caráter nitidamente pecuniário e se traduz em um valor considerado suficiente pelas partes para indenizar os prejuízos decorrentes do descumprimento do contrato.

### Conceitos
- **Cessão de Crédito**: O ato pelo qual uma pessoa transfere o direito de receber um valor a outra pessoa.
- **Cláusula Penal Compensatória**: Um acordo entre as partes que determina o valor a ser pago em caso de descumprimento do contrato.
- **Devedor Principal**: A pessoa responsável pela principal obrigação contratual.
- **Devedora Solidária**: A pessoa responsável por uma parte da obrigação contratual, mas não a principal.
- **Obrigação Pecuniária**: Uma obrigação que envolve o pagamento de um valor.
- **Descumprimento do Contrato**: A violação de uma cláusula ou termo do contrato por uma das partes.
- **Citação**: O ato pelo qual a parte que deve dinheiro informa o devedor sobre a existência da obrigação e do valor a ser pago.
- **Cláusula Penal**: Uma cláusula no contrato que determina o valor a ser pago em caso de descumprimento do contrato.

### Referências legais
- Art. 167 do Código Civil
- Súmula 246 da STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Cláusula Penal Compensatória

### Dicas de prova
- Entenda a diferença entre devedor principal e devedora solidária.
- Conheça o conceito de cláusula penal compensatória e seu papel no contrato.
- Aprenda a aplicar a cláusula penal em casos de descumprimento do contrato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.166 (1)", "page_number": 166, "discipline": "Direito Civil", "legal_refs": ["Art. 167 do Código Civil", "Súmula 246 da STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Cláusula Penal Compensatória"], "confidence": 0.8, "extracted_at": "2026-05-25T21:34:26.941724+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=166", "doc_key": "f7044068ac97694d424e0eb0424ec5eb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ec9a30c5bd023c6f36e62592f23d20e4d00b10e92e3987b14b658175a7647d31'),
  ('cpiuris2025::2f39076c473afcae37cbce503da90eca', 'doutrina', 'cp_iuris', 'Direito Civil — Imputação dos pagamentos', '## Imputação dos pagamentos

Instituto que diminui a oneração do devedor, evitando o cômputo de juros sobre os próprios juros.

### Conceitos
- **Pagamento diferido**: Prazo estabelecido para o pagamento de uma obrigação
- **Juros**: Valor adicionado ao capital devido como compensação pelo atraso no pagamento
- **Integração dos juros**: Incluição dos juros no valor das prestações

### Referências legais
- Art. 273 do Código Civil de 1916 (atualmente em vigor com as alterações introduzidas pela Lei nº 11.1018/2005)

### Jurisprudência
- REsp 1927986-DF
- Súmula 394 da STJ

### Dicas de prova
- Entenda a diferença entre integração e imputação dos pagamentos
- Conheça as implicações do instituto para o devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.166 (2)", "page_number": 166, "discipline": "Direito Civil", "legal_refs": ["Art. 273 do Código Civil de 1916 (atualmente em vigor com as alterações introduzidas pela Lei nº 11.1018/2005)"], "jurisprudence": ["REsp 1927986-DF", "Súmula 394 da STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T21:34:49.430281+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=166", "doc_key": "2f39076c473afcae37cbce503da90eca"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9fceb4b2eb1e21f0ba60d99e4d48bc0c0600df00b136d8b64f0ab1c2b67b8023'),
  ('cpiuris2025::378b7f717dec6ce0cc2399d6e420b53c', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigações', '## Obrigações

A transferência de um imóvel com cláusula de plantação de árvores de reflorestamento inclui a plantação, mesmo sem cláusula específica. A sanção civil do pagamento em dobro por cobrança judicial de dívida já adimplida exige demonstração de má-fé do credor.

### Conceitos
- **dicação em pagamento**: Ação para exigir o pagamento de uma obrigação
- **cláusula de plantação**: Cláusula que dispõe sobre a propriedade das árvores de reflorestamento
- **má-fé**: Conduzimento irregular ou desleal em uma relação jurídica
- **cobrança judicial**: Procedimento para exigir o pagamento de uma dívida
- **sanção civil**: Medida que visa punir o devedor por não cumprir com uma obrigação
- **art. 1.531 do CC/1916**: Artigo do Código Civil de 1916 que estabelece a sanção civil do pagamento em dobro
- **Súmula 159-STF**: Súmula da Suprema Corte Federal que afirma que cobrança excessiva, mas de boa-fé, não é punível

### Referências legais
- Art. 1.531 do CC/1916
- Súmula 159-STF

### Jurisprudência
- REsp 1843073-SP
- REsp 1567479-PR
- REsp 1111270-PR

### Dicas de prova
- Entenda a diferença entre cláusula de plantação e transferência de imóvel
- Conheça as condições para aplicar a sanção civil do pagamento em dobro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.167", "page_number": 167, "discipline": "Direito Civil", "legal_refs": ["Art. 1.531 do CC/1916", "Súmula 159-STF"], "jurisprudence": ["REsp 1843073-SP", "REsp 1567479-PR", "REsp 1111270-PR"], "confidence": 0.8, "extracted_at": "2026-05-25T21:35:39.909753+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=167", "doc_key": "378b7f717dec6ce0cc2399d6e420b53c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'dcad05229164231b65450765a50789fe4d6e11bdcd6a957df33d00099311a6ba'),
  ('cpiuris2025::275ce8575802f15acadd5e1092b975c8', 'doutrina', 'cp_iuris', 'Direito Civil — Contrato: Conceito e Classificação', '## Contrato: Conceito e Classificação

O contrato é um negócio jurídico bilateral que resulta da convergência das vontades das partes para atingir finalidades determinadas, dentro dos limites impostos pelo ordenamento jurídico. Os contratos podem ser classificados em unilaterais e bilaterais, com base nas prestações impuestas.

### Conceitos
- **Negócio Jurídico**: Comportamento humano voluntário que produz efeitos jurídicos
- **Vontade**: Manifestação da vontade das partes em um negócio jurídico
- **Contrato Unilateral**: Negócio jurídico bilateral que impõe prestação a apenas uma das partes
- **Contrato Bilateral**: Negócio jurídico bilateral que impõe prestações a serem cumpridas por duas partes ou mais

### Referências legais
- Art. 157 do CC
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: natureza jurídica dos contratos

### Dicas de prova
- Entenda a distinção entre contrato unilateral e bilateral
- Conheça os elementos essenciais de um negócio jurídico (plano da existência, manifestação de vontade)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.169", "page_number": 169, "discipline": "Direito Civil", "legal_refs": ["Art. 157 do CC", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: natureza jurídica dos contratos"], "confidence": 0.8, "extracted_at": "2026-05-25T21:36:14.146044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=169", "doc_key": "275ce8575802f15acadd5e1092b975c8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fba7d00182fdc4d090377e638474b1f6073b6242655cd2898e3d3475d1d619ae'),
  ('cpiuris2025::3f4353e7e2b9a6424e57a41ba7b0d6d5', 'doutrina', 'cp_iuris', 'Direito Civil — Capacidade das partes no contrato', '## Capacidade das partes no contrato

As partes contratantes precisam ter capacidade jurídica para celebrar um contrato, sendo incapazes menores de 16 anos, ébitos habituais, viciados em tóxicos, pessoas com deficiência ou pródigos que precisam estar assistidos por tutores ou curadores.

### Conceitos
- **Capacidade jurídica**: Habilidade para celebrar um contrato
- **Incapacidade jurídica**: Falta de capacidade para celebrar um contrato
- **Menores de 16 anos**: Não podem celebrar contratos sem assistência
- **Ebítos habituais**: São incapazes por falta de vontade
- **Viciados em tóxicos**: São incapazes por falta de vontade
- **Pessoas com deficiência**: São plenamente capazes, mas podem precisar assistência se necessário
- **Pródigos**: Precisam estar assistidos para celebrar contratos

### Referências legais
- Art. 3º e 4º do CC/02

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Distinção entre absoluta e relativa incapacidade
- Importância da assistência para pessoas com deficiência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.170 (1)", "page_number": 170, "discipline": "Direito Civil", "legal_refs": ["Art. 3º e 4º do CC/02"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:36:48.914734+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=170", "doc_key": "3f4353e7e2b9a6424e57a41ba7b0d6d5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0dee3abec326a9ceb4aafb97c16d08f203740d2ca559e432805bfbe9b6257267'),
  ('cpiuris2025::dde97e089fa9ca11ecb4427097ee3040', 'doutrina', 'cp_iuris', 'Direito Civil — Pessoas Incapazes e Direitos de Pródigos', '## Pessoas Incapazes e Direitos de Pródigos

As pessoas incapazes podem exercer atos de mera administração do seu patrimônio, mas não podem celebrar contratos que envolvam disposições patrimoniais sem a assistência de um curador.

### Conceitos
- **Pessoas Incapazes**: Pessoas que não têm capacidade jurídica para exercer direitos e obrigações
- **Mera Administração**: Atos de gestão ou administração do patrimônio sem a necessidade de assistência
- **Disposição Patrimonial**: Atos que envolvem a transferência de bens ou direitos
- **Curador**: Pessoa designada para representar e defender os interesses de uma pessoa incapaz

### Referências legais
- Art. 1.634 do Código Civil de 2002

### Dicas de prova
- Distinguir entre atos de mera administração e disposições patrimoniais
- Entender a importância da assistência de um curador em casos de pessoas incapazes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.170 (2)", "page_number": 170, "discipline": "Direito Civil", "legal_refs": ["Art. 1.634 do Código Civil de 2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:37:24.622558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=170", "doc_key": "dde97e089fa9ca11ecb4427097ee3040"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '187e574731ce13281fcee95ce601e8ba5c76c76b1347e2d336572a8d7cabf4c0'),
  ('cpiuris2025::88e6a410dd0c7111a5a95e5725a3340b', 'doutrina', 'cp_iuris', 'Direito Civil — Manifestação de Vontade nas Contratos', '## Manifestação de Vontade nas Contratos

A manifestação de vontade é fundamental para a celebração de um contrato, podendo ser verbal, escrita ou por gestos inequívocos. É necessário o consentimento das partes para que o contrato seja formado.

### Conceitos
- **Consentimento**: A manifestação de vontade unificada das partes
- **Legitimação**: O requisito de autorização especial para a celebração de um contrato
- **Vontade Verbal**: Manifestação de vontade feita verbalmente
- **Vontade Escrita**: Manifestação de vontade feita por meio de escrita
- **Gestos Inequívocos**: Manifestação de vontade feita por meio de gestos claros e inequívocos

### Referências legais
- Art. 496 CC/02
- Art. 108 CC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre consentimento e legitimidade nas contratos
- Conheça as formas de manifestação de vontade (verbal, escrita ou por gestos inequívocos)
- A importância da autorização especial para a celebração de alguns atos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Direito Civil", "legal_refs": ["Art. 496 CC/02", "Art. 108 CC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:37:56.293668+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=171", "doc_key": "88e6a410dd0c7111a5a95e5725a3340b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c1d732ca767c07c4e21538a4d4a406bea06901844821c30abaae1f73097b59b2'),
  ('cpiuris2025::7f926522b09de44857d9cb6a2f6f38e7', 'doutrina', 'cp_iuris', 'Direito Civil — Forma dos Contratos', '## Forma dos Contratos

Os contratos podem ter forma livre, verbal ou escrita, e são válidos desde que haja manifestação de vontade clara.

### Conceitos
- **Contrato**: Acordo entre duas ou mais pessoas
- **Forma dos Contratos**: Regra que determina a maneira como o contrato deve ser feito
- **Escrita Pública**: Manifestação de vontade escrita, solene ou não
- **Escrita Particular**: Manifestação de vontade escrita, não solene

### Referências legais
- Art. 108 do Código Civil

### Dicas de prova
- Diferencie entre escritura pública e particular
- Entenda a importância da forma dos contratos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.171 (2)", "page_number": 171, "discipline": "Direito Civil", "legal_refs": ["Art. 108 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:38:15.795127+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=171", "doc_key": "7f926522b09de44857d9cb6a2f6f38e7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cb074c00c6ce1c84ea257530d40e569b44f67610bd745b696226d917a2bc01bc'),
  ('cpiuris2025::a6d1f5e6110b8a51c0b35a68124d8c4a', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos: Teoria Geral dos Contratos', '## Contratos: Teoria Geral dos Contratos

O texto discute a celebração de contratos de locação e fiança, destacando que os contratos de locação podem ser celebrados verbalmente, enquanto os contratos de fiança exigem forma solene. Além disso, o silêncio não é considerado forma de manifestação de vontade em regra.

### Conceitos
- **Contrato**: Acordo entre duas ou mais pessoas que cria uma obrigação
- **Locação**: Condição sob a qual alguém tem direito a usar um imóvel por tempo determinado
- **Fiança**: Garantia oferecida por uma pessoa para garantir o cumprimento de uma obrigação
- **Silêncio**: Ação de não falar ou não manifestar vontade
- **Consentimento**: Manifestação de vontade que expressa a aceitação ou rejeição de uma proposta

### Referências legais
- Art. 819, CC

### Dicas de prova
- Distinção entre locação e fiança
- A importância do consentimento no contrato
- O papel do silêncio na manifestação de vontade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.172 (1)", "page_number": 172, "discipline": "Direito Civil", "legal_refs": ["Art. 819, CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:39:00.560500+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=172", "doc_key": "a6d1f5e6110b8a51c0b35a68124d8c4a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '171ef602693f2dfbcb85be84d1b133e640aa7fd68fd2bf7662b3eb00172351c9'),
  ('cpiuris2025::d42e7ecccf1d679c15c0f3c75c0af65f', 'doutrina', 'cp_iuris', 'Direito Civil — Motivação nos Contratos', '## Motivação nos Contratos

A motivação do contrato é irrelevante para o Direito, salvo se expressa no negócio, em que caso pode ser fundamentação para erro.

### Conceitos
- **motivação**: explicação do motivo pelo qual um contrato foi celebrado
- **irrelevância**: falta de importância ou relevância para o Direito
- **expressão no negócio**: disposição específica que indica a motivação do contrato

### Referências legais
- Art. 140, CC

### Jurisprudência
- RE 123456

### Dicas de prova
- Perguntas sobre motivação podem ser confusas com perguntas sobre motivo.
- A expressão no negócio é fundamental para evitar erros no contrato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.172 (2)", "page_number": 172, "discipline": "Direito Civil", "legal_refs": ["Art. 140, CC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:39:19.874619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=172", "doc_key": "d42e7ecccf1d679c15c0f3c75c0af65f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6dd78edda93da710b058992a153134e55b32fcee0367695b0d9f1842614f7743'),
  ('cpiuris2025::7f0cf3b95491007077814c4b905d3437', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos', '## Teoria Geral dos Contratos

O contrato é um negócio jurídico que depende da participação de pelo menos duas vontades e pode ser bilateral ou plurilateral. A vontade humana está direcionada para as consequências do ato, não necessariamente para a exteriorização através da assinatura do contrato.

### Conceitos
- **Vontade humana**: A manifestação de desejo ou intenção de uma pessoa em relação a um ato ou negócio
- **Negócio jurídico bilateral**: Um negócio que está direcionado à produção de vantagens e envolve a manifestação de vontade de duas pessoas
- **Negócio jurídico plurilateral**: Um negócio que envolve a manifestação de vontade de mais de duas pessoas
- **Vantagem**: Benefício ou resultado positivo que surge do ato ou negócio

### Referências legais
- Art. 421 CC/02
- Art. 539 CC/02

### Dicas de prova
- Entenda a diferença entre vontade humana e manifestação de vontade
- Conheça as características de negócio jurídico bilateral e plurilateral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.173 (1)", "page_number": 173, "discipline": "Direito Civil", "legal_refs": ["Art. 421 CC/02", "Art. 539 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:39:52.531301+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=173", "doc_key": "7f0cf3b95491007077814c4b905d3437"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '21bb67d4b7991231bcd9f5115b31931ea233507ac009550a739a40a0b8fd4507'),
  ('cpiuris2025::a258c6318704efdab1b74ac1b4acaef3', 'doutrina', 'cp_iuris', 'Direito Civil — Autonomia da Vontade no Direito Contratual', '## Autonomia da Vontade no Direito Contratual

A autonomia da vontade é um princípio fundamental do direito contratual, garantindo que o contrato se aperfeiçoe pela manifestação de vontade dos contratantes. No entanto, com o tempo, o princípio evoluiu e não mais é absoluto.

### Conceitos
- **Autonomia da Vontade**: Princípio que garantiza a liberdade de escolha dos contratantes
- **Manifestação de Vontade**: Ação pelo qual os contratantes expressam sua vontade para formar o contrato
- **Princípio Absoluto**: Forma anterior da autonomia da vontade, que não mais é aplicada
- **Código Civil (CC/16)**: Sistema jurídico que buscava proteger apenas o patrimônio dos sujeitos

### Referências legais
- Art. 129 do CC/16

### Dicas de prova
- Entenda a evolução do princípio autonomia da vontade ao longo do tempo
- Destaque a importância da manifestação de vontade na formação do contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.173 (2)", "page_number": 173, "discipline": "Direito Civil", "legal_refs": ["Art. 129 do CC/16"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:40:31.082057+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=173", "doc_key": "a258c6318704efdab1b74ac1b4acaef3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2f16a27718e946c1ca46b0a6a11cc0653aec4daa55f7580505e9b70d9a609d09'),
  ('cpiuris2025::5c579df8a56d3d0c71579b44350ce22c', 'doutrina', 'cp_iuris', 'Direito Civil — Função Social dos Contratos', '## Função Social dos Contratos

A função social dos contratos decorre do princípio da socialidade, limitando a autonomia da vontade com ética, boa-fé e probidade. O direito deve ser concretizado para não engessar as normas gerais.

### Conceitos
- **Princípio da Socialidade**: Limita a autonomia da vontade com ética, boa-fé e probidade
- **Princípio da Eticidade**: Requer que as partes contratuais sejam moralmente corretas
- **Princípio da Operabilidade**: O direito deve ser concretizado para não engessar as normas gerais
- **Função Social do Contrato**: Transmissão de um sentido social, retirando o egoísmo individual

### Referências legais
- Art. 422 do CC/02
- Art. 421 do CC/02

### Dicas de prova
- Entenda a relação entre autonomia da vontade e função social dos contratos
- Pense na ética, boa-fé e probidade como limites para a liberdade contratual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.174 (1)", "page_number": 174, "discipline": "Direito Civil", "legal_refs": ["Art. 422 do CC/02", "Art. 421 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:41:02.824017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=174", "doc_key": "5c579df8a56d3d0c71579b44350ce22c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '558f5c0e43152d6e0a1a66efdef1fb7fdaaf9a66b882e6b14888135f719c7328'),
  ('cpiuris2025::024743e57f2b59fd6bb3fed45de7ef4e', 'doutrina', 'cp_iuris', 'Direito Civil — Autonomia da Vontade e Função Social do Contrato', '## Autonomia da Vontade e Função Social do Contrato

A autonomia da vontade é um princípio fundamental no direito civil, permitindo que as partes contratam livremente. No entanto, com o advento do CC/02, a função social dos contratos ganhou destaque, limitando a autonomia da vontade em alguns aspectos.

### Conceitos
- **Autonomia da Vontade**: O direito das partes contratantes a escolher livremente suas condições
- **Função Social do Contrato**: A função que o contrato deve cumprir para atender às necessidades sociais
- **Cláusulas Abusivas**: Cláusulas que ultrajam a função social do contrato e são prejudiciais ao outro partido

### Referências legais
- Art. 129 CC/02

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a autonomia da vontade e sua relação com a função social do contrato
- Conheça as cláusulas abusivas e suas implicações no direito civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.174 (2)", "page_number": 174, "discipline": "Direito Civil", "legal_refs": ["Art. 129 CC/02"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:41:29.284158+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=174", "doc_key": "024743e57f2b59fd6bb3fed45de7ef4e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '28e8984dfc43df204384ddbf3c250149cfd3d6676089b0e24b0c42c14b16016f'),
  ('cpiuris2025::1d1a5ffe3a524020197f0ff9bb4010ab', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos', '## Teoria Geral dos Contratos

A teoria geral dos contratos busca entender a natureza e os princípios que regem as relações entre as partes, destacando-se a dicotomia entre direito público e privado. O contrato deve ser concluído em benefício dos contratantes sem conflito com o interesse público.

### Conceitos
- **Autonomia da vontade**: liberdade contratual
- **Relatividade dos contratos**: contratos podem ser relativos ou absolutos
- **Obrigatoriedade dos contratos**: contratos são obrigatórios para as partes
- **Função social do contrato**: contrato deve ser feito em benefício dos contratantes sem conflito com o interesse público
- **Boa-fé objetiva**: obrigação de agir com honestidade e justiça
- **Cláusulas gerais**: cláusulas que regem as relações contratuais
- **Interpretação de cláusulas gerais**: interpretação das cláusulas gerais para garantir a justiça e a equidade

### Referências legais
- Art. 118 do CC/2019
- Súmula 245 STF

### Jurisprudência
- RE 123456
- Tema repetitivo da autonomia da vontade

### Dicas de prova
- Entenda a dicotomia entre direito público e privado
- Conheça os princípios clássicos dos contratos (autonomia da vontade, relatividade, etc.)
- Aprenda sobre a função social do contrato e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.175 (1)", "page_number": 175, "discipline": "Direito Civil", "legal_refs": ["Art. 118 do CC/2019", "Súmula 245 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da autonomia da vontade"], "confidence": 0.8, "extracted_at": "2026-05-25T21:42:20.544608+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=175", "doc_key": "1d1a5ffe3a524020197f0ff9bb4010ab"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '74d8c4cab5238e80012c22f52c6ada09ebc2b48c2b91a5bbea27ebd6dc6ffb09'),
  ('cpiuris2025::fc05337618594ff60ebbab15fef0a037', 'doutrina', 'cp_iuris', 'Direito Civil — Liberdade Contratual e Princípio da Intervenção Mínima', '## Liberdade Contratual e Princípio da Intervenção Mínima

A liberdade contratual é exercida dentro dos limites da função social do contrato, prevalecendo o princípio da intervenção mínima nas relações contratuais privadas. Além disso, os contratos civis e empresariais presumem-se paritários e simétricos até a presença de elementos concretos que justifiquem o afastamento dessa presunção.

### Conceitos
- **Liberdade Contratual**: Direito das partes a negocia-los livremente, dentro dos limites da função social do contrato
- **Princípio da Intervenção Mínima**: Regra que limita a intervenção estatal nos contratos privados
- **Paritário e Simétrico**: Presunção de igualdade das partes em um contrato, até a presença de elementos concretos que justifiquem o afastamento dessa presunção

### Referências legais
- Art. 421 da Código Civil
- Lei nº 13.874/2019

### Dicas de prova
- Entenda a função social do contrato e como ela afeta a liberdade contratual
- Conheça o princípio da intervenção mínima e sua aplicação nas relações contratuais privadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.175 (2)", "page_number": 175, "discipline": "Direito Civil", "legal_refs": ["Art. 421 da Código Civil", "Lei nº 13.874/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:42:51.301802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=175", "doc_key": "fc05337618594ff60ebbab15fef0a037"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3b20d0543f354caa088745fe4d4e04131274d805d92f4636b6a731e65c3e8a18'),
  ('cpiuris2025::d88a34a804f0368045a20b8c15d1e2b0', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos', '## Teoria Geral dos Contratos

A alocação de riscos definida pelas partes deve ser respeitada e observada, além de uma revisão contratual excepcional e limitada. O equilíbrio entre as partes é fundamental para preservar a autonomia da vontade privada.

### Conceitos
- **Alocação de riscos**: Definição das responsabilidades e riscos associados a um contrato
- **Revisão contratual**: Mudança ou alteração de termos de um contrato, excepcional e limitada
- **Equilíbrio econômico**: Condição em que as partes têm liberdade para negociar e concordar em termos justos
- **Autonomia da vontade privada**: Direito das partes de estabelecer seus próprios termos e condições no contrato

### Referências legais
- Art. 3°, VIII, da Lei nº 13.874/19

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância do equilíbrio econômico e da autonomia da vontade privada
- Conheça as regras de revisão contratual excepcional e limitada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.176 (1)", "page_number": 176, "discipline": "Direito Civil", "legal_refs": ["Art. 3°, VIII, da Lei nº 13.874/19"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T21:43:26.484977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=176", "doc_key": "d88a34a804f0368045a20b8c15d1e2b0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4f20969a9fd0297d200a0241935a4030b93fcdc813d63a9b688df97a9b46ce7a'),
  ('cpiuris2025::b5d68028b4e2eaa9a3dd31913f0c4588', 'doutrina', 'cp_iuris', 'Direito Civil — Função Social do Contrato', '## Função Social do Contrato

Quem está em pé de igualdade no momento de deliberação sobre os termos do contrato, considerando-se a atividade econômica por eles desempenhada, deve prevalecer a determinação do art. 421 do Código Civil, pois não existe legislação específica para conferir tutela diferenciada.

### Conceitos
- **Função Social do Contrato**: Princípio que rege as relações contratuais, visando a promover a ordem social e a justiça.
- **Art. 421 do Código Civil**: Determina a função social do contrato como cláusula geral que impõe a revisão do princípio da relatividade dos efeitos do contrato em relação a terceiros.
- **Princípio de Conservação do Contrato**: Reforça o princípio de conservação do contrato, assegurando trocas úteis e justas.
- **Relatividade dos Efeitos do Contrato**: Princípio que estabelece que os efeitos do contrato se limitam aos partes contratantes.
- **Tutela Externa do Crédito**: Revisão do princípio da relatividade dos efeitos do contrato em relação a terceiros, visando proteger o crédito.
- **Trocas Úteis e Justas**: Objetivo da função social do contrato, que busca promover trocas justas e úteis.

### Referências legais
- Art. 421 do Código Civil

### Jurisprudência
- REsp n. 1.799.039/SP
- Enunciado 21 do Conselho da Justiça Federal
- Enunciado 22 do Conselho da Justiça Federal

### Dicas de prova
- Entenda a função social do contrato e sua relação com o art. 421 do Código Civil.
- Conheça os princípios de conservação do contrato e relatividade dos efeitos do contrato.
- Aprenda a aplicar a tutela externa do crédito em casos específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.176 (2)", "page_number": 176, "discipline": "Direito Civil", "legal_refs": ["Art. 421 do Código Civil"], "jurisprudence": ["REsp n. 1.799.039/SP", "Enunciado 21 do Conselho da Justiça Federal", "Enunciado 22 do Conselho da Justiça Federal"], "confidence": 0.8, "extracted_at": "2026-05-25T21:44:25.606277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=176", "doc_key": "b5d68028b4e2eaa9a3dd31913f0c4588"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '95251c1ea14fab34427c1fa39f84d364938d8fb2ec7a60b2ba3e1bb3a10585cd'),
  ('cpiuris2025::f84ab31666ecca61bfa0f35eb5c0ff33', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos', '## Teoria Geral dos Contratos

A teoria geral dos contratos se baseia na boa-fé objetiva e tem como objetivo atender à função social do contrato, que não elimina a autonomia contratual, mas a atenua ou reduz seu alcance quando há interesses metaindividuais ou de dignidade humana.

### Conceitos
- **Boa-fé objetiva**: Princípio que fundamenta a teoria geral dos contratos
- **Função social do contrato**: Objetivo do contrato que não elimina a autonomia contratual, mas a atenua ou reduz seu alcance
- **Autonomia contratual**: Direito das partes de dispor livremente de suas vontades em um contrato
- **Interesses metaindividuais**: Interesses que não se referem apenas às partes individuais, mas também à coletividade
- **Dignidade humana**: Direito fundamental que protege a dignidade e o bem-estar das pessoas

### Referências legais
- Art. 421 do Código Civil
- Súmula 302 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a boa-fé objetiva e a função social do contrato
- Conheça os princípios gerais contratuais que balizam o adimplemento substancial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.177 (1)", "page_number": 177, "discipline": "Direito Civil", "legal_refs": ["Art. 421 do Código Civil", "Súmula 302 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:45:02.401068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=177", "doc_key": "f84ab31666ecca61bfa0f35eb5c0ff33"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '33296d5516b1b08b9dcbd9f72ca8df629be56ca1137d7f303badf1f900ece2f5'),
  ('cpiuris2025::f28d60827ed733312bc73a297ba85002', 'doutrina', 'cp_iuris', 'Direito Civil — Limitação do tempo de internação hospitalar e princípio da supremacia da ordem pública', '## Limitação do tempo de internação hospitalar e princípio da supremacia da ordem pública

Cláusula contratual que limita o tempo de internação hospitalar, desequilíbrio econômico e exploração dos mais fracos, além do princípio da supremacia da ordem pública.

### Conceitos
- **Limitação do tempo de internação hospitalar**: Cláusula contratual que estabelece um prazo máximo para o segurado
- **Desequilíbrio econômico**: Desigualdade econômica gerada pela liberdade de contratar
- **Exploração dos mais fracos**: Uso abusivo da liberdade de contratar para prejudicar os mais vulneráveis
- **Princípio da supremacia da ordem pública**: Princípio que prioriza a ordem pública sobre a liberdade individual
- **Dirigismo contratual**: Ação do Estado para regular contratos privados
- **Coletividade**: Atuação maior do Estado no direito público
- **Direito privado**: Direito que regula relações entre indivíduos

### Referências legais
- Art. 48 da CLT
- Súmula 594/STJ

### Jurisprudência
- RE 123456
- Informativo 594/STJ

### Dicas de prova
- Entenda a cláusula contratual de plano de saúde e seu impacto na liberdade de contratar
- Avalie o princípio da supremacia da ordem pública em relação à liberdade individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.177 (2)", "page_number": 177, "discipline": "Direito Civil", "legal_refs": ["Art. 48 da CLT", "Súmula 594/STJ"], "jurisprudence": ["RE 123456", "Informativo 594/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T21:45:37.426273+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=177", "doc_key": "f28d60827ed733312bc73a297ba85002"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '555c5f8310efa58dab830d0047c0c21d8c3064bdaf6e7be7ec123204d96245b9'),
  ('cpiuris2025::5983335149d0fed3d2c59cd7d838d0cc', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos', '## Teoria Geral dos Contratos

O art. 2.035, parágrafo único do CC/02 prevê que nenhuma convenção prevalecerá se contrariar preceitos de ordem pública, garantindo a função social da propriedade e dos contratos.

### Conceitos
- **Diregismo contratual**: Princípio da supremacia da ordem pública no âmbito dos contratos
- **Publicização do direito privado**: Irrível conceito, pois o dirigismo contratual não é a mesma coisa que publicização do direito civil
- **Princípio do consensualismo**: Contratos se formam pela manifestação da vontade e a forma é livre, exceto quando a lei exigir forma ou solenidade específica
- **Função social da propriedade**: A propriedade deve ser utilizada de acordo com o bem-estar social

### Referências legais
- Art. 2.035, parágrafo único do CC/02

### Jurisprudência
- Súmula 620 do STJ

### Dicas de prova
- Entenda a diferença entre dirigismo contratual e publicização do direito privado
- Conheça o princípio do consensualismo e sua relação com a função social da propriedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.178 (1)", "page_number": 178, "discipline": "Direito Civil", "legal_refs": ["Art. 2.035, parágrafo único do CC/02"], "jurisprudence": ["Súmula 620 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T21:46:21.434023+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=178", "doc_key": "5983335149d0fed3d2c59cd7d838d0cc"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1ebc74c0ce5eddb011ba3aa80b597032b44cd78511e84b0cba498b5ec0785a50'),
  ('cpiuris2025::9e86ba99ec09af40ca3f1889f4264073', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos e Nulidade', '## Contratos e Nulidade

O contrato é nulo se não for realizado de acordo com as regras estabelecidas pela lei, como a venda de imóveis em valor superior a 30 salários-mínimos que requer escritura pública.

### Conceitos
- **Contrato nulo**: Contrato que não tem validade jurídica
- **Art. 166 CC/02**: Rege a venda de imóveis em valor superior a 30 salários-mínimos
- **Escritura pública**: Requerida para venda de imóveis em valor superior a 30 salários-mínimos
- **Tradição**: Entrega do bem, necessário para transmissão de direitos reais móveis

### Referências legais
- Art. 166 CC/02

### Jurisprudência
- 87 STJ. 3ª Turma. REsp 1.485.717-SP
- Tema repetitivo: Nulidade de contratos

### Dicas de prova
- Distinguir entre contrato válido e nulo
- Entender a importância da escritura pública em vendas de imóveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.178 (2)", "page_number": 178, "discipline": "Direito Civil", "legal_refs": ["Art. 166 CC/02"], "jurisprudence": ["87 STJ. 3ª Turma. REsp 1.485.717-SP", "Tema repetitivo: Nulidade de contratos"], "confidence": 0.8, "extracted_at": "2026-05-25T21:46:47.790049+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=178", "doc_key": "9e86ba99ec09af40ca3f1889f4264073"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '91c37ecf588e9a019d2b368b786cdee0240f29286a536c27cf2bf1356f8f53fb'),
  ('cpiuris2025::55709bc0aa0f4b1632164536a26eb000', 'doutrina', 'cp_iuris', 'Direito Civil — Princípio da Relatividade dos Contratos e Princípio da Obrigatoriedade dos Contratos', '## Princípio da Relatividade dos Contratos e Princípio da Obrigatoriedade dos Contratos

O contrato só produz efeitos em relação às pessoas que dele participam, mas pode atingir terceiros com estipulação em favor deles. A obrigatoriedade dos contratos é intangível e força vinculante, com a limitação clássica e moderna.

### Conceitos
- **Princípio da Relatividade dos Contratos**: O contrato só produz efeitos em relação às pessoas que dele participam
- **Princípio da Obrigatoriedade dos Contratos**: A obrigatoriedade dos contratos é intangível e força vinculante
- **Pacta Sunt Servanda**: O contrato faz lei entre as partes
- **Limitação Clássica**: Existente desde o CC/16
- **Limitação Moderna**: Criada através do CC/02

### Referências legais
- Art. 157 da Lei nº 9.506/98
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Princípio da Relatividade dos Contratos

### Dicas de prova
- Entenda a diferença entre contrato consensual e real
- Conheça as limitações clássica e moderna da obrigatoriedade dos contratos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.179 (1)", "page_number": 179, "discipline": "Direito Civil", "legal_refs": ["Art. 157 da Lei nº 9.506/98", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Princípio da Relatividade dos Contratos"], "confidence": 0.8, "extracted_at": "2026-05-25T21:47:22.935118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=179", "doc_key": "55709bc0aa0f4b1632164536a26eb000"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3bc1e19d470ae5ffbdf5fcc12e38313933525a8526b2f3b910ee184136be571b'),
  ('cpiuris2025::9639a06feec3ab9c7ac4acf3df2840a5', 'doutrina', 'cp_iuris', 'Direito Civil — Imputabilidade e Princípio da Revisão dos Contratos', '## Imputabilidade e Princípio da Revisão dos Contratos

A imputabilidade de um inadimplemento depende da culpa ou inadimplência do devedor. O inimputável é o inadimplemento que não pode ser atribuído ao devedor, como a força maior. A revisão dos contratos ocorre quando uma prestação se torna excessivamente onerosa para uma das partes.

### Conceitos
- **Imputabilidade**: A responsabilidade do devedor pelo inadimplemento
- **Inimputável**: O inadimplemento que não pode ser atribuído ao devedor
- **Princípio da Revisão dos Contratos**: A revisão dos contratos ocorre quando uma prestação se torna excessivamente onerosa para uma das partes
- **Teoria da Imprevisão**: Mitigação moderna à obrigatoriedade dos contratos
- **Obrigatoriedade dos Contratos**: A obrigação de cumprir com as cláusulas do contrato

### Referências legais
- Art. 393, parágrafo único, CC/02; Art. 478, CC/02

### Dicas de prova
- Entenda a diferença entre imputabilidade e inimputabilidade
- Conheça o princípio da revisão dos contratos e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.179 (2)", "page_number": 179, "discipline": "Direito Civil", "legal_refs": ["Art. 393, parágrafo único, CC/02; Art. 478, CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:48:05.075167+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=179", "doc_key": "9639a06feec3ab9c7ac4acf3df2840a5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7d054a66155985b136577d4811c048474e951d7f141318bcdfd9761c92a9855d'),
  ('cpiuris2025::ea7672d0bb7f9e0bf2ac6615ba98f863', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos e Teoria da Imprevisão', '## Teoria Geral dos Contratos e Teoria da Imprevisão

A teoria da imprevisão permite ao juiz corrigir as prestações de um contrato quando há desequilíbrio entre elas, especialmente em contratos de execução continuada ou diferida. A teoria é aplicável quando há imprevisibilidade, excepcionalidade do fato e desequilíbrio entre as prestações.

### Conceitos
- **Teoria da Imprevisão**: Permite ao juiz corrigir as prestações de um contrato em casos de desequilíbrio
- **Imprevisibilidade**: É objetiva e não há como ser prevista
- **Excepcionalidade do fato**: É necessário que o fato seja excepcional e não previsto
- **Desequilíbrio entre as prestações**: Um dos contratantes detém vantagem e o outro não
- **Princípio da conservação do negócio jurídico**: O contrato deve ser mantido intacto, mas com equilíbrio

### Referências legais
- Art. 317
- Art. 479 CC/02

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre análise subjetiva e objetiva
- Identifique os pressupostos de incidência da teoria da imprevisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.180 (1)", "page_number": 180, "discipline": "Direito Civil", "legal_refs": ["Art. 317", "Art. 479 CC/02"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T21:48:41.690641+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=180", "doc_key": "ea7672d0bb7f9e0bf2ac6615ba98f863"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a6b73ca2d355ddce433ce9931ce2250ac167c727b32c4b5fb6116cd7b01379b4'),
  ('cpiuris2025::e4940b8d7c70989c273ad67acf4403c7', 'doutrina', 'cp_iuris', 'Direito Civil — Inaplicabilidade da teoria da imprevisão nos contratos aleatórios', '## Inaplicabilidade da teoria da imprevisão nos contratos aleatórios

A teoria da imprevisão não é aplicável a contratos que envolvem elementos aleatórios, como a compra e venda de soja com entrega futura.

### Conceitos
- **Teoria da imprevisão**: teoria jurídica que visa justificar a rescisão de contrato por motivos imprevistos
- **Contratos aleatórios**: contratos que envolvem elementos indeterminados ou imprevisíveis

### Referências legais
- Art. 273 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Ponderar a natureza dos contratos e a aplicabilidade da teoria da imprevisão
- Diferenciar entre reexame de fatos e valoração das provas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.180 (2)", "page_number": 180, "discipline": "Direito Civil", "legal_refs": ["Art. 273 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:49:02.967979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=180", "doc_key": "e4940b8d7c70989c273ad67acf4403c7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'be492292cd2097c721b85028ddcc047fbf90552b124332925ddaa11bd70c1e42'),
  ('cpiuris2025::d789809d7d1d8d5703039e7dbe2a8ded', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos e Princípio da Boa-fé', '## Teoria Geral dos Contratos e Princípio da Boa-fé

O risco é inerente ao negócio nos contratos agrícolas de venda para entrega futura. O princípio da boa-fé exige que as partes se comportem de forma correta durante a formação e execução do contrato.

### Conceitos
- **Risco inerente**: A responsabilidade pela perda ou dano que pode ocorrer no negócio
- **Princípio da boa-fé**: O dever de agir com honestidade e sinceridade em todas as relações contratuais
- **Boa-fé objetiva**: Um padrão comportamental ético, pautada na confiança adjetivada – eticização da conduta social
- **Teoria do abuso de direito**: O ato de uma parte explorar ou aproveitar indevidamente a situação contratuais para seu próprio benefício

### Referências legais
- Art. 422 do CC/02

### Jurisprudência
- REsp 1210389/MS
- Súmula N da STF

### Dicas de prova
- Entenda o conceito de risco inerente e sua aplicação nos contratos agrícolas
- Aprenda a distinguir entre boa-fé subjetiva e objetiva
- Conheça a teoria do abuso de direito e como ela se aplica às relações contratuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.181", "page_number": 181, "discipline": "Direito Civil", "legal_refs": ["Art. 422 do CC/02"], "jurisprudence": ["REsp 1210389/MS", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-25T21:49:53.374575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=181", "doc_key": "d789809d7d1d8d5703039e7dbe2a8ded"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '880f3fd5f79c2b92d68181fffcb5e92ad66fe358ce66abc64effcba883d7a7bc'),
  ('cpiuris2025::ce2bed8a2ba17e9394f14fd6982c8966', 'doutrina', 'cp_iuris', 'Direito Civil — Abuso de Direito e Atos Ilícitos', '## Abuso de Direito e Atos Ilícitos

A legislação estabelece que o titular de um direito pode cometer ato ilícito se exceder os limites impostos pelo seu fim econômico ou social, pela boa-fé ou pelos bons costumes. A violação da boa-fé objetiva leva à quebra da confiança, resultando no cometimento do ato ilícito.

### Conceitos
- **Abuso de Direito**: Excesso de direito que pode levar ao cometimento de atos ilícitos
- **Atos Ilícitos**: Ações ou omissões que vão contra a lei ou os direitos dos outros
- **Boa-Fé Objetiva**: Confiança justificada na conduta de um outro, com base em informações verdadeiras e completas
- **Quebra da Confiança**: Falta de confiança entre as partes de um contrato, devido à violação da boa-fé objetiva
- **Responsabilidade Civil**: Obrigação de reparar os danos causados a outra pessoa ou coisa

### Referências legais
- Art. 187 do Código Civil

### Jurisprudência
- Súmula 370 do STJ
- RE 123456

### Dicas de prova
- Entenda a distinção entre abuso de direito e atos ilícitos
- Conheça os requisitos para caracterizar venire contra factum proprium
- Aprenda a aplicar a teoria da boa-fé objetiva em contratos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.182 (1)", "page_number": 182, "discipline": "Direito Civil", "legal_refs": ["Art. 187 do Código Civil"], "jurisprudence": ["Súmula 370 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:50:32.878404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=182", "doc_key": "ce2bed8a2ba17e9394f14fd6982c8966"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4c170ba0014f0791e53c926b9920435c53b622dadd5d74b7c88a15a187a975f6'),
  ('cpiuris2025::d0389fe2c9c97e1283b73ababfdd0438', 'doutrina', 'cp_iuris', 'Direito Civil — Supressio e Surrectio', '## Supressio e Surrectio

A supressio é a perda de um direito pelo seu não exercício no tempo, caracterizada pela omissão no exercício de um direito, transcurso de um período de tempo, objetiva deslealdade e intolerabilidade do posterior exercício.

### Conceitos
- **Supressio**: perda de um direito pelo seu não exercício no tempo
- **Protelamento desleal**: desleal atraso no exercício de um direito
- **Omissão**: não exercer um direito
- **Transcurso de tempo**: passar um período de tempo sem agir
- **Deslealdade objetiva**: agir com má-fé ou desinteresse
- **Intolerabilidade**: não ser possível exercer o direito posteriormente

### Referências legais
- Art. 186 da CC/2002

### Dicas de prova
- Entenda a diferença entre supressio e protelamento desleal
