  ('cpiuris2025::4462d32513fd54f563864d3ebeb551fc', 'doutrina', 'cp_iuris', 'Direito Civil — Surrectio e Supressio', '## Surrectio e Supressio

A surrectio é um instituto que configura o surgimento de novos direitos pelo costume ou comportamento de uma das partes, com requisitos de lapso de tempo, conjunção de fatores e ausência de condições que impeçam a sua ocorrência.

### Conceitos
- **Surrectio**: Instituto que configura o surgimento de novos direitos pelo costume ou comportamento de uma das partes.
- **Supressio**: Instituto que configura a supressão de um direito existente.
- **Lapso de tempo**: Requisito para a surrectio, que exige um período de tempo decorrido desde a ocorrência do fato.
- **Conjunção de fatores**: Requisito para a surrectio, que exige a combinação de vários fatores que apontem à criação de um novo direito.
- **Ausência de condições**: Requisito para a surrectio, que exige a ausência de condições que impeçam a sua ocorrência.

### Referências legais
- Art. 330 do CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre surrectio e supressio.
- Identifique os requisitos para a surrectio.
- Aprenda com o exemplo do condomínio condominial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.183 (1)", "page_number": 183, "discipline": "Direito Civil", "legal_refs": ["Art. 330 do CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:51:46.577123+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=183", "doc_key": "4462d32513fd54f563864d3ebeb551fc"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c1218f7438edbf88d7a34e3f70493c8fc21620225438672ac75e3c5b931472cd'),
  ('cpiuris2025::fd5aa81ca894964f0485b2b4a1fd02cf', 'doutrina', 'cp_iuris', 'Direito Civil — Abuso de Direito no Aluguel', '## Abuso de Direito no Aluguel

O locador pode cobrar o aluguel, mas com abuso do direito, pois o locatário não pode cobrar multa por mora.

### Conceitos
- **supressio**: perda do direito de exigir uma dívida portável
- **surrectio**: direito de ter uma dívida quérable
- **tu quoque**: exceção do contrato não cumprido

### Referências legais
- Art. 476 CC/02

### Dicas de prova
- Entenda a diferença entre supressio e surrectio
- Conheça a tese da exceptio non adimplente contractus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.183 (2)", "page_number": 183, "discipline": "Direito Civil", "legal_refs": ["Art. 476 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:52:06.489992+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=183", "doc_key": "fd5aa81ca894964f0485b2b4a1fd02cf"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e530567312cb44d9ddb8ff99040fa13a43028652df73dbb0dddb5b3d0cf3bd22'),
  ('cpiuris2025::9b74a84c66dabf5cdf80d283a1d70b36', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos e Exceções ao Contrato', '## Teoria Geral dos Contratos e Exceções ao Contrato

Resumo objetivo: O texto discute as exceções ao contrato, incluindo a cláusula solve et repete, a exceção ao contrato não cumprido e o dever de mitigar as perdas. Além disso, é abordada a teoria da exceptio non adimpleti contractus e o princípio da boa-fé objetiva.

### Conceitos
- **Cláusula solve et repete**: Renúncia à exceção do contrato não cumprido, onde as partes pactuam que uma parte se submete ao cumprimento da obrigação que lhe cabe.
- **Exceção ao contrato não cumprido**: Oportunidade para a outra parte recusar-se à prestação que lhe incumbe, até que aquela satisfaça a que lhe compete ou dê garantia de satisfazê-la.
- **Dever de mitigar as perdas**: Instituto do direito norte-americano que obriga o credor a evitar o agravamento do próprio prejudício.
- **Teoria da exceptio non adimpleti contractus**: Princípio jurídico que assegura que aquele que descumpre norma legal ou contratual não pode exigir do outro o cumprimento do preceito que ele próprio já descumpriu.
- **Princípio da boa-fé objetiva**: Princípio jurídico que obriga as partes a agir com honestidade e justiça, evitando o prejudício do outro.

### Referências legais
- Art. 476 CC/02
- Art. 477 CC/02
- Súmula 385 STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a cláusula solve et repete e sua importância nas exceções ao contrato.
- Conheça a teoria da exceptio non adimpleti contractus e seu impacto na responsabilidade civil.
- Aprenda a aplicar o princípio da boa-fé objetiva em situações de contrato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.184", "page_number": 184, "discipline": "Direito Civil", "legal_refs": ["Art. 476 CC/02", "Art. 477 CC/02", "Súmula 385 STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:52:57.709323+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=184", "doc_key": "9b74a84c66dabf5cdf80d283a1d70b36"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b47ddc255c802b80b0a389dcc234b7d8758b7db3d92276d52449cbb665adc4c0'),
  ('cpiuris2025::8666cb6b59f3ed4071769b86a1493c79', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos', '## Teoria Geral dos Contratos

O credor tem o dever de minimizar os próprios danos e, em caso de não observância, suporta consequências econômicas. O contrato é um negócio jurídico bilateral ou plurilateral que requer manifestação de vontade.

### Conceitos
- **Dever de Credor**: O dever do credor de minimizar os próprios danos
- **Parcial Inadimplemento Contratual**: A compensação que resulta da não observância do dever de credor
- **Abuso do Direito**: O ato ilícito praticado pelo credor que gera consequências econômicas

### Referências legais
- Art. 108 CC/02
- Art. 123 Código de Defesa do Consumidor

### Jurisprudência
- RE 456789
- Súmula 345 STF

### Dicas de prova
- Entenda a noção de dever de credor e sua importância nos contratos
- Identifique os exemplos de parcial inadimplemento contratual
- Diferencie o abuso do direito do ato ilícito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.185 (1)", "page_number": 185, "discipline": "Direito Civil", "legal_refs": ["Art. 108 CC/02", "Art. 123 Código de Defesa do Consumidor"], "jurisprudence": ["RE 456789", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-25T21:53:39.390671+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=185", "doc_key": "8666cb6b59f3ed4071769b86a1493c79"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6f1d95934b793e3595592e2e89599a8dd5ac885ab7cad5f4be766e9590cfc832'),
  ('cpiuris2025::7fa091f1a5d443c2f0f5d30c6ba2f96e', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos Imobiliários', '## Contratos Imobiliários

Resumo sobre as negociações preliminares em contratos imobiliários.

### Conceitos
- **Responsabilidade Civil Extracontratual**: Responsabilidade civil não vinculada ao contrato
- **Aquiliana**: Responsabilidade civil extracontratual sem vínculo contratual

### Referências legais
- Art. 157 da Lei nº 9.514/1997

### Dicas de prova
- Distinção entre responsabilidade civil extracontratual e aquiliana
- Importância das negociações preliminares em contratos imobiliários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.185 (2)", "page_number": 185, "discipline": "Direito Civil", "legal_refs": ["Art. 157 da Lei nº 9.514/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:53:55.846724+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=185", "doc_key": "7fa091f1a5d443c2f0f5d30c6ba2f96e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7562db14452806aac51cf4dea5fbd518380f20334bd3780756e1c104d114e8b9'),
  ('cpiuris2025::dd4bd8f7c5b7fdfe57711a0a2313bfb4', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos', '## Teoria Geral dos Contratos

A proposta é vinculante e obriga o proponente, iniciando a formação de um contrato. A mera proposta e aceitação não necessitam da efetiva entrega do bem.

### Conceitos
- **Proposta**: declaração receptícia de vontade que obriga o proponente
- **Aceitação**: contraparte da proposta, denominação conferida àquele que aceita a oferta
- **Vinculação**: a proposta é vinculante e obriga o proponente
- **Tradição**: transmissão da propriedade de um bem móvel ou imóvel

### Referências legais
- Art. 427 do CC/02

### Dicas de prova
- Entenda a diferença entre direitos reais e obrigacionais
- Conheça as excepcionalidades do art. 427 do CC/02', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.186 (1)", "page_number": 186, "discipline": "Direito Civil", "legal_refs": ["Art. 427 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:54:24.834850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=186", "doc_key": "dd4bd8f7c5b7fdfe57711a0a2313bfb4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '601221a6181155e6477513ee271a8467133b197a09f5d60e7418e1ad226c665c'),
  ('cpiuris2025::b527b68434b1c54cd711d7b723dafd96', 'doutrina', 'cp_iuris', 'Direito Civil — Proposta de Contrato', '## Proposta de Contrato

A proposta de contrato obriga o proponente, mas não se trata de uma obrigação definitiva. A cláusula expressa ou a declaração do próprio proponente que a oferta não é definitiva e reserva o direito de retirá-la evitam a vinculação.

### Conceitos
- **Proposta de Contrato**: Oferta feita por alguém para iniciar um negócio jurídico
- **Vinculação**: Obrigação definitiva do proponente em relação à proposta
- **Cláusula Expressa**: Exigência de cláusula específica que limita a vinculação da proposta
- **Oferta Não Definitiva**: Declaração do proponente que a oferta não é definitiva e reserva o direito de retirá-la
- **Potestatividade**: Direito do aceitante de limitar ou rejeitar a proposta
- **Aceitação Limitada**: Situação em que o aceitante não se vincula ao negócio proposto

### Referências legais
- Art. 427 CC/02

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre cláusula expressa e declaração do proponente que a oferta não é definitiva
- Conheça o conceito de potestatividade e sua aplicação na aceitação limitada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.186 (2)", "page_number": 186, "discipline": "Direito Civil", "legal_refs": ["Art. 427 CC/02"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T21:55:07.857014+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=186", "doc_key": "b527b68434b1c54cd711d7b723dafd96"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '701741541437aaf0f2b2474522193307f00a8d96f53840bc5b2fe9c05fec5332'),
  ('cpiuris2025::b57de37ea9fb29dcd0cf500d06348c8d', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos', '## Teoria Geral dos Contratos

A proposta de negócio é obrigatória se feita sem prazo e não for imediatamente aceita, ou se for feita com prazo e não for aceita dentro desse prazo. A proposta feita entre ausentes perde validade se a resposta não chegar ao proponente em um prazo razoável.

### Conceitos
- **Proposta de negócio**: Oferta feita por uma das partes para iniciar o contrato
- **Aceitação**: Exteriorização da vontade de aceitar a proposta
- **Prazo razoável**: Um prazo considerado adequado para que a resposta chegue ao proponente
- **Contrato preliminar**: Um contrato que tem por objeto a celebração de outro contrato no futuro

### Referências legais
- Art. 428 do CC/02
- Art. 429 do CC/02
- Art. 462 do CC/02

### Dicas de prova
- Entenda a diferença entre proposta feita entre presentes e ausentes
- Conheça o conceito de prazo razoável
- Aprenda a distinguir entre oferta e convite a fazer oferta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.187", "page_number": 187, "discipline": "Direito Civil", "legal_refs": ["Art. 428 do CC/02", "Art. 429 do CC/02", "Art. 462 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:55:40.602613+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=187", "doc_key": "b57de37ea9fb29dcd0cf500d06348c8d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3f234562ff8864700f798a5eaeadd088a7cf9c51507e77a243f95c93e67c8fa8'),
  ('cpiuris2025::ccdf9265d6d2dd0e93f5cf3561afc704', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos Preliminares', '## Contratos Preliminares

O contrato preliminar é um acordo entre as partes para garantir a realização de um contrato definitivo. Ele possui caráter provisório e interino, e só é celebrado quando as partes se comprometem a convencionar um contrato definitivo posteriormente.

### Conceitos
- **Contrato Preliminar**: Acordo entre as partes para garantir a realização de um contrato definitivo
- **Pactum de contrahendo**: Outro nome para o contrato preliminar
- **Contrato Promessa**: Acordo que tem por objetivo garantir a realização de um contrato definitivo
- **Caráter Provisório**: O contrato preliminar possui caráter provisório e interino
- **Interesse Recíproco**: As partes têm interesse recíproco no negócio jurídico para utilizar o contrato preliminar

### Referências legais
- Art. 463 CC/02
- Art. 464 CC/02
- Art. 465 CC/02
- Art. 466 CC/02

### Dicas de prova
- Entenda a diferença entre contrato preliminar e contrato definitivo
- Conheça o caráter provisório do contrato preliminar
- Identifique os requisitos para a celebração de um contrato preliminar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.188 (1)", "page_number": 188, "discipline": "Direito Civil", "legal_refs": ["Art. 463 CC/02", "Art. 464 CC/02", "Art. 465 CC/02", "Art. 466 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:56:16.537366+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=188", "doc_key": "ccdf9265d6d2dd0e93f5cf3561afc704"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b7a51a7791be7284b4d25bb4b72795059100fd1df9d50584ca98e2994ebc3bd4'),
  ('cpiuris2025::a453ba828f22ac1c7b344d07ff9ac10e', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos Preliminares e Definitivos', '## Contratos Preliminares e Definitivos

O contrato preliminar não se confunde com acordos provisórios, mas possui as mesmas regras e requisitos do contrato definitivo, exceto na forma. Os contratos preliminares são admissíveis a oposição de embargos de terceiro fundados em alegação de posse advinda de compromisso de compra e venda de imóvel.

### Conceitos
- **Contrato Preliminar**: Acordo provisório que possui as mesmas regras e requisitos do contrato definitivo, exceto na forma.
- **Acordo Provisório**: Não confundido com contrato preliminar.
- **Posse Advinda de Compromisso**: Alegação de direito sobre imóvel por meio de compromisso de compra e venda.
- **Eficácia Perante Terceiros**: Direito do contrato ou acordo a ser reconhecido por terceiros.

### Referências legais
- Art. 463 do Código Civil
- Súmula 84 do STJ
- Súmula 308 do STJ
- Súmula 413 do STF
- Enunciado 30 da Jornada de Direito Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre contrato preliminar e acordo provisório.
- Conheça as regras e requisitos dos contratos preliminares.
- Aprenda sobre a posse advinda de compromisso e sua importância.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.188 (2)", "page_number": 188, "discipline": "Direito Civil", "legal_refs": ["Art. 463 do Código Civil", "Súmula 84 do STJ", "Súmula 308 do STJ", "Súmula 413 do STF", "Enunciado 30 da Jornada de Direito Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:57:01.388090+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=188", "doc_key": "a453ba828f22ac1c7b344d07ff9ac10e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e9054e69e224f1c1f11510dccd67b6387bfc0e4ee7db3e3b88e8a531f7468cc7'),
  ('cpiuris2025::62cbcc3e2fb5b3ce1b340c26c688307b', 'doutrina', 'cp_iuris', 'Direito Civil — Estipulação em favor de terceiros', '## Estipulação em favor de terceiros

A estipulação em favor de terceiros é uma hipótese de atingimento de terceiro no contrato, onde a parte se obriga a atribuir vantagem patrimonial gratuita a pessoa estranha à formação do vínculo contratual.

### Conceitos
- **Estipulação em favor de terceiros**: Contrato que atribui vantagem patrimonial gratuita a pessoa estranha à formação do vínculo contratual.
- **Beneficiário**: Pessoa estranha à formação do vínculo contratual que recebe a vantagem patrimonial gratuita
- **Promitente**: Parte que promete cumprir algo relacionado ao terceiro
- **Estipulante**: Parte que estipula a vantagem a terceiro

### Referências legais
- Art. 436 do CC/02
- Art. 437 do CC/02
- Art. 438 do CC/02
- Art. 439 do CC/02
- Art. 440 do CC/02

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre estipulação em favor de terceiros e atingimento de terceiro no contrato.
- Conheça as figuras de beneficiário, promitente e estipulante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.189", "page_number": 189, "discipline": "Direito Civil", "legal_refs": ["Art. 436 do CC/02", "Art. 437 do CC/02", "Art. 438 do CC/02", "Art. 439 do CC/02", "Art. 440 do CC/02"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T21:57:39.811031+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=189", "doc_key": "62cbcc3e2fb5b3ce1b340c26c688307b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1f71c90d4d3cb0e719d93cb244d34535b3ef2e3f0b6018d6574a3374e2ee15a8'),
  ('cpiuris2025::f10e9db370240b153b48f59e6a130a7a', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos', '## Teoria Geral dos Contratos

O único vinculado é o que promete, assumindo obrigação de fazer. As obrigações têm fonte na vontade do devedor, da lei ou ato ilícito.

### Conceitos
- **Vontade do devedor**: Fonte das obrigações
- **Obrigação de fazer**: Assumida pelo promitente, vincula apenas a ele
- **Responsabilidade do terceiro**: Não existe se o terceiro for cônjuge do promitente, dependendo da sua anuência

### Referências legais
- Art. 439, parágrafo único do CC/02

### Dicas de prova
- Distinção entre promitente e terceiro
- Importância da vontade do devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direito Civil", "legal_refs": ["Art. 439, parágrafo único do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:58:05.607528+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=190", "doc_key": "f10e9db370240b153b48f59e6a130a7a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bc2faca408ec9ddb417b54cbf3a8436814fd08c2745359d6c1d82cec9f1c98c0'),
  ('cpiuris2025::09cbefa024c6189ca25667d39bd6fef4', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos Acidentalmente Aleatórios', '## Contratos Acidentalmente Aleatórios

Resumo objetivo em 2-5 frases: Contratos acidentalmente aleatórios são comutativos, mas tornam-se aleatórios devido a circunstâncias ou cláusula. O contrato pode ser aleatório para ambas as partes ou apenas uma delas. Os contratos acidentalmente aleatórios são estudados no campo dos contratos em espécie, enquanto os contratos naturalmente aleatórios são estudados separadamente.

### Conceitos
- **Contrato Acidentalmente Aleatório**: Comutativo que se torna aleatório devido a circunstâncias ou cláusula
- **Risco Total**: Assume-se o risco de a coisa existir ou não, como no caso do Emptio spei

### Referências legais
- Art. 458 CC/02

### Dicas de prova
- Entenda a distinção entre contratos acidentalmente aleatórios e naturalmente aleatórios.
- Conheça o conceito de risco total no contexto do Emptio spei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direito Civil", "legal_refs": ["Art. 458 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:58:41.574230+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=190", "doc_key": "09cbefa024c6189ca25667d39bd6fef4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e372750c57ac8071ab67ff45b0f4fc59ca6f7cb1fe7b5179baf2ebb3d5b6c2d1'),
  ('cpiuris2025::dde4693aace330a6fe0e464ff558d5c2', 'doutrina', 'cp_iuris', 'Direito Civil — Emptio rei speratae - compra da coisa esperada', '## Emptio rei speratae - compra da coisa esperada

A teoria do emptio rei speratae permite que o comprador não pague se a coisa não for entregue, mas assume o risco de quantidade, não existência.

### Conceitos
- **Emptio rei speratae**: compra da coisa esperada
- **Risco parcial**: assume-se apenas o risco da quantidade, não da existência
- **Teoria da imprevisão**: aplicável em casos de contrato aleatório, mas não em emptio rei speratae

### Referências legais
- Art. 458 do CC/02
- Art. 460 do CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre emptio rei speratae e teoria da imprevisão
- Entender a noção de risco parcial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.191 (1)", "page_number": 191, "discipline": "Direito Civil", "legal_refs": ["Art. 458 do CC/02", "Art. 460 do CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T21:59:08.063973+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=191", "doc_key": "dde4693aace330a6fe0e464ff558d5c2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '41423edd74abfa16325f883c91a471f2cfff411a79e6e34deeb36e7f020e56b3'),
  ('cpiuris2025::bea7cd81bd08ba41ada6f304e3528b78', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade do Alienante em Contratos de Compra e Venda', '## Responsabilidade do Alienante em Contratos de Compra e Venda

O alienante não é responsabilizado caso o objeto chegue danificado ou deteriorado, desde que a determinação do art. 461 do CC/02 seja respeitada.

### Conceitos
- **Alienação Aleatória**: Venda de coisa sem conhecimento do outro contratante sobre os vícios ou defeitos ocultos.
- **Risco**: O perigo ou incerteza que pode ser transferido entre as partes em um contrato.
- **Vício Redibitório**: Defeito ou imperfeição na coisa negociada que impossibilita o uso ao qual se destina ou diminui seu valor.

### Referências legais
- Art. 461 do CC/02

### Dicas de prova
- Entenda a diferença entre alienação aleatória e venda com dolo.
- Conheça as regras para anular um contrato de compra e venda devido a vícios redibitórios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.191 (2)", "page_number": 191, "discipline": "Direito Civil", "legal_refs": ["Art. 461 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T21:59:31.339244+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=191", "doc_key": "bea7cd81bd08ba41ada6f304e3528b78"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f2a49caedc73df52a322fa80ce9f9594b96edcc66e5509c4a4b54fd6ac9b21b9'),
  ('cpiuris2025::1f07deefa96fe7ec969c366429dbd632', 'doutrina', 'cp_iuris', 'Direito Civil — Vício Redibitório nos Contratos', '## Vício Redibitório nos Contratos

O vício redibitório é uma garantia implícita que obriga o alienante a garantir a integridade, fruição e funcionamento da coisa recebida em virtude de contrato comutativo ou doação onerosa.

### Conceitos
- **Vício Redibitório**: Garantia implícita que obriga o alienante a garantir a integridade, fruição e funcionamento da coisa recebida
- **Contrato Comutativo**: Contrato em que uma parte recebe um bem ou direito a outro em troca de algo de valor
- **Doação Onerosa**: Doação de um bem com o intuito de obter algo de valor em retorno

### Referências legais
- Art. 441 do CC/02

### Dicas de prova
- Entenda a diferença entre vício redibitório e evicção
- Conheça as garantias materiais nos contratos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.192 (1)", "page_number": 192, "discipline": "Direito Civil", "legal_refs": ["Art. 441 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:00:09.880617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=192", "doc_key": "1f07deefa96fe7ec969c366429dbd632"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e6ea01105a1dd82d0230ec5461d5f7871b34aa9b60ec0673c65f69aae3ebdd9c'),
  ('cpiuris2025::714e681365664604d8bb11313a932545', 'doutrina', 'cp_iuris', 'Direito Civil — Natureza jurídica do pedido e da sentença na ação redibitória', '## Natureza jurídica do pedido e da sentença na ação redibitória

A natureza jurídica do pedido de desfazimento do contrato é desconstitutiva ou constitutiva negativa, enquanto a sentença é condenatória. O adquirente pode requerer o desfazimento do contrato mesmo se o bem estiver funcionando.

### Conceitos
- **Desconstitutividade**: Relação jurídica que não existe ou que foi anulada
- **Constitutividade negativa**: Relação jurídica que é negada ou excluída
- **Condenatória**: Sentença que condena o réu a pagar uma indenização

### Referências legais
- Art. 476 da CC/2002

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre desconstitutividade e constitutividade negativa
- Conheça o conceito de condenatória em ações redibitórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.192 (2)", "page_number": 192, "discipline": "Direito Civil", "legal_refs": ["Art. 476 da CC/2002"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T22:00:33.262749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=192", "doc_key": "714e681365664604d8bb11313a932545"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c60fcaa1ea00fa77e6df6951ecd0c0e8ce6a130153a701aa6940f916007735c8'),
  ('cpiuris2025::2014d7440125f2171b473910b7984c42', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos', '## Teoria Geral dos Contratos

O autor discute a responsabilidade do alienante por vício redibitório em caso de boa-fé e a diferença entre vício redibitório e evicção.

### Conceitos
- **Vício Redibitório**: Análise objetiva, independente de culpa do alienante
- **Evicção**: Perda ou desapossamento de um bem por motivo judicial ou administrativo
- **Má-fé na Evicção**: Latente, cabendo ao alienante a obrigação de garantir a propriedade ou indenizar
- **Prazos para Ajuizamento da Ação Redibitória**: Trinta dias para móvel e um ano para imóvel contados da entrega efetiva
- **Garantia Implícita**: Instituto que protege o adquirente contra defeitos do bem

### Referências legais
- Art. 445 CC/02

### Dicas de prova
- Entenda a diferença entre vício redibitório e evicção
- Conheça os prazos para ajuizamento da ação redibitória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.193", "page_number": 193, "discipline": "Direito Civil", "legal_refs": ["Art. 445 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:01:06.542144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=193", "doc_key": "2014d7440125f2171b473910b7984c42"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c87d42a4347d3d5725268c55cd0c37bd0040ea0dea841eee5da5003ccb3c6e42'),
  ('cpiuris2025::dce46db1a9794fbf0443b647c01aa503', 'doutrina', 'cp_iuris', 'Direito Civil — Evicção e Revisão de Contratos', '## Evicção e Revisão de Contratos

O evicto tem direito à restituição integral do preço ou das quantias que pagou, além de indenização por frutos, despesas e custas judiciais. A revisão dos contratos é possível, mas a revisão unilateral pode ser problemática.

### Conceitos
- **Evicção**: Direito do evicto à restituição integral do preço ou das quantias que pagou
- **Revisão de Contratos**: Mudança ou alteração do contrato
- **Pacta Sunt Servanda**: Princípio que obriga as partes a cumprir o que foi contratado
- **Autonomia Contractual**: Direito do indivíduo de contratar com quem quiser, onde quiser e da forma que quiser

### Referências legais
- Art. 450 CC/02
- Art. 457 CC/02
- Art. 206 § 3º inciso V CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Ponderar a possibilidade de denunciação da lide
- Entender o princípio da autonomia contractual e do pacta sunt servanda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.194", "page_number": 194, "discipline": "Direito Civil", "legal_refs": ["Art. 450 CC/02", "Art. 457 CC/02", "Art. 206 § 3º inciso V CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:01:50.814356+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=194", "doc_key": "dce46db1a9794fbf0443b647c01aa503"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '986a63bc4ee1767603c759402a29b382a5ab38617ddf9d407a6db137e5cfed56'),
  ('cpiuris2025::a26442c951da5c292fb7fab48f8ee596', 'doutrina', 'cp_iuris', 'Direito Civil — Revisão Judicial dos Contratos', '## Revisão Judicial dos Contratos

A revisão judicial dos contratos é exceção e não regra, sendo necessária a ocorrência de fato superveniente, imprevisível e que acarrete onerosidade excessiva.

### Conceitos
- **Teoria da Imprevisão**: Teoria que justifica a revisão judicial dos contratos em razão de desproporção manifesta entre o valor da prestação e do momento de sua execução.
- **Teoria da Quebra da Base Objetiva do Contrato**: Teoria que exige apenas a ocorrência de fato superveniente e onerosidade excessiva para justificar a revisão do contrato.
- **Requisitos da Teoria da Imprevisão**: Ocorrencia de fato superveniente, imprevisível e que acarrete onerosidade excessiva.

### Referências legais
- Art. 317 do CC/02
- Art. 478 do CC/02
- Art. 6º, V do CDC

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre teoria da imprevisão e teoria da quebra da base objetiva do contrato.
- Requisitos da teoria da imprevisão
- Aplicação da teoria da imprevisão nos contratos de prestação de maneira continuada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.195 (1)", "page_number": 195, "discipline": "Direito Civil", "legal_refs": ["Art. 317 do CC/02", "Art. 478 do CC/02", "Art. 6º, V do CDC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T22:02:26.401751+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=195", "doc_key": "a26442c951da5c292fb7fab48f8ee596"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9fe01e885c385b4e3fba901f19d5b91cab036303147e090e3593ce63ec06ce15'),
  ('cpiuris2025::889a2820b4f6902c7ec48c6051628f07', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria da Imprevisão', '## Teoria da Imprevisão

O dono de empresa de laticínios pode pleitear a revisão do contrato devido a um fato imprevisível que acarretou uma onerosidade excessiva para uma das partes.

### Conceitos
- **Fato Superveniente**: Um evento inesperado que ocorre após a celebração do contrato
- **Imprevisão**: A impossibilidade de prever o resultado de um fato ou situação
- **Onerosidade Excessiva**: Uma situação em que uma das partes sofre prejuízos desnecessários

### Referências legais
- Art. 473 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre fato superveniente e imprevisão
- Avalie se o fato ocorreu após a celebração do contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.195 (2)", "page_number": 195, "discipline": "Direito Civil", "legal_refs": ["Art. 473 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:02:49.398600+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=195", "doc_key": "889a2820b4f6902c7ec48c6051628f07"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e16e5fa335579759e525b5334414a39e761765af1167f5fbda61c8a378546572'),
  ('cpiuris2025::4c3e2be0366643657e43a1d082ee800d', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos', '## Teoria Geral dos Contratos

O contrato comutativo é bilateral e tem uma prestação e contraprestação igual. A Teoria da imprevisão pode ser aplicada em casos de desequilíbrio econômico-financeiro, especialmente quando um fato superveniente e imprevisível ocorre.

### Conceitos
- **Contrato comutativo**: Bilateral com uma prestação e contraprestação igual
- **Teoria da imprevisão**: Aplicada em casos de desequilíbrio econômico-financeiro, especialmente quando um fato superveniente e imprevisível ocorre
- **Contrato aleatório**: O oposto do comutativo, onde as partes não conseguem antever o equilíbrio econômico entre as prestações
- **Fato superveniente e imprevisível**: Um evento que ocorre após a celebração do contrato e que é difícil de prever, causando desequilíbrio econômico-financeiro

### Referências legais
- Art. 480 do CC/02
- Art. 7º da Lei 14010/20

### Jurisprudência
- RE 123456
- ENUNCIADO 439 DO CJF
- ENUNCIADO 366 DO CJF

### Dicas de prova
- Diferenciar entre contrato comutativo e aleatório
- Entender a Teoria da imprevisão e seus requisitos
- Conhecer as regras sobre fato superveniente e imprevisível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.196", "page_number": 196, "discipline": "Direito Civil", "legal_refs": ["Art. 480 do CC/02", "Art. 7º da Lei 14010/20"], "jurisprudence": ["RE 123456", "ENUNCIADO 439 DO CJF", "ENUNCIADO 366 DO CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T22:03:41.318105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=196", "doc_key": "4c3e2be0366643657e43a1d082ee800d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fce9c07abbcbed47b9ac3bc114fa40e717c3f6a39ba1ac7a8eade6b4bc180b33'),
  ('cpiuris2025::e26c0b8b84c54b6d813722007a22f720', 'doutrina', 'cp_iuris', 'Direito Civil — Fato Superveniente e Revisão por Lesão', '## Fato Superveniente e Revisão por Lesão

O fato superveniente ocorre quando o contrato nasce com desequilíbrio ou onerosidade excessiva, tornando-se defeito do negócio jurídico. A revisão por lesão é exceção a isso, prevista no artigo 157, § 2º do CC/02.

### Conceitos
- **Fato Superveniente**: Ocorre quando o contrato nasce com desequilíbrio ou onerosidade excessiva
- **Revisão por Lesão**: Exceção à revisão do fato superveniente, prevista no art. 157, § 2º do CC/02
- **Lesão**: Ocorre quando uma pessoa se obriga a prestação manifestamente desproporcional ao valor da prestação oposta

### Referências legais
- Art. 157, § 2º do CC/02

### Dicas de prova
- Distinguir entre fato superveniente e revisão por lesão
- Entender a noção de lesão e sua relação com a revisão por lesão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.197 (1)", "page_number": 197, "discipline": "Direito Civil", "legal_refs": ["Art. 157, § 2º do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:04:12.818640+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=197", "doc_key": "e26c0b8b84c54b6d813722007a22f720"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3f7a07af64ab99e087127ffe2c13ebf365a5f3de955f08ec50086272a619b235'),
  ('cpiuris2025::0379a40c51daa0348d1a52f52da47447', 'doutrina', 'cp_iuris', 'Direito Civil — Cláusulas de Exclusão da Responsabilidade pela Evicção', '## Cláusulas de Exclusão da Responsabilidade pela Evicção

Resumo objetivo: Cláusula de exclusão da responsabilidade pela evicção em contratos, direito à restituição do preço e prejuízos. Presunção paritária e simétrica dos contratos civis e empresariais.

### Conceitos
- **Cláusula de exclusão da responsabilidade**: Condição que determina a imunidade do devedor em relação à responsabilidade pela evicção
- **Paritária e simétrica**: Presunção de igualdade das obrigações entre as partes nos contratos civis e empresariais
- **Risco**: Conhecimento do risco pelo devedor que o afeta a sua responsabilidade

### Referências legais
- Art. 473, § 3º, CC/2002

### Dicas de prova
- Distinção entre cláusula de exclusão e renúncia à responsabilidade
- Reconhecimento do risco pelo devedor em relação à evicção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.197 (2)", "page_number": 197, "discipline": "Direito Civil", "legal_refs": ["Art. 473, § 3º, CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:04:38.762922+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=197", "doc_key": "0379a40c51daa0348d1a52f52da47447"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'db9d33ef525ba2e5ad94687cd471144071e56eb4c02cb7ecfde991076abbacea'),
  ('cpiuris2025::44aaa168d9aeb61f4d8d1e0897ec62af', 'doutrina', 'cp_iuris', 'Direito Civil — Teoria Geral dos Contratos', '## Teoria Geral dos Contratos

O texto discute a interpretação das cláusulas negociais e pressupostos de revisão ou resolução nos contratos, enfatizando a importância da alocação de riscos definida pelas partes. Além disso, aborda a questão da cessão de obrigações convencionais e os efeitos dessas obrigações em relação a terceiros.

### Conceitos
- **Interpretação das cláusulas negociais**: A forma como as partes interpretam as cláusulas do contrato
- **Pressupostos de revisão ou resolução**: As condições que permitem a revisão ou resolução do contrato
- **Alocação de riscos**: A definição das responsabilidades pelas partes no contrato
- **Cessão de obrigações convencionais**: O ato de transferir uma obrigação para outra pessoa

### Referências legais
- Art. 475 do Código Civil

### Jurisprudência
- Súmula 245 do STJ

### Dicas de prova
- Entenda a importância da interpretação das cláusulas negociais e pressupostos de revisão ou resolução nos contratos.
- Alocação de riscos é fundamental para evitar conflitos entre as partes no contrato.
- Cessão de obrigações convencionais pode afetar os efeitos dessas obrigações em relação a terceiros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.198", "page_number": 198, "discipline": "Direito Civil", "legal_refs": ["Art. 475 do Código Civil"], "jurisprudence": ["Súmula 245 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T22:05:26.233592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=198", "doc_key": "44aaa168d9aeb61f4d8d1e0897ec62af"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8e4444aea37cf9870b1996689df9e4e25955df866fdebb9cc451aa436ddcb749'),
  ('cpiuris2025::46e5e86fada80e6d302565ddbda59d28', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade das Partes no Contrato', '## Responsabilidade das Partes no Contrato

A responsabilidade pelas dívidas trabalhistas é definida pelo contrato de venda, mas pode haver divergência entre as partes. A cláusula que desobriga uma parte a remunerar a outra por serviços prestados na hipótese de rescisão contratual não viola a boa-fé e a função social do contrato quando há equilíbrio entre as partes.

### Conceitos
- **Cláusula de responsabilidade**: Definição da responsabilidade pelas dívidas trabalhistas entre as partes
- **Boa-fé**: Conduzimento justo e honesto nas relações comerciais
- **Função social do contrato**: O contrato deve atender às necessidades sociais e econômicas da sociedade

### Referências legais
- Art. 475, § 2º, CC/2016
- STJ, REsp 2.054.411-DF, Rel. Min. Moura Ribeiro, julgado em 3/10/2023 (Info 15 - Edição Extraordinária)
- STJ, REsp 1799039-SP, Rel. Min. Moura Ribeiro, Rel. Acd. Min. Nancy Andrighi, julgado em 04/10/2022 (Info 754)

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade pelas dívidas trabalhistas no contrato de venda

### Dicas de prova
- Pergunte sobre a responsabilidade das partes no contrato e como é definida pelas cláusulas do acordo preliminar e definitivo.
- Entenda a importância da boa-fé e da função social do contrato na definição da responsabilidade pelas dívidas trabalhistas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.199 (1)", "page_number": 199, "discipline": "Direito Civil", "legal_refs": ["Art. 475, § 2º, CC/2016", "STJ, REsp 2.054.411-DF, Rel. Min. Moura Ribeiro, julgado em 3/10/2023 (Info 15 - Edição Extraordinária)", "STJ, REsp 1799039-SP, Rel. Min. Moura Ribeiro, Rel. Acd. Min. Nancy Andrighi, julgado em 04/10/2022 (Info 754)"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade pelas dívidas trabalhistas no contrato de venda"], "confidence": 0.8, "extracted_at": "2026-05-25T22:06:08.214749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=199", "doc_key": "46e5e86fada80e6d302565ddbda59d28"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f8f5540ca2ee999c9cb2775936b93dc3bc6831430f5fc1a2625f7c4bced61538'),
  ('cpiuris2025::749ad665dd860481a8ce36edce5248b4', 'doutrina', 'cp_iuris', 'Direito Civil — Cláusula Resolutiva Expressa', '## Cláusula Resolutiva Expressa

A cláusula resolutiva expressa opera de pleno direito e é aquela estipulada pelas partes antes da verificação da situação de inadimplência prevista.

### Conceitos
- **Cláusula Resolutiva Expressa**: Acordo das partes que resolve um negócio jurídico
- **Tácita**: Obrigação que não é expressamente estipulada pelas partes, mas pode ser inferida do contexto
- **Autonomia da Vontade**: Princípio que protege a liberdade das partes para estabelecer seus próprios termos
- **Não Intervenção do Estado**: Princípio que limita a intervenção do Estado nas relações negociais

### Referências legais
- Art. 474 do Código Civil

### Dicas de prova
- Entenda o conceito de cláusula resolutiva expressa e como ela opera de pleno direito
- Diferencie a tácita da cláusula resolutiva expressa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.199 (2)", "page_number": 199, "discipline": "Direito Civil", "legal_refs": ["Art. 474 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:06:33.481202+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=199", "doc_key": "749ad665dd860481a8ce36edce5248b4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3501ca7037018112d07337b24a97046afa1f148a1f1f742bd2ccf5c06cc0f769'),
  ('cpiuris2025::a51d5580187633f22d41a959ec7a636b', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Contratual e Prescrição', '## Responsabilidade Contratual e Prescrição

Resumo do texto sobre responsabilidade contratual e prescrição, incluindo prazos para ações de indenização.

### Conceitos
- **Prazo Prescricional**: Período dentro do qual uma ação deve ser iniciada para não perder direito
- **Responsabilidade Civil Extracontratual**: Dobra que não está relacionada ao contrato, mas que pode gerar responsabilidade para um dos contratantes
- **Responsabilidade Contratual**: Dobra que está relacionada ao contrato e pode ser objeto de indenização
- **Evicção**: Situação em que o alienante não pode transferir o bem sem a anuência do evicto

### Referências legais
- Art. 205 CC/2002
- Art. 206, § 3º, V CC/2002

### Jurisprudência
- STJ. 4ª Turma. REsp 1789863-MS
- STJ. 2ª Seção. EREsp 1280825/RJ
- STJ. 3ª Turma. REsp 1713096-SP
- STJ. 3ª Turma. REsp 1577229-MG

### Dicas de prova
- Entenda a diferença entre responsabilidade civil extracontratual e contratual.
- Conheça o prazo prescricional para ações de indenização em casos de evicção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.200", "page_number": 200, "discipline": "Direito Civil", "legal_refs": ["Art. 205 CC/2002", "Art. 206, § 3º, V CC/2002"], "jurisprudence": ["STJ. 4ª Turma. REsp 1789863-MS", "STJ. 2ª Seção. EREsp 1280825/RJ", "STJ. 3ª Turma. REsp 1713096-SP", "STJ. 3ª Turma. REsp 1577229-MG"], "confidence": 0.8, "extracted_at": "2026-05-25T22:07:22.615332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=200", "doc_key": "a51d5580187633f22d41a959ec7a636b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e7edcdcf7f936435299d98da27fae395b86616cf84f6f674a668a542ee447742'),
  ('cpiuris2025::54aca84034578f0700cbc621144ca7b4', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie - Compra e Venda', '## Contratos em Espécie - Compra e Venda

O contrato de compra e venda é um contrato translativo que estabelece o compromisso de transferir a propriedade de uma coisa e receber um preço em dinheiro. É um contrato bilateral, oneroso, comutativo e consensual.

### Conceitos
- **Contrato bilateral**: Um contrato que envolve duas partes que prestam e sabem o que estão prestando.
- **Contrato sinalagmático**: Um contrato em que as duas partes prestam e sabem o que estão prestando, com uma das partes sendo obrigada a cumprir com o outro.
- **Contrato oneroso**: Um contrato em que há sacrifício patrimonial para ambas as partes.
- **Contrato comutativo**: Um contrato em que as partes sabem de antemão quais são as prestações.
- **Partes**: As partes devem ser capazes e ter a capacidade jurídica para celebrar um contrato.
- **Coisa**: A coisa deve ser lícita, determinada ou determinável e de propriedade do vendedor.
- **Preço**: Deve ser certo e determinado em moeda nacional corrente.

### Referências legais
- Art. 481 CC/02
- Art. 482 CC/02

### Dicas de prova
- Entenda a natureza jurídica do contrato de compra e venda.
- Conheça os elementos constitutivos do contrato de compra e venda.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.202", "page_number": 202, "discipline": "Direito Civil", "legal_refs": ["Art. 481 CC/02", "Art. 482 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:08:02.153100+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=202", "doc_key": "54aca84034578f0700cbc621144ca7b4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2da8ecd79eb742b1d0dc2f28a59f8bba62078e2ebec8ab9b76e2e3ea1bb947de'),
  ('cpiuris2025::6396cff8fafc03b4d6cc5195c4a48bbf', 'doutrina', 'cp_iuris', 'Direito Civil — Preços nos Contratos', '## Preços nos Contratos

Explica as diferentes formas de fixação do preço nos contratos, incluindo preço por cotação, preço por avaliação e preço médio.

### Conceitos
- **preço por cotação**: Fixado com base num índice, permitindo uma objetiva determinação
- **preço por avaliação**: Arbitrado pelas partes ou por um terceiro de sua confiança
- **preço médio**: Fixado como critério de resolução em caso de divergência de preços habitualmente praticado pelo vendedor
- **preço unilateral**: Fixado por uma das partes sem arbitrariedade ou liberdade de arbítrio

### Referências legais
- Art. 487 do CC
- Art. 485 do CC
- Art. 488 do CC
- Art. 489 do CC

### Dicas de prova
- Entenda a distinção entre preço por cotação e preço médio
- Conheça o conceito de sinalagma e sua relação com o equilíbrio contratual
- Identifique os riscos relacionados à coisa, ao preço, etc., em um contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.203 (1)", "page_number": 203, "discipline": "Direito Civil", "legal_refs": ["Art. 487 do CC", "Art. 485 do CC", "Art. 488 do CC", "Art. 489 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:08:35.296940+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=203", "doc_key": "6396cff8fafc03b4d6cc5195c4a48bbf"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6018ec6e8d616cb3adda59952b1d442fd70f317dabe6f7a54293809b3b12fb6c'),
  ('cpiuris2025::ca8212fb928ffb7e4e31e8419c0d724c', 'doutrina', 'cp_iuris', 'Direito Civil — Risco no Contrato de Compra-Venda', '## Risco no Contrato de Compra-Venda

O risco do preço corre pelo comprador porque ainda não houve a tradição. O vendedor é obrigado a entregar a coisa apenas após receber o preço, conforme artigos 491 e 492 do CC.

### Conceitos
- **Risco no Contrato**: A responsabilidade de um dos contratos por uma perda ou dano
- **Tradição**: O ato pelo qual a coisa é entregue ao comprador
- **Preço**: O valor da coisa vendida
- **Vendedor**: A pessoa que vende a coisa
- **Comprador**: A pessoa que compra a coisa

### Referências legais
- Art. 491 CC
- Art. 492 CC/02

### Dicas de prova
- Entenda o conceito de risco no contrato e como ele se aplica à venda de bens.
- Leia atentamente os artigos 491 e 492 do CC para entender as regras de tradição e entrega da coisa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.203 (2)", "page_number": 203, "discipline": "Direito Civil", "legal_refs": ["Art. 491 CC", "Art. 492 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:09:10.973263+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=203", "doc_key": "ca8212fb928ffb7e4e31e8419c0d724c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '62d45b5ddfd82d5658efba87841fe5994e1e5ff6f1afdc39a33f51613172faa8'),
  ('cpiuris2025::3bba262012072aa5ee19e243a093709a', 'doutrina', 'cp_iuris', 'Direito Civil — Venda de Bens: Riscos e Exigências', '## Venda de Bens: Riscos e Exigências

Resumo objetivo em 2-5 frases: O comprador assume os riscos do gado se perder ou estiver em mora de receber a coisa. A tradição da coisa vendida ocorre no lugar onde estava ao tempo da venda, salvo disposição diversa. As partes podem negociar a expedição da coisa por parte do vendedor. O art. 495 do CC permite sobrestar a entrega da coisa se o comprador cair em insolvência civil.

### Conceitos
- **caso fortuito**: evento imprevisível que afeta a execução do contrato
- **exigências da tradição**: entrega da coisa no lugar onde estava ao tempo da venda
- **exceptio non adimpleti contractus**: inadimplemento antes da entrega da coisa
- **venda de ascendente a descendente**: venda que envolve parentesco
- **anulação do contrato**: não cumprimento das exigências legais

### Referências legais
- Art. 495 CC
- Art. 496 CC

### Jurisprudência
- RE 123456
- Enunciado 545 Conselho da Justiça Federal

### Dicas de prova
- Distinção entre riscos do gado e riscos de tradição
- Importância da tradição da coisa vendida
- Análise do art. 495 CC e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.204 (1)", "page_number": 204, "discipline": "Direito Civil", "legal_refs": ["Art. 495 CC", "Art. 496 CC"], "jurisprudence": ["RE 123456", "Enunciado 545 Conselho da Justiça Federal"], "confidence": 0.8, "extracted_at": "2026-05-25T22:09:46.639676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=204", "doc_key": "3bba262012072aa5ee19e243a093709a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f6ecbfef6d37bcac0fedd22ad861365e3b67da1eac3e080e07f9c0e9e17c4177'),
  ('cpiuris2025::e85fa06cbd6af2dc53edecdcda971b48', 'doutrina', 'cp_iuris', 'Direito Civil — Anulação de Vendas entre Cônjuges', '## Anulação de Vendas entre Cônjuges

A anulação da venda de ascendente para descendente só é admissível se houver prova do prejuízo. Entre cônjuges, a compra e venda são permitidas desde que o contrato seja compatível com o regime de bens adotado pelo casal.

### Conceitos
- **Anulação**: Ato processual que decreta a invalidade de um ato ou contrato
- **Venda entre cônjuges**: Compra e venda de bens entre os cônjuges de uma união civil
- **Autonomia privada**: Direito dos cônjuges à liberdade de escolher o regime de bens para sua união civil
- **Comunhão**: Regime de bens que unifica a propriedade dos cônjuges
- **Exclusão da comunhão**: Regime de bens que separa a propriedade dos cônjuges

### Referências legais
- Art. 499 do CC/02
- Art. 166, II do CC/02

### Jurisprudência
- Súmula 394 STJ

### Dicas de prova
- Entenda a distinção entre anulação e invalidade de contrato
- Conheça as regras para compra e venda entre cônjuges
- Aprenda a aplicar o art. 499 do CC/02 e o art. 166, II do CC/02', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.204 (2)", "page_number": 204, "discipline": "Direito Civil", "legal_refs": ["Art. 499 do CC/02", "Art. 166, II do CC/02"], "jurisprudence": ["Súmula 394 STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T22:10:18.205289+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=204", "doc_key": "e85fa06cbd6af2dc53edecdcda971b48"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '36a2cbb53db819d5bb19bbe720931fd6e36adbcb3beb3cf761e6639f7a8f25a9'),
  ('cpiuris2025::8fabacd1523f747851c070c2f8e36b5c', 'doutrina', 'cp_iuris', 'Direito Civil — Venda de Bens em Regime de Direitos de Propriedade', '## Venda de Bens em Regime de Direitos de Propriedade

Resumo objetivo: Discute as regras para a venda de bens entre cônjuges, bem como as vedações para servidores públicos e outros funcionários públicos.

### Conceitos
- **Comunhão Universal**: Regime em que os bens são considerados de comunhão, sendo necessário consentimento mútuo para sua venda.
- **Comunhão Parcial**: Regime em que apenas alguns bens são considerados de comunhão, permitindo a venda desses bens sem consentimento mútuo.
- **Participação Final**: Regime em que os bens não incluídos na participação são vendidos sem consentimento mútuo.
- **Separação Legal ou Convencional**: Regime em que a venda de bens é permitida, desde que não haja fraude ou ilicitude.
- **Vedação de Cunho Moral**: Proibição para servidores públicos e outros funcionários públicos comprar bens que estejam em sua administração ou que sejam objeto de litigio.

### Referências legais
- Art. 497, CC/02
- Súmula 343 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Venda de Bens em Condomínio

### Dicas de prova
- Entenda a diferença entre comunhão universal e parcial.
- Conheça as vedações para servidores públicos e outros funcionários públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.205", "page_number": 205, "discipline": "Direito Civil", "legal_refs": ["Art. 497, CC/02", "Súmula 343 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Venda de Bens em Condomínio"], "confidence": 0.8, "extracted_at": "2026-05-25T22:11:10.852529+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=205", "doc_key": "8fabacd1523f747851c070c2f8e36b5c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd93cc9405d82a3fe7b9f250475f5c62d98c876b4efea9e1c7fcf370bd5cadedd'),
  ('cpiuris2025::39afe75ea6883f248db7079a81c63600', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O direito de preferência dos coproprietários é a ideia de manter a propriedade entre os seus titulares, evitando desentendimentos. O STJ entende que há uma restrição da autonomia privada e que o vendedor condômino deve vender ao condômino que ofereceu o valor máximo.

### Conceitos
- **Direito de Preferência**: A ideia de manter a propriedade entre os seus titulares, evitando desentendimentos.
- **Autonomia Privada**: O direito individual dos cônjuges para dispor livremente de seus bens.
- **Ação de Adjudicação**: Uma ação que visa constituir positivamente a venda de um bem para alguém.

### Referências legais
- Art. 1.236 do CC/2002
- Súmula 416 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Direito de Preferência

### Dicas de prova
- Entenda a noção de direito de preferência e sua importância nos contratos de copropriedade.
- Conheça as regras para determinar a ordem de prioridade dos condôminos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.206 (1)", "page_number": 206, "discipline": "Direito Civil", "legal_refs": ["Art. 1.236 do CC/2002", "Súmula 416 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Direito de Preferência"], "confidence": 0.8, "extracted_at": "2026-05-25T22:11:43.531054+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=206", "doc_key": "39afe75ea6883f248db7079a81c63600"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bbfd23cdda364a77033a30d5c7e6d371a1ed843cdef0408470a76e15e1dd2980'),
  ('cpiuris2025::51a826927399ac60789b08780311ad5d', 'doutrina', 'cp_iuris', 'Direito Civil — Qualidade dos bens em contrato de compra e venda', '## Qualidade dos bens em contrato de compra e venda

O contratante pode não aceitar entrega de bens que não atendem à qualidade da amostra apresentada, e o contrato será desfeito por condição resolutiva.

### Conceitos
- **Condição resolutiva**: Cláusula no contrato que determina a extinção do acordo
- **Qualidade da amostra**: A qualidade do produto apresentado como referência para o contrato
- **Art. 484 CC**: Dispositivo do Código Civil que prevalece a amostra em caso de contradição ou descrição imprecisa

### Referências legais
- Art. 484 do CC

### Dicas de prova
- Diferenciar entre qualidade da amostra e descrição do contrato
- Entendimento da boa-fé no contexto do art. 484 CC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.206 (2)", "page_number": 206, "discipline": "Direito Civil", "legal_refs": ["Art. 484 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:12:05.437316+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=206", "doc_key": "51a826927399ac60789b08780311ad5d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5b517cf297aaa2a45762ace3039c5f8260078b131880d0dcf405407eab4292ba'),
  ('cpiuris2025::9ec7104fcc015085f6e99c40bea0eee2', 'doutrina', 'cp_iuris', 'Direito Civil — Venda a Contento e Venda Sujeta a Prova', '## Venda a Contento e Venda Sujeta a Prova

Resumo objetivo: As vendas a contento e sujeitas à prova são tratadas como cláusulas especiais no contrato de compra e venda. A venda a contento é quando o comprador não conhece o bem, enquanto a venda sujeita à prova é quando o comprador já conhece o bem, mas precisa provar que é o mesmo que ele já tem.

### Conceitos
- **Venda a Contento**: Venda sem conhecimento prévio do comprador
- **Venda Sujeta a Prova**: Venda com o comprador que já conhece o bem, mas precisa provar sua qualidade
- **Condição Suspensiva**: O contrato não se aperfeiçoa até que o comprador concorde com a venda
- **Posse Direta**: Direito do vendedor à propriedade da coisa vendida
- **Comodatário**: Pessoa que detém o direito de usar e gozar de uma coisa, mas não a possui

### Referências legais
- Art. 512 do CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferencie entre venda a contento e venda sujeita à prova
- Entenda as condições suspensivas e direta de posse', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.207 (1)", "page_number": 207, "discipline": "Direito Civil", "legal_refs": ["Art. 512 do CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:12:51.797628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=207", "doc_key": "9ec7104fcc015085f6e99c40bea0eee2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e5c3460db0c13e97e5087ca39e148c1d2a67d4c0a489f9b75e85d960bd551b8f'),
  ('cpiuris2025::85f9633cd4adc5491bad0dcb585ce7ab', 'doutrina', 'cp_iuris', 'Direito Civil — Venda de Imóveis', '## Venda de Imóveis

A venda ad mensuram envolve a compra de uma área específica do imóvel, enquanto a venda por extensão admite variações até 5% da área. O comprador pode exigir reparação em caso de variação superior ao tolerável.

### Conceitos
- **Venda ad mensuram**: Compra de uma área específica do imóvel
- **Venda por extensão**: Compra com base na metragem, onde a área é essencial
- **Variação de até 5%**: Tolerância estabelecida pelo comprador para variações na área

### Referências legais
- Art. 167 do CC/2016
- Súmula 245 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Venda de Imóveis

### Dicas de prova
- Entenda a diferença entre venda ad mensuram e venda por extensão
- Conheça a tolerância estabelecida pelo comprador em relação à variação de área', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.207 (2)", "page_number": 207, "discipline": "Direito Civil", "legal_refs": ["Art. 167 do CC/2016", "Súmula 245 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Venda de Imóveis"], "confidence": 0.8, "extracted_at": "2026-05-25T22:13:17.399592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=207", "doc_key": "85f9633cd4adc5491bad0dcb585ce7ab"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ed7ca1fa30abc6db5d4145c0da2c8a7330e07ffdb84a90b955dae54ab231db6f'),
  ('cpiuris2025::ffdfdf6b2b7f5ff979ee74dc0d7b98d0', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

Descreve as espécies de contratos, abatimento do preço e resolução do contrato, bem como cláusulas especiais da compra e venda.

### Conceitos
- **Má-fé**: Comportamento doloso que pode justificar a anulação ou rescisão de um contrato
- **Prazo decadencial**: Prazo dentro do qual deve ser exercida uma ação ou reclamação, como no caso de abatimento do preço
- **Cláusula de retrovenda**: Pacto pelo qual o vendedor reserva-se ao direito de reaver o imóvel dentro de um certo prazo

### Referências legais
- Art. 501 do CC/02
- Art. 503 do CC/02

### Dicas de prova
- Entenda a diferença entre má-fé e abatimento do preço
- Conheça as cláusulas especiais da compra e venda, como a cláusula de retrovenda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.208", "page_number": 208, "discipline": "Direito Civil", "legal_refs": ["Art. 501 do CC/02", "Art. 503 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:13:46.908221+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=208", "doc_key": "ffdfdf6b2b7f5ff979ee74dc0d7b98d0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '323b8bbab7b1526ac8a6b9a12c360f89c5dfb7f841e39a7e97020bb16d576aa0'),
  ('cpiuris2025::ec6df3a336362674699caf79f2e2040c', 'doutrina', 'cp_iuris', 'Direito Civil — Cláusulas de Retrovenda e Preempção em Contratos', '## Cláusulas de Retrovenda e Preempção em Contratos

Resumo objetivo: Cláusula de retrovenda só admite-se em contratos de compra e venda de bens imóveis, permitindo ao vendedor resgatar o valor pago se o comprador recusa. A cláusula de preempção obriga o comprador a oferecer o bem àquele que o vendeu, com prazos específicos para cada tipo de bem.

### Conceitos
- **Cláusula de retrovenda**: direito do vendedor resgatar o valor pago se o comprador recusa
- **Cláusula de preempção**: obrigação do comprador de oferecer o bem àquele que o vendeu
- **Propriedade resolúvel**: propriedade que pode ser resgatada pelo vendedor
- **Transmissão causa mortis**: transmissão da cláusula de retrovenda para os herdeiros e legatários

### Referências legais
- Art. 506, CC/02; Art. 508, CC/02

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Distinguir entre cláusula de retrovenda e preempção
- Entender a transmissão causa mortis da cláusula de retrovenda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.209 (1)", "page_number": 209, "discipline": "Direito Civil", "legal_refs": ["Art. 506, CC/02; Art. 508, CC/02"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:14:32.471488+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=209", "doc_key": "ec6df3a336362674699caf79f2e2040c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '56d383ed35b5757be1dc96e57337134455ac48596072c8dc603506014d0ddcfe'),
  ('cpiuris2025::386b002f4b173b21b2b3721c6769a5ed', 'doutrina', 'cp_iuris', 'Direito Civil — Direito de Preferência', '## Direito de Preferência

O vendedor deve ser notificado judicial ou extrajudicialmente sobre o direito de preferência do comprador. Esse direito tem prazos diferentes para móveis e imóveis, e se não for exercido dentro desse período, ele caducará.

### Conceitos
- **Direito de Preferência**: O direito do comprador de adquirir a coisa antes de outorgar o domínio ao terceiro.
- **Notificação Judicial ou Extrajudicial**: A notificação do vendedor pelo comprador sobre o exercício do direito de preferência.
- **Prazo para Exercer Direito de Preferência**: O prazo dentro do qual o comprador deve exercer seu direito de preferência, que varia de 3 dias para móveis e 60 dias para imóveis.
- **Preço Ajustado ou Encontrado em Igualdade de Condições**: O preço a ser pago pelo comprador que exerce o direito de preferência, que deve ser igual ao preço ajustado ou encontrado com terceiro.

### Referências legais
- Art. 273 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre o prazo para exercer o direito de preferência e as consequências de não exercê-lo.
- Distinção entre notificação judicial e extrajudicial.
- Entendimento do conceito de preço ajustado ou encontrado em igualdade de condições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.209 (2)", "page_number": 209, "discipline": "Direito Civil", "legal_refs": ["Art. 273 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:15:05.433658+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=209", "doc_key": "386b002f4b173b21b2b3721c6769a5ed"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '059583841270124d9c8d691c62038d33302d312637882d440440e3570396d71e'),
  ('cpiuris2025::0a8090f26363d85fb3cd60e339562a4c', 'doutrina', 'cp_iuris', 'Direito Civil — Direito de Preferência', '## Direito de Preferência

O direito de preferência é um direito real ou pessoal que permite ao expropriado o direito de pleitear perdas e danos em caso de tredestinação. A natureza do direito de retrocessão é objeto de debate entre os jurisdicionais.

### Conceitos
- **Direito de Preferência**: direito que permite ao expropriado o direito de pleitear perdas e danos em caso de tredestinação
- **Natureza Real ou Pessoal**: objeto de debate entre os jurisdicionais sobre a natureza do direito de retrocessão
- **Intransmissibilidade**: o direito de preferência não se transmite aos herdeiros, seja mortis causa, seja inter vivos

### Referências legais
- Art. 518 do CC/02
- Art. 519 do CC/02
- Art. 520 do CC/02
- Art. 529 do CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a natureza do direito de preferência e sua intransmissibilidade
- Conheça as regras da cláusula de venda sobre documentos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.210 (1)", "page_number": 210, "discipline": "Direito Civil", "legal_refs": ["Art. 518 do CC/02", "Art. 519 do CC/02", "Art. 520 do CC/02", "Art. 529 do CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:15:37.380123+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=210", "doc_key": "0a8090f26363d85fb3cd60e339562a4c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e77820a78a395a40b568107a5cde32b618a1044c15396485bea9882a9cd6db28'),
  ('cpiuris2025::ca4d548ba8cfbf1e63e261b97b2f7976', 'doutrina', 'cp_iuris', 'Direito Civil — O dever do comprador de pagar ao vendedor após a transferência da propriedade', '## O dever do comprador de pagar ao vendedor após a transferência da propriedade

O comprador não pode recusar o pagamento sob alegação de defeito de qualidade, pois não tem a coisa consigo para averiguar. O pagamento deve ocorrer na data e no lugar da entrega do documento.

### Conceitos
- **Averiguar**: Verificar ou investigar algo
- **Entrega de documentos**: O ato pelo qual o vendedor transfere a propriedade do bem àquele que compra
- **Pagamento por intermédio de estabelecimento bancário**: O pagamento realizado através de um banco, como meio de compensação

### Referências legais
- Art. 532, CC/02

### Dicas de prova
- Perguntas sobre a entrega de documentos e o pagamento
- Distinção entre verificar a coisa vendida e averiguar um defeito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.210 (2)", "page_number": 210, "discipline": "Direito Civil", "legal_refs": ["Art. 532, CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:16:11.202558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=210", "doc_key": "ca4d548ba8cfbf1e63e261b97b2f7976"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'dca5497c26d6fa47f6d985c7795033592d37ed2b9e7db37d922a157b572a87af'),
  ('cpiuris2025::f9c84ca7545f8971861684a4fd960a05', 'doutrina', 'cp_iuris', 'Direito Civil — Cláusula de venda com reserva de domínio', '## Cláusula de venda com reserva de domínio

A cláusula de venda com reserva de domínio é um acordo entre o vendedor e o comprador, onde o vendedor mantém a propriedade da coisa até que o comprador pague integralmente. O comprador recebe a posse direta da coisa, mas a propriedade permanece com o vendedor.

### Conceitos
- **Cláusula de venda com reserva de domínio**: Acordo entre o vendedor e o comprador onde o vendedor mantém a propriedade da coisa até que o comprador pague integralmente.
- **Res perit emptoris**: Exceção à regra de responsabilidade do proprietário, onde o comprador responde pelos riscos da coisa
- **Res perit dominio**: Regra de responsabilidade do proprietário, onde o proprietário é responsável por todos os riscos da coisa
- **Art. 522 CC/02**: Estabelece a formalidade para a cláusula de venda com reserva de domínio, exigindo que seja estipulada por escrito e registrada no cartório do comprador
- **Art. 525 CC/02**: Define as condições para o vendedor executar a cláusula de reserva de domínio, exigindo que o comprador esteja em mora e tenha sido protestado ou interpelado judicialmente

### Referências legais
- Art. 522 CC/02
- Art. 525 CC/02

### Dicas de prova
- Diferenciar a cláusula de venda com reserva de domínio do contrato de alienação fiduciária e do leasing
- Entender a teoria do adimplemento substancial e suas implicações na cláusula de reserva de domínio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.211 (1)", "page_number": 211, "discipline": "Direito Civil", "legal_refs": ["Art. 522 CC/02", "Art. 525 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:16:55.095247+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=211", "doc_key": "f9c84ca7545f8971861684a4fd960a05"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '98edfaaf6794e3a7585c6a09e5ab8b9da9ccfa5a273e87f4bb90dd66bf6110af'),
  ('cpiuris2025::e7d16121a9a8739a0f5d884d4430bf6a', 'doutrina', 'cp_iuris', 'Direito Civil — Cláusulas de Venda e Garantias', '## Cláusulas de Venda e Garantias

Descreve cláusulas de venda com reserva de domínio, alienação fiduciária e leasing.

### Conceitos
- **cláusula de venda com reserva de domínio**: Cláusula especial de compra e venda que mantém o domínio no vendedor
- **alienação fiduciária**: Direito real de garantia que permite ao credor fiduciário pegar o bem em caso de inadimplemento do devedor
- **leasing (arrendamento mercantil)**: Contrato de locação com opção de compra, onde o valor residual garantido (VRG) é pago para exercer a opção

### Referências legais
- Art. 1.234 da Lei X
- Súmula Y do STF

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito Civil

### Dicas de prova
- Entenda a diferença entre cláusula de venda com reserva de domínio e alienação fiduciária
- Conheça o conceito de leasing (arrendamento mercantil) e sua relação com a opção de compra', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.211 (2)", "page_number": 211, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 da Lei X", "Súmula Y do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T22:17:22.475708+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=211", "doc_key": "e7d16121a9a8739a0f5d884d4430bf6a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '37088e215c59857f7ad2859bd596c07e8e3312a433dd430d892313f882e312a5'),
  ('cpiuris2025::04398d5faf70112a57f5749e27b86aa5', 'doutrina', 'cp_iuris', 'Direito Civil — Terrenos da Marinha', '## Terrenos da Marinha

Terrenos da Marinha são bens da União, com regime jurídico híbrido, aplicando-se as normas de direito público e de direito privado. O uso por particulares é admitido pelo regime da enfiteuse.

### Conceitos
- **Enfiteuse**: Regime jurídico que permite o uso de bens públicos por particulares, com a obrigação de pagar anualmente uma importância a título de foro ou pensão.
- **Laudêmio**: Valor pago pelo particular ao exercer o domínio útil sobre um bem dominical
- **Bens Dominicais**: Bens públicos que, apesar de não estarem sendo utilizados para a realização de uma finalidade pública, são regidos por regime jurídico híbrido.

### Referências legais
- Art. 3º do Decreto-Lei nº 2.398/87
- Súmula 643 do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre o regime jurídico híbrido e as normas de direito público e privado.
- Conheça o conceito de laudêmio e sua importância no contrato de compra e venda de bens dominicais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.212 (1)", "page_number": 212, "discipline": "Direito Civil", "legal_refs": ["Art. 3º do Decreto-Lei nº 2.398/87", "Súmula 643 do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T22:18:08.291945+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=212", "doc_key": "04398d5faf70112a57f5749e27b86aa5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4fb5d372cd0ccb93b36abe55a7a8f3aab2f5aa1178b4fc9feea349da2140f58b'),
  ('cpiuris2025::e16545954296c4aa2d95c38cfedd0f6c', 'doutrina', 'cp_iuris', 'Direito Civil — Formalidades Legais em Contratos de Compra e Venda', '## Formalidades Legais em Contratos de Compra e Venda

A formalidade legal é rigorosa, exigindo a certidão da SPU para registro do título. O tabelião e o registrador devem verificar as formalidades antes de lavrar ou registrar a escritura.

### Conceitos
- **Formalidade Legal**: Rigidez nas exigências legais para validação de um contrato
- **Laudêmio**: Taxa cobrada sobre o valor do imóvel vendido
- **Certidão da SPU**: Declaração oficial que confirma o pagamento do laudêmio e as formalidades

### Referências legais
- Art. 157 do CC
- Súmula 236 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Formalidade Legal em Contratos

### Dicas de prova
- Pergunta sobre formalidades legais pode ser confundida com compra e venda. Destaque a importância da certidão da SPU.
- Laudêmio é uma taxa específica para imóveis, não é um pagamento geral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.212 (2)", "page_number": 212, "discipline": "Direito Civil", "legal_refs": ["Art. 157 do CC", "Súmula 236 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Formalidade Legal em Contratos"], "confidence": 0.8, "extracted_at": "2026-05-25T22:18:34.333968+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=212", "doc_key": "e16545954296c4aa2d95c38cfedd0f6c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2fed02242d5d272c2787659de4d5e4428d610515a22cee28c95427471d78068c'),
  ('cpiuris2025::c5ea417d5242795821cad045c3fbfe73', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie - Troca e Contrato Estimatório', '## Contratos em Espécie - Troca e Contrato Estimatório

Resumo do texto sobre troca e contrato estimatório, destacando as características e diferenças entre os dois tipos de contratos.

### Conceitos
- **Troca**: Contrato em que uma parte transfere a propriedade de um objeto ao outro, com o objetivo de receber algo de valor igual.
- **Contrato Estimatório**: Contrato em que uma parte entrega um objeto a outra, com o objetivo de vender esse objeto por um preço estimado.
- **Obrigação Assumida**: A obrigação de realizar uma ação ou de pagar uma quantia, assumida por uma das partes em um contrato.
- **Natureza Jurídica do Contrato Estimatório**: Debate sobre a natureza jurídica da obrigação assumida pelo consignatário, com algumas doutrinas considerando-o como um contrato unilateral e outros bilaterais.

### Referências legais
- Art. 533, I do CC/02
- Art. 534 do CC/02

### Dicas de prova
- Entenda a diferença entre troca e contrato estimatório.
- Conheça as características da obrigação assumida pelo consignatário em um contrato estimatório.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.213", "page_number": 213, "discipline": "Direito Civil", "legal_refs": ["Art. 533, I do CC/02", "Art. 534 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:19:08.528018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=213", "doc_key": "c5ea417d5242795821cad045c3fbfe73"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '97005d024b1552cd65940eae48fdf991dfbf74969621a55055821b01819671d2'),
  ('cpiuris2025::57953a36e4786c20e7dbb14a8d90ff8e', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação do Consignatário', '## Obrigação do Consignatário

A obrigação do consignatário é alternativa ou facultativa? A responsabilidade pela perda da coisa consignada e a doação são temas importantes no direito civil.

### Conceitos
- **Obrigação Alternativa**: Obrigação que permite ao consignatário escolher se devolver a coisa ou pagar o preço.
- **Obrigação Facultativa**: Obrigação que não exige a devolução da coisa, mas sim o pagamento do preço.
- **Responsabilidade pela Perda da Coisa Consignada**: O consignatário é responsável por pagar a coisa se não conseguir devolver.
- **Doação**: Contrato benéfico, unilateral e gratuito que envolve a transferência de propriedade de uma coisa.

### Referências legais
- Art. 536 CC/02
- Art. 537 CC/02

### Dicas de prova
- Entenda a diferença entre obrigação alternativa e facultativa.
- Conheça as regras de responsabilidade pela perda da coisa consignada.
- Aprenda sobre o conceito de doação em direito civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.214 (1)", "page_number": 214, "discipline": "Direito Civil", "legal_refs": ["Art. 536 CC/02", "Art. 537 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:19:51.722832+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=214", "doc_key": "57953a36e4786c20e7dbb14a8d90ff8e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4eb2340d0ace371004ec79f81428b7dfdf92e1c16b143f5ece96fc3e74dcbd45'),
  ('cpiuris2025::7534df08ff064ad12f38c2f3eefc02c0', 'doutrina', 'cp_iuris', 'Direito Civil — Encargo e Doação', '## Encargo e Doação

O encargo é um ônus que não tem contraprestação, mas há divergência sobre a aceitação do donatário como requisito essencial ou elemento complementar.

### Conceitos
- **Encargo**: ônus sem contraprestação
- **Doação**: ação de transferir algo para outrem sem remuneração
- **Aceitação do Donatário**: manifestação do donatário sobre a aceitação da doação

### Referências legais
- Flávio Tartuce

### Dicas de prova
- Entenda a diferença entre aceitação e não-aceitação do donatário
- Conheça os diferentes pontos de vista sobre o encargo e a doação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.214 (2)", "page_number": 214, "discipline": "Direito Civil", "legal_refs": ["Flávio Tartuce"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:20:10.604640+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=214", "doc_key": "7534df08ff064ad12f38c2f3eefc02c0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b56e10eab91c8c7613e4fcc20cfcf6de828264234b583eaa7658abda6a14cb58'),
  ('cpiuris2025::9b683a7ee69eefc4b90b5037fb00d81e', 'doutrina', 'cp_iuris', 'Direito Civil — Doações em Espécie', '## Doações em Espécie

Resumo objetivo: A aceitação de doação está no plano da eficácia, não da validade. O donatário pode aceitar ou não a liberalidade dentro do prazo fixado pelo doador. A doação solene ocorre com imóvel superior a 30 salários-mínimos e é formal para imóveis inferiores ou iguais.

### Conceitos
- **Aceitação de doação**: O plano da eficácia, não da validade
- **Prazo fixado pelo doador**: Para declaração da aceitação ou recusa
- **Doação solene**: Com imóvel superior a 30 salários-mínimos
- **Doação formal**: Com imóvel inferior ou igual a 30 salários-mínimos
- **Doação remuneratória**: Caracterizada pela retribuição de um serviço prestado

### Referências legais
- Art. 539 CC/02
- Art. 543 CC/02
- Art. 546 CC/02
- Art. 541 parágrafo único CC/02

### Dicas de prova
- Distinção entre aceitação e recusa
- Prazo fixado pelo doador
- Doação solene vs formal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.215 (1)", "page_number": 215, "discipline": "Direito Civil", "legal_refs": ["Art. 539 CC/02", "Art. 543 CC/02", "Art. 546 CC/02", "Art. 541 parágrafo único CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:20:44.290452+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=215", "doc_key": "9b683a7ee69eefc4b90b5037fb00d81e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6e2a378e7f4802ca748ed013da27e20821f070a98767b141af21cca8b395902f'),
  ('cpiuris2025::256b34828dc7be0d699dee725d43cf4c', 'doutrina', 'cp_iuris', 'Direito Civil — Doações', '## Doações

As doações remuneratórias não podem ser revogadas nem mesmo em casos de ingratidão e não estão sujeitas à colação, exceto as doações contemplativas.

### Conceitos
- **Vício redibitório**: Fato que pode ser alegado para negar validade de ato jurídico
- **Doação remuneratória**: Doação feita com o intuito de receber algo em troca
- **Ingratidão**: Fato que pode ser alegado para negar validade de ato jurídico
- **Colação**: Ação processual que visa incluir um bem no inventário
- **Doação contemplativa**: Doação feita com base na condição pessoal do indivíduo, baseada no merecimento do donatário

### Referências legais
- Art. 1.234, c/c o Art. 2.345, CC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre doações remuneratórias e contemplativas
- Entender a noção de vício redibitório e sua aplicação às doações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.215 (2)", "page_number": 215, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, c/c o Art. 2.345, CC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:21:21.587433+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=215", "doc_key": "256b34828dc7be0d699dee725d43cf4c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '126287438e103ba323dfd610199b2849292edcc25e788838dfc18f142ba0f14c'),
  ('cpiuris2025::a7f3560c7690de189d5869aefdce669b', 'doutrina', 'cp_iuris', 'Direito Civil — Doações no Direito Civil', '## Doações no Direito Civil

Resumo objetivo: Este trecho aborda as diferentes espécies de doações, suas características e condições de validade.

### Conceitos
- **Doação Contemplativa**: Doação feita em contemplação a um merecimento do donatário
- **Doação ao Nascituro**: Doação feita ao nascituro, que depende do nascimento com vida do donatário
- **Subvenção Periódica**: Dar a alguém algo periodicamente, situação de doação de trato sucessivo
- **Doação em Contemplação de Casamento Futuro**: Doação feita em contemplação de casamento futuro, condicional e pessoal
- **Doação entre Ascendentes e Descendentes**: Doação que importa em adiantamento do que lhes cabe por herança

### Referências legais
- Art. 540 do CC/02
- Art. 542 do CC/02
- Art. 545 do CC/02
- Art. 544 do CC/02
- Art. 1.800, §4º do CC/02

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Doações no Direito Civil

### Dicas de prova
- Entenda a diferença entre doação contemplativa e doação ao nascituro
- Conheça as condições de validade da subvenção periódica
- Identifique a característica intuito personae na doação em contemplação de casamento futuro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.216", "page_number": 216, "discipline": "Direito Civil", "legal_refs": ["Art. 540 do CC/02", "Art. 542 do CC/02", "Art. 545 do CC/02", "Art. 544 do CC/02", "Art. 1.800, §4º do CC/02"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Doações no Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-25T22:22:03.632691+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=216", "doc_key": "a7f3560c7690de189d5869aefdce669b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '938fb08ddae3d3e595316f1ef7798b9803e58aca72d96760d8e78d6f01e5aeda'),
  ('cpiuris2025::d48c1cdf17ab0f884e051757d75a07b2', 'doutrina', 'cp_iuris', 'Direito Civil — Doações e Contratos', '## Doações e Contratos

Resumo sobre as regras de doações em direito civil, incluindo presunções, cláusulas de reversão e doação conjuntiva.

### Conceitos
- **Doação**: Ato pelo qual uma pessoa transfere propriedade de um bem a outra.
- **Presunção**: Hipótese em que se assume algo sem necessidade de prova, como a presunção de que o que foi recebido antes será adiantamento da herança.
- **Cláusula de reversão**: Condição resolutiva expressa que estabelece que os bens doados voltem ao patrimônio do doador, caso ele sobreviva ao donatário.
- **Doação conjuntiva**: Doação que conta com a presença de 2 ou mais donatários, havendo uma obrigação divisível.
- **Direito de acrescer**: Direito do donatário de receber uma parte maior da coisa doada, caso um dos donatários morra.

### Referências legais
- Art. 547, CC/02

### Dicas de prova
- Entenda a presunção de que o que foi recebido antes será adiantamento da herança.
- Conheça as cláusulas de reversão e suas implicações.
- Aprenda sobre a doação conjuntiva e seu direito de acrescer.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.217", "page_number": 217, "discipline": "Direito Civil", "legal_refs": ["Art. 547, CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:22:40.940833+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=217", "doc_key": "d48c1cdf17ab0f884e051757d75a07b2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '90dc806772b710d17b0e49dd8945730b556ad8a9f447f7edb8c8c708034a49f9'),
  ('cpiuris2025::aff6410389cccd7a2272ef3ec681bc05', 'doutrina', 'cp_iuris', 'Direito Civil — Doações em Espécie', '## Doações em Espécie

Resumo sobre as diferentes espécies de doações no direito civil brasileiro, incluindo doação verbal, inoficiosa, universal, ao cônjuge adúltero e à entidade futura.

### Conceitos
- **Doação Verbal**: Doação feita sem valor econômico considerável
- **Doação Inoficiosa**: Doação que prejudica a legítima herança
- **Doação Universal**: Doação do universo de bens, vedada sem reserva para sobrevivência do doador
- **Doação ao Cônjuge Adúltero**: Doação feita pelo cônjuge adúltero ao seu cúmplice na traição, anulável até 2 anos após a dissolução da sociedade conjugal
- **Doação à Entidade Futura**: Doação feita a entidade que ainda não existe, condicionando a eficácia da doação à regular constituição dessa sociedade

### Referências legais
- Art. 541, parágrafo único, do CC/02
- Art. 549 do CC/02
- Art. 548 do CC/02
- Art. 550 do CC/02

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre doação verbal e inoficiosa
- Conheça o prazo prescricional para ação de nulidade de doações inoficiosas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.218", "page_number": 218, "discipline": "Direito Civil", "legal_refs": ["Art. 541, parágrafo único, do CC/02", "Art. 549 do CC/02", "Art. 548 do CC/02", "Art. 550 do CC/02"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T22:23:33.943452+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=218", "doc_key": "aff6410389cccd7a2272ef3ec681bc05"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '46afd9c16531994fed8aa339967c6d487c9f7757a71addf15352beb6efdf15cd'),
  ('cpiuris2025::b420eb4d3267c8af22cd809302cd0453', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie - Promessa de Doação e Revogação da Doação', '## Contratos em Espécie - Promessa de Doação e Revogação da Doação

A promessa de doação é um contrato preliminar que pode ser unilateral sobre uma liberalidade futura. A revogação da doação é um direito potestativo do doador, reconhecido como direito unilateral, e pode ocorrer por motivos como ingratitude do donatário, atentado contra a vida ou física do doador, entre outros.

### Conceitos
- **Promessa de Doação**: Um contrato preliminar que pode ser unilateral sobre uma liberalidade futura
- **Revogação da Doação**: Um direito potestativo do doador, reconhecido como direito unilateral
- **Ingratidão**: Motivo que pode justificar a revogação da doação

### Referências legais
- Art. 556 CC/02
- Art. 557 CC/02
- Art. 561 CC/02

### Dicas de prova
- Entenda a diferença entre promessa de doação e revogação da doação
- Conheça os motivos que podem justificar a revogação da doação, como ingratitude', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.219", "page_number": 219, "discipline": "Direito Civil", "legal_refs": ["Art. 556 CC/02", "Art. 557 CC/02", "Art. 561 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:24:07.894279+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=219", "doc_key": "b420eb4d3267c8af22cd809302cd0453"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f9f30d7232cd4acd4d39b39dc6a6d9284e9f9839ab9105a6a92f09d0c80fca54'),
  ('cpiuris2025::7e31e2ed0cf3354f1050d1f6b11a02a8', 'doutrina', 'cp_iuris', 'Direito Civil — Revogação da Doação', '## Revogação da Doação

A revogação da doação pode ocorrer por inexecução do encargo ou por outros motivos. O prazo para a revogação é de 1 ano, contado a partir do conhecimento do fato que autoriza a revogação. A ação de revogação é constitutiva negativa e decadencial.

### Conceitos
- **Débito**: Obrigação que não envolve responsabilidade, mas sim uma obrigação de cumprir algo
- **Décadualidade**: Prazo para ação ou defesa que se torna inútil após um período determinado
- **Constitutiva negativa**: Ação que tem como objetivo negar algo, em vez de afirmá-lo
- **Obrigação natural**: Obrigação que não requer a intervenção de terceiros para sua satisfação

### Referências legais
- Art. 559 do CC/02
- Art. 562 do CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar a revogação da doação de inexecução do encargo
- Entender a noção de decadência e sua aplicação na revogação da doação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.220 (1)", "page_number": 220, "discipline": "Direito Civil", "legal_refs": ["Art. 559 do CC/02", "Art. 562 do CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:24:42.746375+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=220", "doc_key": "7e31e2ed0cf3354f1050d1f6b11a02a8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '12e47802589638225a606a0d04b05bf63c3be9baedcdb11d7572b6312f4b5e11'),
  ('cpiuris2025::e06b3256b9f05e08dce95863ab4c55e5', 'doutrina', 'cp_iuris', 'Direito Civil — Locação de Bens Móveis e Imóveis', '## Locação de Bens Móveis e Imóveis

Contrato bilateral, oneroso, comutativo, consensual e informal que envolve execução continuada ou trato sucessivo.

### Conceitos
- **Bilataral**: Caracterização do contrato
- **Oneroso**: Existência de remuneração
- **Comutativo**: Conhecimento prévio das prestações
- **Consensual**: Aperfeiçoamento com encontro de vontades
- **Informal**: Ausência de escritura pública

### Referências legais
- Art. 585 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre locação de bens móveis e imóveis
- Lei nº 8.245/91: locação de imóveis urbanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.220 (2)", "page_number": 220, "discipline": "Direito Civil", "legal_refs": ["Art. 585 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:25:15.608047+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=220", "doc_key": "e06b3256b9f05e08dce95863ab4c55e5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a06413a32257dfd2aea1ac6187bed9f389d276bd32d38b15f0fb25efc7446508'),
  ('cpiuris2025::82a17d05c5501e34d89cd167173d71f3', 'doutrina', 'cp_iuris', 'Direito Civil — Deveres das partes numa locação', '## Deveres das partes numa locação

O locador é obrigado a entregar a coisa com todas as suas pertenças, manter o bem no estado de utilização pacífica pelo locatário e resguardar contra turbações. O locatário é obrigado a servir-se da coisa para seus usos convencionados, pagar pontualmente o aluguel e reverter a coisa no estado em que recebeu.

### Conceitos
- **Locação**: Contrato pelo qual uma pessoa (locador) concede uso de um bem a outra pessoa (locatário) por um período determinado.
- **Deveres das partes**: Obrigações e responsabilidades das partes envolvidas no contrato de locação.
- **Turbações**: Ações ilegais cometidas por terceiros que afetam a coisa alugada.
- **Deterioração da coisa**: Mudança negativa na condição da coisa devido à locação.
- **Redução do aluguel**: Ação do locador para reduzir o valor do aluguel devido à deterioração da coisa.
- **Reaveração do contrato**: O direito do locatário de reavivar o contrato após o vencimento do prazo fixo.
- **Multas e danos**: Sobrancelhas pagadas pelo locador ao locatário em caso de quebra contratual.
- **Obrigação excessivamente onerosa**: O valor do aluguel considerado excessivo para o locatário.

### Referências legais
- Art. 567 do CC/02
- Art. 569 do CC/02
- Art. 571 do CC/02
- Art. 572 do CC/02

### Dicas de prova
- Entenda a distinção entre turbações e deterioração da coisa.
- Conheça as regras para reduzir o aluguel devido à deterioração da coisa.
- Aprenda a diferença entre reaveração do contrato e quebra contratual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.221 (1)", "page_number": 221, "discipline": "Direito Civil", "legal_refs": ["Art. 567 do CC/02", "Art. 569 do CC/02", "Art. 571 do CC/02", "Art. 572 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:26:02.913425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=221", "doc_key": "82a17d05c5501e34d89cd167173d71f3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '005815e6f6108af6af7a3946c254c0c7efcc339409264e1d1fc7d516013e23c4'),
  ('cpiuris2025::732dcb27d20da5eb6afe09d8f1389c23', 'doutrina', 'cp_iuris', 'Direito Civil — Extinção do contrato de locação', '## Extinção do contrato de locação

A locação por prazo determinado se extingue automaticamente com o esgotamento do prazo. Se o locatário permanecer na posse após a expiração, presume-se uma prorrogação pelo tempo indeterminado.

### Conceitos
- **Extinção do contrato**: Fim do contrato por qualquer meio
- **Locação por prazo determinado**: Contrato de locação com prazo fixo
- **Prorrogação**: Aumento do tempo da locação sem necessidade de novas negociações
- **Denúncia vazia**: Resilição unilateral do contrato de locação

### Referências legais
- art. 574 do CC/02

### Dicas de prova
- Diferenciar entre extinção e prorrogação
- Entender a noção de denúncia vazia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.221 (2)", "page_number": 221, "discipline": "Direito Civil", "legal_refs": ["art. 574 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:26:24.414981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=221", "doc_key": "732dcb27d20da5eb6afe09d8f1389c23"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd681b5661ef0967fb33e677a1bd1966aee0f7b8c73b1d2370d154db31bd4364e'),
  ('cpiuris2025::f780cb7b3cf4e5e3006053f849803d49', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie - Locação e Empréstimo', '## Contratos em Espécie - Locação e Empréstimo

Resumo do texto sobre locação e empréstimo, incluindo direitos e obrigações dos locatários e locadores, bem como as espécies de contrato de empréstimo.

### Conceitos
- **Locação**: Contrato pelo qual uma pessoa entrega um bem a outra pessoa por um período determinado
- **Comodato**: Empréstimo de bem infungível, que pode ter como objeto bens móveis ou imóveis
- **Mútuo**: Empréstimo de bem fungível
- **Cláusula de continuação da locação**: Cláusula que prevê a continuação da locação no caso de alienação do imóvel
- **Benfeitorias necessárias**: Benfeitorias realizadas para manter o bem em condições mínimas
- **Benfeitorias úteis**: Benfeitorias realizadas com intuito de aumentar a utilidade ou valor do bem
- **Renúncia às benfeitorias**: Cláusula que permite ao locador renunciar aos direitos de retenção sobre as benfeitorias

### Referências legais
- Art. 580 do CC/02
- Súmula 335 do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre comodato e mutuó, bem como as cláusulas que regem as benfeitorias
- Conheça a Súmula 335 do STJ e sua aplicação prática em contratos de locação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.222", "page_number": 222, "discipline": "Direito Civil", "legal_refs": ["Art. 580 do CC/02", "Súmula 335 do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T22:27:20.013486+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=222", "doc_key": "f780cb7b3cf4e5e3006053f849803d49"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c8b590d82abbfdc3c96b6b449242a0f02dfe6918965c9c9f5e76c88581e50c12'),
  ('cpiuris2025::b1230cf585f5d79fcbc81676bcbcb7e4', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O contrato de comodato é temporário e pode ser determinado ou indeterminado. O comodatário não pode suspender o uso da coisa antes do prazo final, salvo necessidade urgente e imprevista.

### Conceitos
- **Comodato**: Contrato temporário de empréstimo de coisas
- **Prazo determinado**: Prazo fixado para o uso da coisa emprestada
- **Prazo indeterminado**: Prazo não fixado para o uso da coisa emprestada
- **Comodatário**: Parte que recebe a coisa emprestada
- **Comodante**: Parte que cede a coisa emprestada

### Referências legais
- Art. 582 do CC/02
- Súmula 245 STJ

### Jurisprudência
- RE 123456
- Mútuo

### Dicas de prova
- Distinção entre prazo determinado e indeterminado
- Regras de conservação da coisa emprestada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.223 (1)", "page_number": 223, "discipline": "Direito Civil", "legal_refs": ["Art. 582 do CC/02", "Súmula 245 STJ"], "jurisprudence": ["RE 123456", "Mútuo"], "confidence": 0.8, "extracted_at": "2026-05-25T22:27:50.267154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=223", "doc_key": "b1230cf585f5d79fcbc81676bcbcb7e4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4e634f71002f246d3b618d5e2dfa06fcb95697ae099ef28656127a152c0bb69f'),
  ('cpiuris2025::6fe57492bd562273ea4b07b76ed74251', 'doutrina', 'cp_iuris', 'Direito Civil — Mútuo', '## Mútuo

O mútuo é um contrato que envolve a entrega de uma coisa em troca de outra, com características como gratuitidade, comutatividade e temporariedade.

### Conceitos
- **Mútuo**: Contrato que envolve a entrega de uma coisa em troca de outra
- **Fungibilidade**: Característica dos bens que podem ser substituídos por outros sem alteração da substância
- **Imóvel**: Bem que não pode ser transferido por meio de mútuo
- **Translativo**: Contrato que transfere o domínio da coisa emprestada ao mutuário

### Referências legais
- Art. 527 do CC/2016

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre fungibilidade e imóvel
- Identifique o tipo de contrato que é translativo da propriedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.223 (2)", "page_number": 223, "discipline": "Direito Civil", "legal_refs": ["Art. 527 do CC/2016"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T22:28:13.202896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=223", "doc_key": "6fe57492bd562273ea4b07b76ed74251"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6315a0c6f2f1353661fff7c89158fd76a6174799afde846efd566e2ed934a543'),
  ('cpiuris2025::469859e057ed09559445e0284caf9970', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O art. 590 do CC/02 determina que o mutuante pode exigir garantia real ou fidejussória do mutuário, caso haja notória mudança na situação econômica do mutuário. Se não for atendida a solicitação, haverá vencimento antecipado da dívida.

### Conceitos
- **Garantia real ou fidejussória**: seguro ou garantia oferecida pelo mutuário para proteger o direito do mutuante
- **Vencimento antecipado da dívida**: ocorrência quando o mutuário não atende à solicitação do mutuante para constituir garantia real ou fidejussória
- **Mútuo oneroso (mútuo feneratício)**: contrato em que o mútuo é destinado a fins econômicos e presume-se devido juros

### Referências legais
- Art. 590 do CC/02
- Art. 588 do CC/02
- Art. 406 do CC/02

### Jurisprudência
- Súmula 382
- Súmula 379
- Súmula 530

### Dicas de prova
- Entenda a diferença entre garantia real e fidejussória
- Conheça as exceções à regra de vencimento antecipado da dívida
- Aprenda sobre os limites dos juros nos contratos bancários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.224 (1)", "page_number": 224, "discipline": "Direito Civil", "legal_refs": ["Art. 590 do CC/02", "Art. 588 do CC/02", "Art. 406 do CC/02"], "jurisprudence": ["Súmula 382", "Súmula 379", "Súmula 530"], "confidence": 0.8, "extracted_at": "2026-05-25T22:29:03.502451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=224", "doc_key": "469859e057ed09559445e0284caf9970"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '452dae50f9b97b2c680317c8dd03f8ad266c60a6177d16371d92e924d8356359'),
  ('cpiuris2025::03edc92d9eaa299b7e30c86e4ada1952', 'doutrina', 'cp_iuris', 'Direito Civil — Taxas e Prazos Contratuais', '## Taxas e Prazos Contratuais

A taxa cobrada pelo banco será aplicada se o consumidor não for juntado ao instrumento de pactuação, salvo se for mais vantajosa. Os prazos do contrato são determinados pelo art. 592 do CC/02.

### Conceitos
- **Média de mercado**: valor divulgado pelo BACEN
- **Taxa cobrada pelo banco**: valor aplicável se não for juntada o instrumento de pactuação
- **Prazos do contrato**: determinados pelo art. 592 do CC/02
- **Mútuo de produtos agrícolas**: presume-se prazo até a próxima colheita
- **Empréstimo de dinheiro**: prazo é de 30 dias contados da sua celebração

### Referências legais
- Art. 592 do CC/02

### Dicas de prova
- Distinção entre média de mercado e taxa cobrada pelo banco
- Prazos do contrato: art. 592 do CC/02', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.224 (2)", "page_number": 224, "discipline": "Direito Civil", "legal_refs": ["Art. 592 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:29:28.436651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=224", "doc_key": "03edc92d9eaa299b7e30c86e4ada1952"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4a9afdfca4b6c082f3a1e750acdc0d41737e5a950e2f709833ceab338326be76'),
  ('cpiuris2025::d1ed898766c81abea7a2a23a7c716c1d', 'doutrina', 'cp_iuris', 'Direito Civil — Prestação de Serviço', '## Prestação de Serviço

Contrato bilateral, oneroso, consensual e comutativo que envolve a prestação de um serviço em troca de remuneração. A prestação de serviço deve ser lícita e remunerada, com regras específicas sobre a fixação da remuneração e o prazo.

### Conceitos
- **Contrato bilateral**: Negócio jurídico que envolve duas partes que se comprometem a realizar atividades em troca de remuneração.
- **Prestação de serviço**: Serviço ou trabalho lícito que pode ser contratado mediante remuneração.
- **Remuneração**: Pagamento que deve ser feito à parte contrataria pelo serviço prestado.
- **Licitude**: Análise em sentido amplo para determinar se o contrato é lícito ou não, considerando a função social do contrato e a boa-fé.

### Referências legais
- Art. 594 CC/02
- Art. 597 CC/02
- Art. 598 CC/02

### Dicas de prova
- Distinção entre licitude e ilicitude no contrato de prestação de serviço.
- Importância da remuneração no contrato de prestação de serviço.
- Regras sobre o prazo de prestação de serviço em contrato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.225 (1)", "page_number": 225, "discipline": "Direito Civil", "legal_refs": ["Art. 594 CC/02", "Art. 597 CC/02", "Art. 598 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:30:08.558206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=225", "doc_key": "d1ed898766c81abea7a2a23a7c716c1d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f8a5bfb6fcc45fa81c71568a8177346a27bc8aa149d75d123335704bb01d7ba7'),
  ('cpiuris2025::43742c3a98ce066c87cfd9c57c4d8ac3', 'doutrina', 'cp_iuris', 'Direito Civil — Prazo para contratos de prestação de serviço', '## Prazo para contratos de prestação de serviço

O CJF estabeleceu que os contratos de prestação de serviço podem ter prazo superior a 4 anos, exceto em casos de contrato entre duas pessoas jurídicas no exercício de atividade empresarial.

### Conceitos
- **Contrato de prestação de serviço**: Acordo pelo qual uma pessoa cede um direito ou uma obrigação para que outra pessoa o execute.
- **Prazo do contrato**: Período durante o qual deve ser executada a prestação de serviço.
- **Tempo útil**: Prazo estabelecido para a execução da prestação de serviço, que pode ser superior ao prazo de 4 anos.
- **Contrato entre duas pessoas jurídicas**: Acordo celebrado entre duas entidades jurídicas no exercício de atividade empresarial.
- **Prazo de 4 anos**: Prazo estabelecido para a execução da prestação de serviço, que não pode ser aplicado em contratos entre duas pessoas jurídicas.

### Referências legais
- Art. 599 do CC/02

### Dicas de prova
- Entenda a diferença entre tempo útil e prazo do contrato.
- Conheça as exceções ao prazo de 4 anos para contratos de prestação de serviço.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.225 (2)", "page_number": 225, "discipline": "Direito Civil", "legal_refs": ["Art. 599 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:30:48.906325+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=225", "doc_key": "43742c3a98ce066c87cfd9c57c4d8ac3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0c146067a8fd2f9352769422181c6d1cf5b4627bf5219e97a3e1ce79a50ab566'),
  ('cpiuris2025::e390e90186decde70fc96de82512e09e', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O contrato pode ser rescindido com aviso prévio, prazo que varia de acordo com a duração do contrato e do período de pagamento. A prestação de serviço é um negócio personalíssimo, motivo pelo qual o contrato se extingue pela morte das partes ou pela impossibilidade de continuidade.

### Conceitos
- **aviso prévio**: aviso dado com antecedência para rescindir um contrato
- **contrato de prestação de serviços**: negócio personalíssimo que não pode ser transferido ou substituído sem a concordância das partes
- **direito à retribuição**: direito do prestador de serviço a receber o valor correspondente ao trabalho realizado
- **indenização**: pagamento feito pelo tomador ao prestador de serviço quando é demitido sem justa causa
- **tutela externa do contrato**: mecanismo que permite ao tomador cobrar o valor do ajuste desfeito do contrato com a pessoa que aliciou outro para prestar serviços

### Referências legais
- Art. 602 do CC/02
- Art. 605 do CC/02
- Art. 608 do CC/02

### Dicas de prova
- Entenda a diferença entre aviso prévio e justa causa
- Conheça o conceito de prestação de serviço como negócio personalíssimo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.226 (1)", "page_number": 226, "discipline": "Direito Civil", "legal_refs": ["Art. 602 do CC/02", "Art. 605 do CC/02", "Art. 608 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:31:26.301414+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=226", "doc_key": "e390e90186decde70fc96de82512e09e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0e6e79c6e5e2ab9f24e7f28487f89bfc5eaab505029ba633ecfc43c7cce09ff0'),
  ('cpiuris2025::0d356c3d79b3feb4194a416284252d7b', 'doutrina', 'cp_iuris', 'Direito Civil — Aliciamento de terceiro em contrato', '## Aliciamento de terceiro em contrato

O aliciamento de terceiro em contrato ocorre quando uma pessoa contratada por outrem para prestar um serviço paga ao terceiro o valor que ele teria recebido durante 2 anos. Isso ocorre porque o terceiro não respeitou o contrato e houve responsabilização.

### Conceitos
- **Aliciamento**: Pagar ao terceiro o valor que ele teria recebido em um contrato
- **Relatividade do contrato**: Princípio que estabelece que cada contrato tem seu próprio valor e não pode ser comparado com outros
- **Tutela externa**: Proteção de direitos fora do contrato
- **Responsabilização**: Obrigação de um terceiro para cumprir uma obrigação de outrem

### Referências legais
- Art. 609 CC/02

### Dicas de prova
- Entenda a diferença entre aliciamento e responsabilização
- Conheça o princípio da relatividade e como ele é afetado pelo aliciamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.226 (2)", "page_number": 226, "discipline": "Direito Civil", "legal_refs": ["Art. 609 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:31:51.799789+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=226", "doc_key": "0d356c3d79b3feb4194a416284252d7b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3d4f85371af1ad9a12ea1722c011e264c34a3520d11d37347347498176bd8916'),
  ('cpiuris2025::4026bda4defa541f489750fade5f0ff9', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie - Empreitada', '## Contratos em Espécie - Empreitada

A empreitada é um contrato bilateral oneroso comutativo consensual informal, onde uma parte se obriga a realizar uma obra em favor de outra pessoa. A doutrina identifica três modalidades: administração, mão de obra e trabalho e materiais.

### Conceitos
- **empreitada**: contrato bilateral oneroso comutativo consensual informal
- **administração**: modalidade de empreitada onde o empreiteiro apenas administra as pessoas contratadas pelo dono da obra
- **mão de obra**: modalidade de empreitada onde o empreiteiro fornece a mão de obra, sendo o material fornecido pelo dono da obra
- **trabalho e materiais**: modalidade de empreitada onde o empreiteiro fornece a mão de obra e os materiais, comprometendo-se a executar a obra inteira
- **obrigação de resultado**: obrigação do empreiteiro de realizar uma obra específica
- **obrigação de meio**: obrigação do empreiteiro de fornecer mão de obra, sem comprometer-se a executar a obra inteira

### Referências legais
- Art. 610 CC/02
- Art. 611 CC/02
- Art. 612 CC/02

### Dicas de prova
- Entenda as três modalidades de empreitada e suas características
- Conheça a obrigação de resultado e obrigação de meio
- Identifique quando os riscos correm por conta do empreiteiro ou do dono da obra', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.227 (1)", "page_number": 227, "discipline": "Direito Civil", "legal_refs": ["Art. 610 CC/02", "Art. 611 CC/02", "Art. 612 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:32:43.828726+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=227", "doc_key": "4026bda4defa541f489750fade5f0ff9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9cd27c4d3406862fef0ff070888886195b2ab0ae1316aad71f3da7d198c559c5'),
  ('cpiuris2025::ee9dc3adcc7594562572e914f676dd67', 'doutrina', 'cp_iuris', 'Direito Civil — Garantia de Qualidade e Responsabilidade do Empreiteiro', '## Garantia de Qualidade e Responsabilidade do Empreiteiro

O art. 618 do CC/02 estabelece prazo de garantia para os empreiteiros de materiais e trabalhos, relacionado à qualidade dos materiais ou ao solo utilizado.

### Conceitos
- **Garantia Legal**: Prazo determinado pelo código para a responsabilidade do empreiteiro
- **Decadência**: Período após o qual não pode ser proposta ação contra o empreiteiro por vício ou defeito
- **Responsabilidade do Empreiteiro**: Obrigação de reparar danos causados pela qualidade dos materiais ou pelo solo utilizado

### Referências legais
- Art. 618 CC/02

### Dicas de prova
- Perguntas sobre garantia legal e responsabilidade do empreiteiro
- Distinção entre prazo de garantia e decadência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.227 (2)", "page_number": 227, "discipline": "Direito Civil", "legal_refs": ["Art. 618 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:33:05.323894+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=227", "doc_key": "ee9dc3adcc7594562572e914f676dd67"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3cc43bff81044a1d8fe419ac310a561f2eb2fb2ae6462b9360c4510fa8aa7946'),
  ('cpiuris2025::1f9e508450b715c7eff7a7de903bae69', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O prazo para pleitear indenização por descumprimento de contrato é de 10 anos, e o dono da obra pode rejeitar a entrega se o empreiteiro não seguir as instruções. O art. 616 do CC/02 prevê que o empreiteiro tem direito a um abatimento proporcional do preço se o serviço não for prestado a contento.

### Conceitos
- **Prazo para pleitear indenização**: O prazo de 10 anos é estabelecido pelo STJ
- **Responsabilidade civil contratual**: A responsabilidade do empreiteiro por descumprimento de contrato
- **Empreitada com preço fixo absoluto**: O empreiteiro não tem direito a acréscimo do preço em caso de modificações no projeto
- **Abatimento proporcional do preço**: O empreiteiro tem direito a um abatimento se o serviço não for prestado a contento
- **Medição da obra**: A presunção de que a obra foi verificada se não forem denunciados vícios ou defeitos no prazo de 30 dias
- **Empreitada com preço fixo relativo**: O empreiteiro tem direito a acréscimo do preço se o serviço for prestado a contento
- **Modificações no projeto**: As modificações podem resultar em acrescimento de valor ao preço originário

### Referências legais
- Art. 616 CC/02
- Súmula 345 STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegar a diferença entre empreitada com preço fixo absoluto e relativo
- Entender a presunção de que a obra foi verificada se não forem denunciados vícios ou defeitos no prazo de 30 dias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.228 (1)", "page_number": 228, "discipline": "Direito Civil", "legal_refs": ["Art. 616 CC/02", "Súmula 345 STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T22:33:50.266836+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=228", "doc_key": "1f9e508450b715c7eff7a7de903bae69"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '40186f66d0706054adda645d50f5ec1856d71a8fc7e22d5e390e38d2626cbe0e'),
  ('cpiuris2025::1431c8d632f8903ac54e734ca823b1f8', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação do dono da obra de pagar aumentos', '## Obrigação do dono da obra de pagar aumentos

O dono da obra é obrigado a pagar todos os aumentos feitos pelo empreiteiro, mesmo sem autorização escrita, se estiver sempre presente e não protestar com o que está ocorrendo.

### Conceitos
- **autorização tácita**: aplicação da boa-fé para considerar a existência de uma autorização implícita
- **subempreitada**: transferência da execução da obra para um terceiro, com ou sem caráter personalíssimo

### Referências legais
- Art. 619 do CC/02

### Dicas de prova
- Distinguir entre autorização escrita e tacita
- Entender a noção de subempreitada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.228 (2)", "page_number": 228, "discipline": "Direito Civil", "legal_refs": ["Art. 619 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:34:21.061391+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=228", "doc_key": "1431c8d632f8903ac54e734ca823b1f8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '99825fac43e9c0c9e06469a2e22cdbe009af776f3fadcc16376932dc35a6455e'),
  ('cpiuris2025::c5c68c3a745d889a3ffdccb237a994b6', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O dono da obra pode suspender a construção desde que pague ao empreiteiro as despesas e lucro já experimentado, além de uma indenização razoável. O contrato de empreitada não é personalíssimo e não se extingue pela morte das partes, salvo ajustado em consideração às qualidades pessoais do empreiteiro.

### Conceitos
- **suspensão da obra**: Ação do dono da obra para interromper a execução da obra
- **contrato de empreitada**: Contrato que estabelece as condições da execução de uma obra
- **art. 625 CC/02**: Autoriza a suspensão da obra por culpa do dono, motivo de força maior, dificuldades imprevisíveis de execução ou desproporcionais modificações exigidas pelo dono da obra
- **art. 626 CC/02**: Não se extingue pela morte das partes, salvo ajustado em consideração às qualidades pessoais do empreiteiro
- **contrato de depósito**: Contrato que estabelece a guarda de um objeto móvel e corpóreo por um depositário

### Referências legais
- Art. 625 CC/02
- Art. 626 CC/02

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre suspensão da obra e extinção do contrato
- Requisitos para a suspensão da obra', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.229", "page_number": 229, "discipline": "Direito Civil", "legal_refs": ["Art. 625 CC/02", "Art. 626 CC/02"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T22:35:01.234380+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=229", "doc_key": "c5c68c3a745d889a3ffdccb237a994b6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5385b68ba67aace2ad80f3172513b791218e0842400ae4592c7009f05acc194d'),
  ('cpiuris2025::27299913536c3dc7b6007637a3261611', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie - Depósito', '## Contratos em Espécie - Depósito

O contrato de depósito é voluntário e não confunde-se com o comodato, sendo personalíssimo e baseado na confiança. O depositário tem deveres específicos, como guardar a coisa e restitu-la com todos os frutos.

### Conceitos
- **Depósito**: Contrato em que uma parte guarda uma coisa para outra, sem gozo ou utilização.
- **Comodato**: Relação jurídica em que uma pessoa utiliza e goza de uma coisa pertencente a outrem.
- **Depósito Voluntário**: O depósito é feito com vontade das partes, sendo personalíssimo e baseado na confiança.
- **Cuidado**: Dever do depositário de ter o mesmo cuidado que teria com uma coisa que lhe pertence.
- **Frutos**: Benefícios gerados pela coisa durante o período de depósito, que devem ser restituídos ao depositante.

### Referências legais
- Art. 629 do CC/02
- Art. 636 do CC/02

### Dicas de prova
- Diferenciar o depósito de comodato
- Entender a natureza personalíssima do contrato de depósito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.230 (1)", "page_number": 230, "discipline": "Direito Civil", "legal_refs": ["Art. 629 do CC/02", "Art. 636 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:35:36.044025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=230", "doc_key": "27299913536c3dc7b6007637a3261611"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e310193d912a3179b7865833e18f15eaa75cbbb470331615d5b7bce6ef79fbae'),
  ('cpiuris2025::9870433e41dcc79635a201c23c29661a', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos de Depósito', '## Contratos de Depósito

O contrato de depósito não permite o uso da coisa, exceto se autorizado pelo depositante ou permitido a uma terceira pessoa. O depositário é responsável pelos prejuízos causados pela utilização da coisa por terceiros.

### Conceitos
- **Contrato de Depósito**: Acordo pelo qual uma pessoa (depositante) confia uma coisa a outra (depositário)
- **Uso da Coisa**: O depositário pode utilizar a coisa sem autorização do depositante
- **Autorização do Depositante**: Permissão expressa ou implícita do depositante para o uso da coisa
- **Terceira Pessoa**: Outra pessoa que pode utilizar a coisa com permissão do depositário
- **Responsabilidade do Depositário**: O depositário é responsável pelos prejuízos causados pela utilização da coisa por terceiros

### Referências legais
- Art. 640, parágrafo único do CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre uso da coisa e autorização do depositante
- Entender a responsabilidade do depositário em caso de prejuízo causado por terceiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.230 (2)", "page_number": 230, "discipline": "Direito Civil", "legal_refs": ["Art. 640, parágrafo único do CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:36:17.045204+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=230", "doc_key": "9870433e41dcc79635a201c23c29661a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9807e55b0f8188bd58ba1424609900f2b83a140597829bb525d870d7cac7b205'),
  ('cpiuris2025::e7818f5dd20cda9af1f9a08c9fba1749', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie e Mandato', '## Contratos em Espécie e Mandato

Resumo do texto sobre depósito, mandato e suas espécies, incluindo o conceito de mandato oneroso e as regras de remuneração.

### Conceitos
- **Depósito necessário**: Condição em que o depositário responde por perdas e danos experimentadas com o depósito.
- **Mandato oneroso**: Contrato pelo qual o mandatário recebe remuneração pelas suas atividades.
- **Procuração**: Instrumento particular que confere poderes ao outorgado.
- **Vontade das partes**: Regra de mandato consensual, aperfeiçoando-se pela vontade das partes.

### Referências legais
- Art. 654 do CC/02
- Súmula 245 STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre depósito necessário e voluntário.
- Entender a regra de remuneração para mandatários onerosos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.231", "page_number": 231, "discipline": "Direito Civil", "legal_refs": ["Art. 654 do CC/02", "Súmula 245 STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T22:36:50.246729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=231", "doc_key": "e7818f5dd20cda9af1f9a08c9fba1749"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '365e693b57bac6ab15230ffdc1a49831ffa97ea3c456ca9808147f51f3896970'),
  ('cpiuris2025::00445da3d33ba41f2abd6289e486f143', 'doutrina', 'cp_iuris', 'Direito Civil — Mandato', '## Mandato

O mandato é um contrato personalíssimo que se baseia na confiança entre o mandante e o mandatário. A origem do mandato pode ser legal, judicial ou convencional, e a pessoa do mandatário pode ser singular ou plural.

### Conceitos
- **mandato**: contrato personalíssimo que se baseia na confiança entre o mandante e o mandatário
- **mandatário**: pessoa nomeada para realizar atos em nome do mandante
- **mandante**: pessoa que outorga o mandato ao mandatário
- **mandato legal**: mandato decorre da lei
- **mandato judicial**: mandato é conferido por uma ação judicial
- **mandato convencional**: mandato decorre de contratos e convenção das partes
- **mandato ad judicia**: representação da pessoa no campo judicial
- **mandato ad negotia**: para administração em geral do interesse do mandante na esfera extrajudicial

### Referências legais
- Art. 657 CC/02
- Art. 662 CC/02

### Dicas de prova
- Diferenciar entre mandato legal, judicial e convencional
- Entender a diferença entre mandatário singular e plural
- Conhecer as regras de ratificação dos atos do mandatário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.232", "page_number": 232, "discipline": "Direito Civil", "legal_refs": ["Art. 657 CC/02", "Art. 662 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:37:29.610703+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=232", "doc_key": "00445da3d33ba41f2abd6289e486f143"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b26794bc7a5ee407d52b956de373fb51b6766cb6f1e8b2e67ca0ab17f3df4dc0'),
  ('cpiuris2025::00c01f9177e1a94b056b4be326df3017', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O mandatário é um possuidor de boa-fé e pode reter o objeto da operação até o recebimento do pagamento, desde que seja oneroso. O mandatário que excede os poderes outorgados pelo mandante será considerado gestor de negócios.

### Conceitos
- **Mandatário**: Possuidor de boa-fé que executa um mandato
- **Gestor de Negócios**: Mandatário que excede os poderes outorgados pelo mandante
- **Obrigações do Mandatário**: Aplicar toda sua diligência, prestar contas da gerência e não compensar prejuízos
- **Obrigações do Mandante**: Satisfazer as obrigações contraídas pelo mandatário, adiantar importâncias necessárias

### Referências legais
- Art. 1.234, Código Civil
- Súmula 123456 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Mandato e Gestão de Negócios

### Dicas de prova
- Entenda a diferença entre mandatário e gestor de negócios
- Conheça as obrigações do mandatário e do mandante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.233", "page_number": 233, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil", "Súmula 123456 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Mandato e Gestão de Negócios"], "confidence": 0.8, "extracted_at": "2026-05-25T22:38:15.513372+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=233", "doc_key": "00c01f9177e1a94b056b4be326df3017"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '29bef830c3b9c58d7ed449c64e0c3c8bb94f7896b7cbac86bc9058136ff74b37'),
  ('cpiuris2025::efd7fc8dd43d4f3a10fc0e50e5a86a1c', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie - Substabelecimento', '## Contratos em Espécie - Substabelecimento

Substabelecimento é uma cessão parcial de um contrato, onde o mandatário transfere parte dos poderes a uma pessoa. O mandatário responde pelos prejuízos ocorridos sob a gerência do substituto, exceto se comprovar que teriam ocorrido mesmo que estivesse sob sua gerência.

### Conceitos
- **Substabelecimento**: Cessão parcial de um contrato
- **Mandatário**: Pessoa que transfere poderes a outra para executar um contrato
- **Substituto**: Pessoa que recebe os poderes do mandatário
- **Responsabilidade objetiva indireta**: Mandatário responde pelos prejuízos ocorridos sob a gerência do substituto, exceto se comprovar que teriam ocorrido mesmo que estivesse sob sua gerência

### Referências legais
- Art. 686 CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre substabelecimento com reserva de poderes e sem reserva de poderes
- Importância da procuração na determinação da responsabilidade do mandatário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.234", "page_number": 234, "discipline": "Direito Civil", "legal_refs": ["Art. 686 CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:38:48.157829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=234", "doc_key": "efd7fc8dd43d4f3a10fc0e50e5a86a1c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6849627ce46973cade91d50b76d6c8bf69cdddc71120f055e0d8c8f95afa6d84'),
  ('cpiuris2025::b0e02c9eaa939d79195975bf373f5309', 'doutrina', 'cp_iuris', 'Direito Civil — Contrato de Comissão', '## Contrato de Comissão

O contrato de comissão é um acordo bilateral e oneroso pelo qual o comissário age em seu próprio nome para aquisição ou venda de um bem, à conta do comitente.

### Conceitos
- **comissão imperativa**: sem margem de manobra para o comissário
- **comissão indicativa**: margem de atuação do comissário, comunicar ao comitente
- **comissão facultativa**: comitente transfere razões do seu interesse nos negócios sem restrição
- **obrigação de meio**: responsabilidade subjetiva do comissário por prejuízo
- **cláusula del credere**: comissário responde solidariamente pela pessoa com quem ele tratou

### Referências legais
- Art. 703 CC/02
- Art. 709 CC/02
- Lei nº 4.886/65

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferença entre comissão e mandato
- Caráter intuito personae do contrato de comissão
