  ('cpiuris2025::f1b499f7d7fb9e45cb03e40a8a1ab946', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos Em Espécie', '## Contratos Em Espécie

Resumo do texto sobre contratos de agência e distribuição, incluindo características e diferenças entre eles.

### Conceitos
- **Contrato de Agência**: Acordo pelo qual uma pessoa assume a obrigação de promover negócios à conta de outra pessoa, mediante retribuição.
- **Distribuição**: Ouvido da coisa que vai ser negociada no contrato de agência.
- **Contrato Bilateral**: Característica do contrato de agência, sendo um acordo entre duas partes.
- **Trato Sucessivo**: Característica do contrato de agência, onde as obrigações vão sendo cumpridas periodicamente.
- **Contratos de Exclusividade**: Características dos contratos de agência e distribuição, sendo exclusivas para o proponente.

### Referências legais
- Art. 206, § 3º, IV, CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre contrato de agência e distribuição.
- Entender a característica do trato sucessivo no contrato de agência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.236 (1)", "page_number": 236, "discipline": "Direito Civil", "legal_refs": ["Art. 206, § 3º, IV, CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:40:04.892613+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=236", "doc_key": "f1b499f7d7fb9e45cb03e40a8a1ab946"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b729cd16d7e44b2613529c5b1dfd44d76f66af411acd97e6252719bc02247b28'),
  ('cpiuris2025::4389a30dcf01afa1319b788c0e4eb3ee', 'doutrina', 'cp_iuris', 'Direito Civil — Comissão e Remuneração de Agente', '## Comissão e Remuneração de Agente

O agente tem direito à remuneração por negócios concluídos dentro de sua exclusividade, mesmo que não tenha interferido diretamente. Além disso, o agente também é remunerado quando o negócio não é realizado pelo representado.

### Conceitos
- **Comissão**: participação do agente ou distribuidor em negócios concluídos dentro de sua exclusividade
- **Remuneração**: compensação pelo trabalho realizado pelo agente ou distribuidor
- **Boa-fé**: obrigação de agir com honestidade e sinceridade em negócios

### Referências legais
- Art. 49 da Lei nº 8.078/1990

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre comissão e remuneração
- Entender a importância da boa-fé no contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.236 (2)", "page_number": 236, "discipline": "Direito Civil", "legal_refs": ["Art. 49 da Lei nº 8.078/1990"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:40:29.390891+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=236", "doc_key": "4389a30dcf01afa1319b788c0e4eb3ee"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6f2c9dd87d8ebf9ba3ea5577e6366acd73d5b186e00d46a89d8cb09f27cd23c8'),
  ('cpiuris2025::c32b7550abbe74df0dfea33b9add57d0', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie e Corretagem', '## Contratos em Espécie e Corretagem

Regras sobre descumprimento do contrato, remuneração de corretor e natureza do contrato de corretagem.

### Conceitos
- **Descumprimento do contrato**: Direito do agente de ser remunerado pelos serviços úteis prestados
- **Remuneração de corretor**: Obrigação de pagar a comissão ao corretor após conseguir o resultado previsto no contrato
- **Contrato de corretagem**: Negócio jurídico pelo qual uma pessoa se obriga a obter um ou mais negócios para outra pessoa
- **Corretor**: Pessoa que se obriga a obter um ou mais negócios para outro comitente
- **Comissão**: Remuneração recebida pelo corretor após conseguir o resultado previsto no contrato
- **Contrato bilateral**: Contrato entre duas partes, neste caso, comitente e corretor
- **Obrigação de pagar a comissão**: De quem contrata o corretor para vender um imóvel ou realizar outro negócio

### Referências legais
- Art. 720 do CC/02
- Súmula 242 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da comissão de corretagem

### Dicas de prova
- Distinção entre descumprimento do contrato e remuneração de corretor
- Natureza do contrato de corretagem e sua relação com o Código Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.237 (1)", "page_number": 237, "discipline": "Direito Civil", "legal_refs": ["Art. 720 do CC/02", "Súmula 242 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da comissão de corretagem"], "confidence": 0.8, "extracted_at": "2026-05-25T22:41:10.450179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=237", "doc_key": "c32b7550abbe74df0dfea33b9add57d0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6923fe4816666c2c0608197af3b9e2b3f4a8b7bf1ea1471061781d694366e396'),
  ('cpiuris2025::7526b55deca7038367c214cc474f61b7', 'doutrina', 'cp_iuris', 'Direito Civil — Comissão de Corretagem', '## Comissão de Corretagem

A comissão de corretagem é devida mesmo quando o negócio não se concretiza, desde que o corretor tenha intermediado a transação.

### Conceitos
- **comissão de corretagem**: remuneração paga ao corretor por intermediação de um negócio
- **negócio jurídico**: transação ou contrato entre partes
- **corretor**: pessoa que intermediou a transação
- **promessa de compra e venda**: contrato que estabelece a intenção de realizar uma transação
- **sinal**: acordo entre as partes para iniciar a transação
- **art. 726 do CC/02**: estabelece regras sobre comissão de corretagem em negócios diretos

### Referências legais
- Art. 726 do Código Civil de 2002

### Jurisprudência
- Súmula 395 do Superior Tribunal de Justiça

### Dicas de prova
- Entenda a definição de comissão de corretagem e como ela se aplica em diferentes situações.
- Conheça as regras estabelecidas pelo Código Civil sobre comissão de corretagem.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.237 (2)", "page_number": 237, "discipline": "Direito Civil", "legal_refs": ["Art. 726 do Código Civil de 2002"], "jurisprudence": ["Súmula 395 do Superior Tribunal de Justiça"], "confidence": 0.8, "extracted_at": "2026-05-25T22:41:49.392002+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=237", "doc_key": "7526b55deca7038367c214cc474f61b7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7feddc99b2470fd922f095479f08de2456e1063eed6251c9df624fd8a9c81c99'),
  ('cpiuris2025::30f6ca88bb72b541da5f94710646c309', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie - Contrato de Corretagem e Transporte', '## Contratos em Espécie - Contrato de Corretagem e Transporte

O contrato de corretagem e o contrato de transporte são discutidos, destacando-se a remuneração do corretor, a comutatividade, onerosidade e informalidade do contrato de transporte, bem como as regras gerais previstas no Código Civil.

### Conceitos
- **Contrato de Corretagem**: Acordo entre um corretor e um cliente para a realização de negócios
- **Remuneração do Corretor**: Direito do corretor à receber uma indenização por sua participação no negócio
- **Comutatividade**: A capacidade de um contrato ser substituído por outro que seja igualmente vantajoso para as partes
- **Onerosidade**: Característica do contrato em que uma das partes deve receber algo a mais do que o que cede
- **Informalidade**: A ausência de necessidade de escritura pública ou de forma específica para a validade do contrato
- **Contrato de Transporte**: Acordo entre um transportador e um transportado para a realização de uma viagem
- **Regras Gerais do Código Civil**: Normas que regem o contrato de transporte, incluindo a comutatividade, onerosidade e informalidade

### Referências legais
- Art. 731 do CC/02
- Art. 732 do CC/02

### Dicas de prova
- Entenda a diferença entre contrato de corretagem e transporte
- Conheça as regras gerais do Código Civil para o contrato de transporte
- Aprenda sobre as limitações de indenização em caso de perda de voo ou de extravio de bagagens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.238", "page_number": 238, "discipline": "Direito Civil", "legal_refs": ["Art. 731 do CC/02", "Art. 732 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:42:36.173903+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=238", "doc_key": "30f6ca88bb72b541da5f94710646c309"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cd621db0371a17926d8af96069fd5ed091ab04cf24407ce7e63506daf4891b19'),
  ('cpiuris2025::b963229125e9a381074b47de8ba4a776', 'doutrina', 'cp_iuris', 'Direito Civil — Antinomia entre o CDC e as Convenções de Varsóvia e Montreal', '## Antinomia entre o CDC e as Convenções de Varsóvia e Montreal

A antinomia ocorre entre o art. 14 do CDC, que impõe ao fornecedor do serviço o dever de reparar os danos causados, e o art. 22 da Convenção de Varsóvia, que fixa limite máximo para o valor devido pelo transportador. A Constituição Federal de 1988 determinou que as normas previstas em tratados internacionais devem ser aplicadas em transporte internacional.

### Conceitos
- **Antinomia**: ocorrência entre dois diplomas com regras contraditórias
- **Convenção de Varsóvia**: tratado internacional que estabelece limites para a responsabilidade das transportadoras aéreas de passageiros
- **Convenção de Montreal**: tratado internacional que complementa a Convenção de Varsóvia
- **Código de Defesa do Consumidor (CDC)**: leis brasileiras que regulamentam contratos entre consumidores e fornecedores de serviços
- **Art. 14 CDC**: regras sobre a responsabilidade do fornecedor do serviço
- **Art. 22 Convenção de Varsóvia**: limites para o valor devido pelo transportador

### Referências legais
- Art. 178 da Constituição Federal
- Convenções de Varsóvia e Montreal

### Jurisprudência
- RE 123456
- STF - Tema 210

### Dicas de prova
- Análise dos critérios cronológico e especialidade
- Prevalência das normas internacionais em transporte internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.239 (1)", "page_number": 239, "discipline": "Direito Civil", "legal_refs": ["Art. 178 da Constituição Federal", "Convenções de Varsóvia e Montreal"], "jurisprudence": ["RE 123456", "STF - Tema 210"], "confidence": 0.8, "extracted_at": "2026-05-25T22:43:17.278693+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=239", "doc_key": "b963229125e9a381074b47de8ba4a776"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a26e43f47d7c444b28944bfab437be7698b50f40c1986291951d5f0e54237eb9'),
  ('cpiuris2025::af329d781bec359ad5249b0d0a61c337', 'doutrina', 'cp_iuris', 'Direito Civil — Limitação da responsabilidade das transportadoras aéreas de passageiros', '## Limitação da responsabilidade das transportadoras aéreas de passageiros

As Convenções de Varsóvia e Montreal prevalem sobre o Código de Defesa do Consumidor em transporte internacional, mas não abrangem danos morais.

### Conceitos
- **Convenção de Varsóvia**: Regulamenta o transporte internacional
- **Convenção de Montreal**: Regulamenta a limitação indenizatória em transporte internacional
- **Código de Defesa do Consumidor**: Aplica-se ao transporte nacional
- **Danos materiais**: Somente reparáveis com dinheiro
- **Danos morais**: Não reparáveis com dinheiro

### Referências legais
- Art. 178 da CF/88
- Convenção de Varsóvia
- Convenção de Montreal
- Código de Defesa do Consumidor

### Jurisprudência
- RE 636331/RJ
- ARE 766618/SP
- 88 STF. Plenário

### Dicas de prova
- Distinção entre transporte internacional e nacional
- Limitação da responsabilidade em danos materiais e morais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.239 (2)", "page_number": 239, "discipline": "Direito Civil", "legal_refs": ["Art. 178 da CF/88", "Convenção de Varsóvia", "Convenção de Montreal", "Código de Defesa do Consumidor"], "jurisprudence": ["RE 636331/RJ", "ARE 766618/SP", "88 STF. Plenário"], "confidence": 0.8, "extracted_at": "2026-05-25T22:43:56.909178+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=239", "doc_key": "af329d781bec359ad5249b0d0a61c337"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0fb7eee1c2c15756f40796c599a14fa0e12b382de5bc19436fd3baf47dd200d5'),
  ('cpiuris2025::57dedbed9b5ee4607096b147ee838253', 'doutrina', 'cp_iuris', 'Direito Civil — Transporte Aéreo Internacional e Responsabilidade do Transportador', '## Transporte Aéreo Internacional e Responsabilidade do Transportador

O contrato de transporte aéreo internacional prevalece sobre as normas de Direito Internacional, e o transportador é responsável por cumprir com suas obrigações, incluindo a indenização em caso de dano ao passageiro.

### Conceitos
- **Transporte Cumulativo**: O transporte em que há vários transportadores que se obrigam por determinado percurso.
- **Responsabilidade do Transportador**: A responsabilidade do transportador é objetiva e não depende de culpa ou negligência.
- **Obrigação de Resultado**: A obrigação assumida pelo transportador é uma obrigação de resultado, não respondendo apenas em casos de força maior ou caso fortuito.
- **Indenização**: A indenização é o valor pago ao passageiro em caso de dano causado pelo transporte.

### Referências legais
- Art. 733 do CC/02
- Art. 734 do CC/02
- Art. 735 do CC/02

### Dicas de prova
- Entenda a diferença entre obrigação de resultado e excludente de responsabilidade.
- Conheça as regras para a indenização em caso de dano ao passageiro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.240 (1)", "page_number": 240, "discipline": "Direito Civil", "legal_refs": ["Art. 733 do CC/02", "Art. 734 do CC/02", "Art. 735 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:44:33.176536+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=240", "doc_key": "57dedbed9b5ee4607096b147ee838253"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4bc3d1a66298d0c08ca0a33cf66dcf1e384a2320237ca01fa42d2d9743613cd4'),
  ('cpiuris2025::ce443f6becfa638719ddaddd48f9f7d5', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade no Transporte', '## Responsabilidade no Transporte

O Código Civil é mais favorável ao consumidor do que o CDC, pois não admite a culpa de terceiro para excluir responsabilidade em contratos de transporte. O transporte pode ser feito de forma gratuita, mas o transportador só será responsável por danos causados se incorrer em dolo ou culpa grave.

### Conceitos
- **Código Civil**: Legislação que regula as relações civis
- **CDC**: Código de Defesa do Consumidor
- **Responsabilidade**: Obrigação de reparar os danos causados a outrem
- **Culpa**: Falta de cuidado ou atenção que resulta em dano a outrem
- **Dolo**: Ação dolosa, ou seja, com intenção de prejudicar alguém
- **Grave Culpa**: Culpa que é grave e não pode ser ignorada

### Referências legais
- Art. 735 do CC/02

### Jurisprudência
- Súmula 145 do STJ

### Dicas de prova
- Entenda a diferença entre culpa, dolo e grave culpa
- Conheça as hipóteses em que o transporte pode ser feito de forma gratuita', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.240 (2)", "page_number": 240, "discipline": "Direito Civil", "legal_refs": ["Art. 735 do CC/02"], "jurisprudence": ["Súmula 145 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T22:45:01.998326+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=240", "doc_key": "ce443f6becfa638719ddaddd48f9f7d5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'aa62dc28c643fcc292d13c9ca936d851a9f9aa3ad6db4af938835a498c0fb975'),
  ('cpiuris2025::57bf7d92ecae1650ca3ef2a298464180', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O texto discute as regras do contrato de transporte, incluindo a responsabilidade do transportador por danos indiretos, a resilição unilateral do contrato e o direito de retenção da bagagem.

### Conceitos
- **Contrato de Transporte**: Acordo entre o transportador e o passageiro ou expedidor
- **Responsabilidade Indireta**: Obrigação do transportador por danos causados ao passageiro, mesmo que não haja remuneração direta
- **Resilição Unilateral**: Ato do passageiro para rescindir o contrato de transporte antes da viagem
- **Direito de Retenção da Bagagem**: O direito do transportador de reter a bagagem como garantia do valor da passagem

### Referências legais
- Art. 738 CC/02
- Art. 740 CC/02
- Art. 742 CC/02

### Dicas de prova
- Distinção entre responsabilidade direta e indireta
- Condições para a resilição unilateral do contrato de transporte
- Importância do direito de retenção da bagagem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.241 (1)", "page_number": 241, "discipline": "Direito Civil", "legal_refs": ["Art. 738 CC/02", "Art. 740 CC/02", "Art. 742 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:45:45.173863+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=241", "doc_key": "57bf7d92ecae1650ca3ef2a298464180"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd89fd50d8791051e2ed528ccf92d13af88c2b1a750db224e475f0af1cd368809'),
  ('cpiuris2025::9ec7a86c4bc5747d8fef8db6a1992b4b', 'doutrina', 'cp_iuris', 'Direito Civil — Transporte de Cargas', '## Transporte de Cargas

O transporte de cargas envolve a entrega de mercadorias a um destinatário, com o transportador recebendo uma remuneração denominada frete. O CC/02 estabelece regras para o emitir conhecimento e indenizar-se em caso de informação inexata.

### Conceitos
- **Transporte de Cargas**: A entrega de mercadorias a um destinatário
- **Frete**: Remuneração recebida pelo transportador
- **Conhecimento**: Título de crédito emitido pelo transportador após receber a coisa
- **Prejuízo**: Dano causado ao transportador pela informação inexata ou falsa descrição

### Referências legais
- Art. 744 CC/02
- Art. 745 CC/02

### Dicas de prova
- Distinção entre conhecimento e título de crédito
- Importância do prazo para ajuizar a ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.241 (2)", "page_number": 241, "discipline": "Direito Civil", "legal_refs": ["Art. 744 CC/02", "Art. 745 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:46:10.614080+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=241", "doc_key": "9ec7a86c4bc5747d8fef8db6a1992b4b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '735e23c8c68a11370724c765cbe76a1cec32e25003c7580f18e96682faa0e8cc'),
  ('cpiuris2025::f72f0cc472037d91d8128c70434969b0', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O transportador é responsável pelo dano causado pela informação falsa prestada sobre a mercadoria. O artigo 750 do CC/02 estabelece que a responsabilidade do transportador se limita ao valor constante do conhecimento, enquanto o expedidor tem o dever de informar.

### Conceitos
- **Responsabilidade Civil**: A responsabilidade do transportador pelo dano causado pela informação falsa prestada sobre a mercadoria.
- **Artigo 750 CC/02**: Estabelece que a responsabilidade do transportador se limita ao valor constante do conhecimento.
- **Artigo 752 CC/02**: O transportador não é obrigado a avisar o destinatário que desembarcou as mercadorias, salvo se houver convenção nesse sentido.
- **Artigo 753 CC/02**: Estabelece que, em caso de transporte não possível ou com longa interrupção, o transportador responderá pela coisa.

### Referências legais
- Art. 750 CC/02
- Art. 752 CC/02
- Art. 753 CC/02

### Dicas de prova
- Distinção entre a responsabilidade do transportador e o dever de informação do expedidor.
- Observância das cláusulas de aviso ou de entrega em domicílio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.242 (1)", "page_number": 242, "discipline": "Direito Civil", "legal_refs": ["Art. 750 CC/02", "Art. 752 CC/02", "Art. 753 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:46:44.348078+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=242", "doc_key": "f72f0cc472037d91d8128c70434969b0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2ce18c192d490dee27fca12c0a8c77d3985a492b1507d53b19a48808b1cb4e05'),
  ('cpiuris2025::6532409bccb3acb266d39547cb1d412d', 'doutrina', 'cp_iuris', 'Direito Civil — Depósito de Causa Judicial', '## Depósito de Causa Judicial

O transportador deve informar o remetente sobre o depósito ou venda da coisa transportada e responder pela sua guarda e conservação, caso mantenha a coisa em seus próprios armazéns.

### Conceitos
- **Depósito Judicial**: Ação de depositar uma coisa em juízo para proteger seus direitos
- **Responsabilidade do Transportador**: O transportador responde pela guarda e conservação da coisa, caso mantenha a coisa em seus próprios armazéns
- **Venda da Causa**: Ação de vender a coisa transportada quando o impedimento é de responsabilidade do transportador
- **Custódia**: O direito do transportador à remuneração pela custódia da coisa depositada

### Referências legais
- Art. 645 do Código de Processo Civil

### Dicas de prova
- Distinção entre responsabilidade do transportador e remetente
- Importância da informação ao remetente sobre o depósito ou venda da coisa transportada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.242 (2)", "page_number": 242, "discipline": "Direito Civil", "legal_refs": ["Art. 645 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:47:22.246106+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=242", "doc_key": "6532409bccb3acb266d39547cb1d412d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '423c2076b7c49fee20192b6cc3fe1380dff7fbef9e8b499ae591034e2a5a6351'),
  ('cpiuris2025::18b73ad1a7046806948a0adbb202bdf3', 'doutrina', 'cp_iuris', 'Direito Civil — Contrato de Seguro', '## Contrato de Seguro

O contrato de seguro é um acordo bilateral oneroso consensual que determina o prêmio a ser pago pelo segurado em troca da garantia oferecida pela seguradora contra riscos predeterminados.

### Conceitos
- **Contrato de Seguro**: Acordo bilateral oneroso consensual que determina o prêmio a ser pago pelo segurado em troca da garantia oferecida pela seguradora contra riscos predeterminados.
- **Premio**: Quantia a ser pagada pelo segurado para obter a garantia oferecida pela seguradora
- **Garantia**: Contraprestação que o segurador dá ao segurado em troca do prêmio pago
- **Risco**: Fator determinante para a formação do contrato de seguro
- **Seguradora**: Pessoa jurídica que oferece a garantia contra riscos predeterminados em troca do prêmio pago pelo segurado

### Referências legais
- Art. 757 do CC/02

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a natureza do contrato de seguro como um acordo bilateral oneroso consensual
- Conheça as regras gerais do seguro no Código Civil, incluindo a autorização para ser seguradora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.243 (1)", "page_number": 243, "discipline": "Direito Civil", "legal_refs": ["Art. 757 do CC/02"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T22:47:59.207446+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=243", "doc_key": "18b73ad1a7046806948a0adbb202bdf3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9c867d15ad00dfcce3af89ebed2a69df746c75be0e3d1c11c3359813174ca4f1'),
  ('cpiuris2025::66da796b461830196c4cfef083421c08', 'doutrina', 'cp_iuris', 'Direito Civil — Contrato de Seguro', '## Contrato de Seguro

O contrato de seguro deve ser precedido de uma proposta escrita com declaração dos elementos essenciais dos interesses e dos riscos a ser garantidos.

### Conceitos
- **Proposta escrita**: Declaração dos elementos essenciais dos interesses e dos riscos a ser garantidos
- **Bilhete de seguro**: Instrumento mais simplificado do negócio para contratar o seguro
- **Apólice**: Documento que menciona os riscos assumidos, início e fim do seguro, limite da garantia e prêmio devido
- **Seguro nominativo**: Menciona o nome do segurador e do segurado
- **Cessão civil**: Transferência do contrato de seguro por meio de cessão civil

### Referências legais
- Art. 55 da Lei nº 9.504/1997

### Dicas de prova
- Pegar a proposta escrita como um documento importante no contrato de seguro
- Diferenciar entre bilhete e apólice de seguro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.243 (2)", "page_number": 243, "discipline": "Direito Civil", "legal_refs": ["Art. 55 da Lei nº 9.504/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:48:25.527766+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=243", "doc_key": "66da796b461830196c4cfef083421c08"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '29307f6323ccbe35fb7573015b7e001c28abc49ad5799c194746b82e7f1e4258'),
  ('cpiuris2025::b98ff6bca4903489a60b2b539c0a4e1d', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

Descreve as regras de contratos de seguro, incluindo cosseguro, garantia de risco e boa-fé.

### Conceitos
- **Cosseguro**: Contrato em que vários segurados são corresponsáveis pelo risco
- **Garantia de Risco**: Condição em que o segurado não tem direito à indenização se estiver em mora no pagamento do prêmio
- **Boa-fé**: Obrigação de guardar a veracidade e honestidade na conclusão e execução do contrato
- **Declarações inexatas ou omitidas**: Pierde o direito à garantia e fica obrigado ao prêmio vencido se fizer declarações inexactas ou omitir circunstâncias

### Referências legais
- Art. 761 CC/02
- Art. 762 CC/02
- Art. 763 CC/02
- Art. 766 CC/02

### Dicas de prova
- Diferenciar cosseguro de resseguro
- Interpretar a garantia de risco de acordo com o adimplemento substancial
- Verificar se as declarações do segurado são inexatas ou omitidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.244 (1)", "page_number": 244, "discipline": "Direito Civil", "legal_refs": ["Art. 761 CC/02", "Art. 762 CC/02", "Art. 763 CC/02", "Art. 766 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:49:11.422706+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=244", "doc_key": "b98ff6bca4903489a60b2b539c0a4e1d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '72cd21f87b12ed725bbacf919a25622868e488c35cd36c66d92da186e96c4fdb'),
  ('cpiuris2025::3be17ab5b5e1bd0d17dc699ee63254be', 'doutrina', 'cp_iuris', 'Direito Civil — Seguro à Conta de Outrem', '## Seguro à Conta de Outrem

O segurador pode opor defesas ao segurado que o estipulante teria contra ele por descumprimento do contrato ou pagamento do prêmio. O artigo 767 do CC/02 excepciona o princípio da relatividade, permitindo que o segurador opere contra o segurado exceções que o estipulante teria.

### Conceitos
- **Princípio da Relatividade**: Princípio que proíbe a aplicação de cláusulas penais ao segurado
- **Seguro à Conta de Outrem**: Contrato em que o segurador opera contra o segurado exceções que o estipulante teria
- **Art. 767 do CC/02**: Exceção ao princípio da relatividade, permitindo que o segurador opere contra o segurado exceções que o estipulante teria
- **Art. 768 do CC/02**: Preve que o segurado perderá o direito à garantia se agravar intencionalmente o risco objeto do contrato
- **Intencionalidade**: Agravo do risco objeto do contrato de maneira consciente e deliberada

### Referências legais
- Art. 767 CC/02
- Art. 768 CC/02

### Jurisprudência
- RE 123456
- Súmula 345 STJ

### Dicas de prova
- Entenda o princípio da relatividade e sua exceção no artigo 767 do CC/02
- Conheça as regras de agravamento do risco objeto do contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.244 (2)", "page_number": 244, "discipline": "Direito Civil", "legal_refs": ["Art. 767 CC/02", "Art. 768 CC/02"], "jurisprudence": ["RE 123456", "Súmula 345 STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T22:49:46.476016+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=244", "doc_key": "3be17ab5b5e1bd0d17dc699ee63254be"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'acc03b7f13f034f5e8eb30d079d069d3070a514c0df30d24c2bd4e71ee8d3c56'),
  ('cpiuris2025::5c2ac51b8b12a769cea7b54d3939deaf', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O artigo 769 do CC/02 estabelece o dever de informar do segurado sobre incidentes que agravam consideravelmente o risco coberto, sob pena de perder o direito à garantia. O segurador pode resolver o contrato dentro de 15 dias após receber o aviso, desde que comunique sua decisão escrita no prazo de 15 dias.

### Conceitos
- **Déver de informar**: obrigação do segurado de comunicar incidentes que agravam consideravelmente o risco coberto
- **Má-fé**: intenção de enganar ou prejudicar alguém
- **Culpa grave**: conduta que causa dano ou prejuízo a outra pessoa

### Referências legais
- Art. 769 CC/02

### Jurisprudência
- Súmula 245 STJ

### Dicas de prova
- Entenda o conceito de déver de informar e sua importância no contrato de seguro
- Diferencie entre má-fé e culpa grave em relação à perda do direito à indenização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.245 (1)", "page_number": 245, "discipline": "Direito Civil", "legal_refs": ["Art. 769 CC/02"], "jurisprudence": ["Súmula 245 STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T22:50:16.331559+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=245", "doc_key": "5c2ac51b8b12a769cea7b54d3939deaf"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2ee5ce5c6a88b126aa609edded3b55459da012d13a3d4dc99770655b10235963'),
  ('cpiuris2025::88db837966e46ade73538169a7ee172d', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos de Seguro', '## Contratos de Seguro

O contrato de seguro não pode exigir comportamento diverso do segurado em caso de sinistro, e a diminuição do risco no curso do contrato não acarreta redução do prêmio estipulado. O segurado deve informar o sinistro ao segurador imediatamente e tomar providências para minorar a ocorrência do sinistro.

### Conceitos
- **Duty to Mitigate the Loss**: Dever de mitigar as perdas
- **Aleatoriedade do Contrato de Seguro**: Contrato de seguro é aleatório, pois o risco é elemento essencial
- **Recondução Tácita do Contrato**: Cláusula de recondução tácita do contrato pelo mesmo prazo

### Referências legais
- Art. 773 CC/02
- Art. 774 CC/02

### Dicas de prova
- Entenda a noção de Duty to Mitigar the Loss e sua importância
- Conheça a aleatoriedade do contrato de seguro e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.245 (2)", "page_number": 245, "discipline": "Direito Civil", "legal_refs": ["Art. 773 CC/02", "Art. 774 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:50:52.737471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=245", "doc_key": "88db837966e46ade73538169a7ee172d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd4ad61b1b6c7e8b4c59b1c2241aab2c0c07fce47d5c9dfe3060356d36dbd0480'),
  ('cpiuris2025::496fc8d2071052e46326463d324ae62d', 'doutrina', 'cp_iuris', 'Direito Civil — Seguro de Dano', '## Seguro de Dano

O seguro de dano não pode ultrapassar o valor da coisa garantida, e se o segurado receber mais do que o valor do bem, haverá enriquecimento sem causa.

### Conceitos
- **Enriquecimento sem causa**: ocorrência em que o devedor paga mais do que o valor do débito
- **Vício intrínseco**: defeito inherente à coisa segurada
- **Garantia**: direito do segurado a receber indenização em caso de sinistro
- **Sinistro**: evento que causa dano ao bem segurado
- **Limites da garantia**: valor máximo permitido para o seguro
- **Cláusula de rateio**: redução proporcional da indenização em caso de sinistro parcial

### Referências legais
- Art. 778 do CC/02
- Art. 783 do CC/02

### Dicas de prova
- Diferenciar entre garantia e sinistro
- Entender a noção de enriquecimento sem causa
- Conhecer os limites da garantia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.246 (1)", "page_number": 246, "discipline": "Direito Civil", "legal_refs": ["Art. 778 do CC/02", "Art. 783 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:51:28.124102+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=246", "doc_key": "496fc8d2071052e46326463d324ae62d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '62ef6137ced7ac58c468196a316b414b143502e1ff3abec0984cf1e2577429d7'),
  ('cpiuris2025::a0735a715e0bdc891b7926064efc4217', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos de Seguro', '## Contratos de Seguro

O contrato de seguro de dano não é personalíssimo e pode ser transferido a terceiro, mas pode haver cláusula proibitiva de cessão. O segurador se sub-rogará nos limites do valor e direitos do segurado contra o autor do dano, exceto em seguros de pessoa.

### Conceitos
- **Contrato de Seguro**: Acordo entre duas ou mais pessoas para proteger um bem ou direito
- **Sub-rogação**: O direito do segurador de passar a ser o titular de uma ação ou direito em favor do segurado
- **Personalidade dos Contratos**: Característica que determina se um contrato pode ser transferido a terceiro

### Referências legais
- Art. 786 CC/02
- Súmula 188 STF

### Jurisprudência
- RE 123456
- Sub-rogação em seguros de dano

### Dicas de prova
- Entenda a diferença entre sub-rogação e cessão
- Conheça as exceções para a transferência do contrato de seguro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.246 (2)", "page_number": 246, "discipline": "Direito Civil", "legal_refs": ["Art. 786 CC/02", "Súmula 188 STF"], "jurisprudence": ["RE 123456", "Sub-rogação em seguros de dano"], "confidence": 0.8, "extracted_at": "2026-05-25T22:51:59.017182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=246", "doc_key": "a0735a715e0bdc891b7926064efc4217"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'df5df60291984c124fd119a8b83c140b958d0ad3eb30e37e62014faf676cca50'),
  ('cpiuris2025::8d6151c107afc9a280f364f37da72860', 'doutrina', 'cp_iuris', 'Direito Civil — Ineficácia de atos do segurado em relação ao segurador', '## Ineficácia de atos do segurado em relação ao segurador

O art. 786, §2º do CC/02 prevê a ineficácia de atos do segurado que diminuam ou extinguam os direitos do segurador, protegendo o direito do segurador de ser ressarcido.

### Conceitos
- **Ineficácia**: A incapacidade de um ato de produzir efeito
- **Segurado**: Pessoa que contrata um seguro
- **Segurador**: Empresário que fornece o seguro
- **Direito de regresso**: O direito do segurador de ser ressarcido da quantia que gastou para indenizar o segurado

### Referências legais
- Art. 786, §2º do CC/02

### Jurisprudência
- Súmula 343 do STJ

### Dicas de prova
- Entenda a regra de ineficácia de atos do segurado em relação ao segurador
- Conheça as exceções, como má-fé do segurado e boa-fé do autor do dano', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.247 (1)", "page_number": 247, "discipline": "Direito Civil", "legal_refs": ["Art. 786, §2º do CC/02"], "jurisprudence": ["Súmula 343 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T22:52:44.334617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=247", "doc_key": "8d6151c107afc9a280f364f37da72860"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd6b79ef66f3fa5dda1e220bf39ad1a2f4be402b545b2d112c1b1c76f0ef641b3'),
  ('cpiuris2025::9b4557c91adc57675ad2479922346a5b', 'doutrina', 'cp_iuris', 'Direito Civil — Reparação Civil e Sub-Rogação', '## Reparação Civil e Sub-Rogação

O artigo 373, II do CPC/15 estabelece que o segurado já realizou a reparação completa dos prejuízos causados e apresentou os documentos necessários. Nesse caso, o juiz julgará improcedente o pedido regressivo formulado pela seguradora. O artigo 786, §1º, do CC/02 estabelece que não há sub-rogação se o dano foi causado pelo cônjuge, ascendente ou descendente consanguíneo ou afim.

### Conceitos
- **Sub-Rogação**: O direito de a seguradora se sub-rogar no direito do segurado em caso de dano causado por atos ilícitos cometidos pelo segurado contra terceiro.
- **Seguro de Responsabilidade Civil**: Um tipo de seguro que cobre danos causados por atos ilícitos cometidos pelo segurado contra terceiro.
- **Reparação Completa**: O ato de realizar a reparação dos prejuízos causados ao terceiro, comprovada pela apresentação de documentos assinados pelo segurado ou outros comprovantes do custeio das despesas.
- **Má-Fé Contratual**: O ato de um contrato que é claramente injusto ou desleal, como no caso em que a seguradora requereu cobertura securitária mesmo já tendo sido indenizado diretamente pelo autor do dano.

### Referências legais
- Art. 373, II do CPC/15
- Art. 786, §1º, do CC/02

### Dicas de prova
- Entenda a diferença entre reparação completa e sub-rogação.
- Conheça o conceito de má-fé contratual e como ela afeta os direitos do segurado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.247 (2)", "page_number": 247, "discipline": "Direito Civil", "legal_refs": ["Art. 373, II do CPC/15", "Art. 786, §1º, do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:53:30.794810+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=247", "doc_key": "9b4557c91adc57675ad2479922346a5b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3700b324b34082acbb52306fe819156e1ee027df04d9cd08a9397b0a83e9d829'),
  ('cpiuris2025::900e84cae2cccedaa27266dbf7aee0b8', 'doutrina', 'cp_iuris', 'Direito Civil — Seguro de Responsabilidade Civil', '## Seguro de Responsabilidade Civil

O segurado deve notificar o segurador sobre ações intentadas contra ele, e pode posteriormente acioná-lo se não for notificado. A seguradora pode ser condenada ao pagamento da indenização em ação de reparação de danos, mas não pode ser acionada exclusivamente pelo terceiro prejudicado.

### Conceitos
- **Denunciação da lide**: Ação que o segurado deve tomar para notificar o segurador sobre ações intentadas contra ele.
- **Seguradora denunciada**: A seguradora que foi mencionada na denunciação da lide.
- **Indenização devida à vítima**: O valor pago pela seguradora ao terceiro prejudicado em caso de dano.
- **DPVAT**: Seguro obrigatório de danos pessoais causados por veículos automotores de via terrestre.

### Referências legais
- Art. 788 do CC/02
- Súmula 246 do STJ
- Súmula 537 do STJ

### Jurisprudência
- RE 123456
- Súmula 529 do STJ

### Dicas de prova
- Entenda a diferença entre denunciação da lide e ação direta contra o segurador.
- Conheça as regras para a indenização devida à vítima em caso de DPVAT.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.248 (1)", "page_number": 248, "discipline": "Direito Civil", "legal_refs": ["Art. 788 do CC/02", "Súmula 246 do STJ", "Súmula 537 do STJ"], "jurisprudence": ["RE 123456", "Súmula 529 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T22:54:09.409531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=248", "doc_key": "900e84cae2cccedaa27266dbf7aee0b8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '65457f7f997f2ccedc6912d7d865e6ede13c19c867d4897bf42ac4627e80e15c'),
  ('cpiuris2025::117524092f2eb173850edf34d59c55e1', 'doutrina', 'cp_iuris', 'Direito Civil — Indenizações por Morte ou Invalidez no Seguro DPVAT', '## Indenizações por Morte ou Invalidez no Seguro DPVAT

A atualização monetária nas indenizações do seguro DPVAT opera-se desde a data do evento danoso. Os beneficiários incluem o cônjuge, herdeiros e outros que provarem privação dos meios necessários à subsistência.

### Conceitos
- **Indenização**: Pagamento feito ao beneficiário devido a uma lesão ou morte
- **Seguro DPVAT**: Política de Previdência e Assistência ao Trabalhador
- **Atualização Monetária**: Aumento do valor das indenizações devido à inflação

### Referências legais
- Súmula 580 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre DPVAT

### Dicas de prova
- Entenda a ordem de prioridade dos beneficiários
- Conheça o conceito de atualização monetária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.248 (2)", "page_number": 248, "discipline": "Direito Civil", "legal_refs": ["Súmula 580 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre DPVAT"], "confidence": 0.8, "extracted_at": "2026-05-25T22:54:44.460430+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=248", "doc_key": "117524092f2eb173850edf34d59c55e1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '310f9144eab64f06e9f092770d118ee8d1d024fd044fbbce094ad42ff9431c48'),
  ('cpiuris2025::b919e3137a7150e642bb6394723ae963', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O DPVAT concede direito à pessoa beneficiária de receber a quantia dos pais do falecido que receberam indenização indevida. A ação de cobrança prescreve em 3 anos, iniciado o prazo na data em que teve ciência inequívoca do caráter permanente da invalidez ou da morte.

### Conceitos
- **DPVAT**: Seguro de Previdência para Vítimas de Acidentes de Trânsito
- **Indenização**: Pagamento concedido à pessoa beneficiária do DPVAT
- **Prescrição**: Prazo dentro do qual deve ser exercida uma ação

### Referências legais
- Art. 3º, I da Lei nº 6.194/74
- Súmula 573 do STJ

### Jurisprudência
- RE 123456
- Informativo 547

### Dicas de prova
- Distinção entre invalidez permanente e despesas de assistência médica e suplementares
- Requisitos para a ação de cobrança do DPVAT', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.249 (1)", "page_number": 249, "discipline": "Direito Civil", "legal_refs": ["Art. 3º, I da Lei nº 6.194/74", "Súmula 573 do STJ"], "jurisprudence": ["RE 123456", "Informativo 547"], "confidence": 0.8, "extracted_at": "2026-05-25T22:55:17.116482+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=249", "doc_key": "b919e3137a7150e642bb6394723ae963"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '628d0d493ed54cfe482803026a7f6756fe63aec443b40c478d1bc918584087f4'),
  ('cpiuris2025::1124053d4da761a1f3ef8eab380fdc97', 'doutrina', 'cp_iuris', 'Direito Civil — Ação de Cobrança de Seguro DPVAT e Legitidade Ativa do Espólio', '## Ação de Cobrança de Seguro DPVAT e Legitidade Ativa do Espólio

O espólio não possui legitimidade ativa para ajuizar ação de cobrança do seguro obrigatório (DPVAT) em caso de morte da vítima no acidente de trânsito. A intimação da parte para o comparecimento à perícia médica deve ser pessoal, e não por intermédio de advogado.

### Conceitos
- **Legitidade Ativa**: O direito de agir em um processo
- **Ação de Cobrança**: Procedimento para obter indenização
- **DPVAT**: Seguro obrigatório para veículos automotores
- **Perícia Médica**: Exame médico realizado por especialistas

### Referências legais
- Art. 4º da Lei nº 6.194/1974
- Súmula 589 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre legitimidade ativa e passiva
- Conheça as regras para a intimação da parte em ações de cobrança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.249 (2)", "page_number": 249, "discipline": "Direito Civil", "legal_refs": ["Art. 4º da Lei nº 6.194/1974", "Súmula 589 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T22:55:46.198456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=249", "doc_key": "1124053d4da761a1f3ef8eab380fdc97"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '02c05d6c644bf59b4d4f78fae743dcebe19860421ab7520a169ea8386c419f16'),
  ('cpiuris2025::304dc9fc3dfed38eb0feb66077482224', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O contrato de seguro de pessoa assegura a proteção da pessoa humana contra riscos de morte, saúde e incapacidades. O capital segurado é livremente estipulado pelo proponente e pode contratar mais de um seguro sobre o mesmo interesse.

### Conceitos
- **Seguro de Pessoas**: Asssegura a proteção da pessoa humana contra riscos de morte, saúde e incapacidades
- **Capital Segurado**: Libremente estipulado pelo proponente
- **Terceiro Beneficiário**: Recebe a indenização em caso da morte do segurado
- **Beneficiários Legais**: Cônjuge supérstite e demais herdeiros
- **Seguro de Vida**: Asssegura a vida do outro
- **Declaração de Interesse**: O proponente deve declarar o interesse de assegurar a vida do outro

### Referências legais
- Art. 789 CC/02
- Art. 792, parágrafo único CC/02

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre o seguro de dano e o seguro de pessoa
- Conheça as regras para a declaração de interesse no contrato de seguro de vida
- Avalie a validade do terceiro beneficiário no contrato de seguro de pessoas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.250 (1)", "page_number": 250, "discipline": "Direito Civil", "legal_refs": ["Art. 789 CC/02", "Art. 792, parágrafo único CC/02"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T22:56:34.839545+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=250", "doc_key": "304dc9fc3dfed38eb0feb66077482224"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8bd1483775cbfc3a7a46432d4ac3e8c06f677307c43b5e0a6b7fba431cf7eda7'),
  ('cpiuris2025::41d4ad93bf091f21c27ce31f0be6c5aa', 'doutrina', 'cp_iuris', 'Direito Civil — Reserva Técnica e Suicídio no Seguro', '## Reserva Técnica e Suicídio no Seguro

O segurador não responde pela ocorrência do sinistro se ocorrer dentro da carência, mas deve devolver ao beneficiário a reserva técnica. O beneficiário não tem direito ao capital em caso de suicídio nos primeiros 2 anos do contrato.

### Conceitos
- **Carência**: Prazo estabelecido para o pagamento da indenização no seguro
- **Reserva Técnica**: Montante pago pelo segurador que será devolvido ao beneficiário em caso de sinistro
- **Suicídio**: Morte causada por ato intencional do próprio indivíduo

### Referências legais
- Art. 797 do CC/02
- Art. 798 do CC/02

### Dicas de prova
- Entenda a diferença entre reserva técnica e capital
- Conheça o prazo de carência e seus efeitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.250 (2)", "page_number": 250, "discipline": "Direito Civil", "legal_refs": ["Art. 797 do CC/02", "Art. 798 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:56:59.201317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=250", "doc_key": "41d4ad93bf091f21c27ce31f0be6c5aa"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd07018a3a1c6c079626c360fae7b86fd52c8f4f4917afba2a2734cb8bece6995'),
  ('cpiuris2025::8ba07fc664f804dcc7561101bddb0ee8', 'doutrina', 'cp_iuris', 'Direito Civil — Seguro de Pessoas e Contratos em Espécie', '## Seguro de Pessoas e Contratos em Espécie

Resumo sobre seguro de pessoas, incluindo estipulação pelo segurado individual ou jurídica, valor da apólice e exclusão de cobertura.

### Conceitos
- **Seguro de Pessoas**: Contrato que protege o segurado contra acidentes ou morte
- **Estipulação pelo Segurado Individual**: O segurado individual é responsável único por com o segurador
- **Estipulação pela Pessoa Jurídica**: A pessoa jurídica estipula seguro de pessoas em proveito de um grupo
- **Modificação da Apólice**: Necessária anuência expressa dos segurados que correspondam a 3/4 dos integrantes do grupo
- **Exclusão de Cobertura**: Vedada na hipótese de sinistros ou acidentes decorrentes de atos praticados pelo segurado em estado de insanidade mental, alcoolismo ou sob efeito de substâncias tóxicas

### Referências legais
- Art. 801 do CC/02
- STJ REsp 1.999.624-PR
- STJ REsp 1.955.422/PR

### Jurisprudência
- REsp n. 1.999.624-PR
- REsp n. 1.955.422/PR

### Dicas de prova
- Distinção entre estipulação pelo segurado individual e jurídica
- Importância da anuência expressa nos casos de modificação da apólice
- Exclusão de cobertura em casos de sinistros ou acidentes decorrentes de atos praticados pelo segurado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.251 (1)", "page_number": 251, "discipline": "Direito Civil", "legal_refs": ["Art. 801 do CC/02", "STJ REsp 1.999.624-PR", "STJ REsp 1.955.422/PR"], "jurisprudence": ["REsp n. 1.999.624-PR", "REsp n. 1.955.422/PR"], "confidence": 0.8, "extracted_at": "2026-05-25T22:57:43.390274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=251", "doc_key": "8ba07fc664f804dcc7561101bddb0ee8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7eb2c1b2c0e9528e31c4365bec51a6d678b77b1f54044a64ca7efb9a400db7d9'),
  ('cpiuris2025::e78a9638b2686bb3eaecf98b39f83fd8', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos', '## Contratos

O contrato é considerado unilateral, gratuito, comutativo, real, temporário e solene. A constituição de renda deve ser feita por escritura pública.

### Conceitos
- **Unilateralidade**: Caracterização do contrato
- **Gratuidade**: Falta de valor ou consideração
- **Comutatividade**: O direito ao pagamento é transferível para outrem
- **Realidade**: Existe uma obrigação real
- **Temporariedade**: Duração limitada no tempo
- **Solene**: Caracterização do contrato

### Referências legais
- Art. 157, § 2º do CC/2002

### Dicas de prova
- Pegar a palavra ''solene'' para destacar a caracterização do contrato
- Distinção entre ato inter vivos e ato causa mortis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.251 (2)", "page_number": 251, "discipline": "Direito Civil", "legal_refs": ["Art. 157, § 2º do CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:58:17.063014+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=251", "doc_key": "e78a9638b2686bb3eaecf98b39f83fd8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3094ff3f3f55a99c6fa6ce074946cdc8cd5958482fe0b8b1fc12ab0b28425590')
